window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_019"]={"n":"徐熥","dyn":"明","poems":[{"t":"春夜同钱叔达陈惟秦斋中雨坐","f":"五言律诗","c":["高斋开乱竹，孤烛坐潺湲。","世味随年减，浮生到夜閒。","交应同白水，语不离青山。","城市红尘满，烟霞独此间。"]},{"t":"春日雨中喜惟秦至","f":"五言律诗","c":["斋居耽阒寂，犹厌鹿麋群。","茶汲松泉煮，香收桂屑焚。","避人宜昼雨，来客损春云。","不带红尘至，寥寥独见君。"]},{"t":"秋日偶成","f":"五言律诗","c":["山翠夕阳天，斋居息众缘。","倦啼将暮鸟，哀咽过秋蝉。","榻静喧松雨，窗疏纳竹烟。","微吟多信步，行到蓼花边。"]},{"t":"怨词","f":"五言绝句","c":["一从闭深宫，不复徵歌舞。","房中今夜声，是妾当年谱。"]},{"t":"汉宫春晓词 其一","f":"七言绝句","c":["长信宫中玉漏微，绿杨枝上乳鸦飞。","忽听银钥开金锁，残月楼头照舞衣。"]},{"t":"秦宫怨","f":"七言绝句","c":["宫中无复望车尘，已分阿房老此身。","纵使君王得相见，也应不爱白头人。"]},{"t":"梁宫怨","f":"七言绝句","c":["深宫长日闭苍苔，恩宠于今念已灰。","莫望他生更相见，君王行满不轮回。"]},{"t":"闽王审知墓下作","f":"七言律诗","c":["玉辇何年去不回，霸图千古总成灰。","秋深兔穴依寒垄，岁久鱼灯暗夜台。","故国关河瓯越在，遗民蘋藻鼎湖哀。","莲花峰下黄昏月，犹见三郎白马来。"]},{"t":"飞龙篇","f":"五言古诗","c":["海上三神山，中为仙人居。","金楼高崔嵬，玉堂结绮疏。","朝乘飞龙去，翱翔登鼎湖。","骋风周八极，飘飘凌紫虚。","安期同遨游，八公相为徒。","看日扶桑巅，采药昆崙区。","桑田有变迁，人世多荣枯。","安得乞灵药，蜕此凡浊躯。","一朝生毛羽，白日升天衢。"]},{"t":"秋风辞","f":"楚辞体","c":["秋风摇落兮，草木变衰。","白云缭绕兮，鸿雁声悲。","兰为佩兮，芙蓉为裳。","彼君子兮，天一方。","鼓桂棹兮，度横塘。","明星烂兮，露为霜。","歌声沸兮，夜未央。","誓与君兮，永不忘。","人生欢会兮，安可常。"]},{"t":"悲愁歌","f":"楚辞体","c":["我之生兮在深宫，嗟薄命兮事远戎。","乌孙老兮语不通，征尘起兮多悲风。","望故土兮心忡忡，羡黄鹄兮泪无穷。"]},{"t":"战城南","f":"古风","c":["战城南，死城北，枯骨累累弃路侧。","为我谓乌，游魂不归。","臭腐将焉用，饲汝安足悲。","阴云漠漠，寒雨潇潇。","黄昏古城下，新鬼声号咷。","阳九厄，战城南，空裹革。","七尺微躯我不惜，老死蓬蒿竟何益。","愿为忠臣，忠臣诚可为。","茫茫穹庐，掩骼为谁。"]},{"t":"落叶哀蝉曲","f":"楚辞体","c":["西风兮吹襟，蝉声兮满林。","古砌静而叶落，凄然感乎予心。","忆美人于闺房兮，方敛袂而沉吟。"]},{"t":"野田黄雀行","f":"五言古诗","c":["朝来步野田，田中有黄雀。","翩翩飞且鸣，饮啄亦自若。","何期侠少年，遽尔加矰缴。","置之樊笼中，絷以黄金络。","微物有至性，安能事束缚。","悲鸣念故群，所志在林薄。","感此宗庙牺，叹彼华亭鹤。","何如辞网罗，高翔在寥廓。"]},{"t":"饮马长城窟行","f":"五言古诗","c":["饮马长城窟，水深没马腹。","朝发祈连山，暮宿太原谷。","男儿事格斗，安能讳杀戮。","昨日新战败，死者什五六。","残血吹腥风，尸骸路相续。","身死自不悲，所痛在骨肉。","嗟哉杞梁妻，哀哀城下哭。"]},{"t":"铜雀妓","f":"五言律诗","c":["日暮西陵望，但见蒿与莱。","悲风起四野，歌舞有馀哀。","漳河流不返，穗帐空尘埃。","荒台久寂寞，雄图安在哉。"]},{"t":"羽林郎","f":"五言古诗","c":["昔有羽林郎，持戟出未央。","挥鞭过酒肆，招摇都市傍。","酒家女二八，颜色耀春芳。","黄金为条脱，白玉为耳珰。","越罗裁中裙，齐纨制下裳。","服饰既璀璨，膏沐尤馨香。","不意冶游子，停骖登我堂。","银鞍耀红日，韎韐何辉煌。","提壶索美酒，岸帻据胡床。","金刀脍鲜鲤，烈火炮羔羊。","酒尽出门去，婵媛结衷肠。","已去复再返，解赠紫罗囊。","君心一何苦，君情一何长。","妇人贵远别，持此非所当。","还君紫罗囊，妾非青楼倡。"]},{"t":"车遥遥","f":"五言古诗","c":["车轮何遥遥，出门不顾返。","轮岂不能回，君心自难挽。","听此辚辚声，一声一以远。","看此两行辙，能令欢爱断。","如何驭者手，不肯须臾缓。","敢望君心回，但愿车轮烂。"]},{"t":"门有车马客行","f":"五言古诗","c":["门有车马客，来从故乡陌。","乍见虽可欢，道旧反不怿。","试问旧亲宾，存亡异畴昔。","别时诸儿童，于今皆半百。","今时诸壮夫，多非故相识。","旧人居新坟，新人居旧宅。","里社既荒凉，市朝多变易。","累累丘垄间，郁郁生松柏。","离别才几时，光阴如此迫。","静言思故乡，含情泪沾臆。"]},{"t":"白马篇","f":"五言古诗","c":["谁家冶游子，捐躯事戎行。","白马黄金羁，驱驰赴朔方。","兜鍪既焜耀，宝剑生光芒。","良弓悬韎韐，激矢藏缥囊。","仰天射凫雁，俯身射豺狼。","膂力已绝世，捷黠谁能当。","边风方惨冽，壮士临风僵。","跃马入重围，生擒左贤王。","丈夫思报国，安肯思故乡。","裹尸诚所愿，毋然悲死伤。"]},{"t":"君马黄","f":"古风","c":["君马黄，臣马赤。","君马驰驱，臣马辟易。","君马登天闲，臣马伏槽枥。","二马同行，一马太息。"]},{"t":"临高台","f":"楚辞体","c":["临高台，望故乡，下有流水流汤汤。","群草委腓万木黄，翩翩南雁来回翔。","揽衣起徬徨，美人不见兮断我衷肠。"]},{"t":"怨歌行","f":"五言古诗","c":["当时匣中铜，于今翳尘土。","当时箧中丝，于今无寸缕。","磨镜休使光，缲丝休使长。","镜光惊貌换，丝长嫌绪乱。","对镜与治丝，两者俱肠断。"]},{"t":"江南弄","f":"古风","c":["冰肌皓魄红罗襦，郁金裙带悬流苏，莲舟荡漾临澄湖。","临澄湖，连臂歌，欢不来，将奈何。"]},{"t":"龙笛曲","f":"古风","c":["于阗玉管流哀音，馀音寥亮水龙吟，调繁指弱忧思深。","忧思深，涕汍澜，怀远道，催清颜。"]},{"t":"采莲曲","f":"古风","c":["兰舟容与过横塘，步摇惊起双鸳鸯，罗裙带湿生浓香。","生浓香，红汗滴，坐中流，奏龙笛。"]},{"t":"游女曲","f":"古风","c":["罗衣半褪飘金缕，约束纤腰五杂组，日暮采芳临洛浦。","临洛浦，鲜明珠，望交甫，心踟蹰。"]},{"t":"朝云曲","f":"古风","c":["朝云日日阳台上，晻暧迷茫开绮帐，襄王一去劳相望。","劳相望，梦难醒，湘水绿，湘山青。"]},{"t":"凤笙曲","f":"古风","c":["纤指按节玉参差，樱唇缓吸声迟迟，吹侬无限心中悲。","心中悲，望远情，何时吹，双凤鸣。"]},{"t":"春日白纻曲","f":"七言绝句","c":["辛夷半落桃花开，金羁宝瑟上春台。","佳人倦倚阑干曲，两两黄莺飞相逐。"]},{"t":"夏日白纻曲","f":"七言绝句","c":["绿池风来菡萏香，临流照影见妍妆。","隔花忽听郎歌调，自取齐纨障巧笑。"]},{"t":"秋日白纻曲","f":"七言绝句","c":["庭槐初落秋气深，月中玉腕捣清砧。","东家倡妇恣行乐，酒阑更说罗衣薄。"]},{"t":"冬日白纻曲","f":"七言绝句","c":["玉肌起粟寒相侵，金壶美酒对君斟。","麝兰香气罗衾满，夜长转觉氍毹煖。"]},{"t":"乌栖曲 其一","f":"七言绝句","c":["高楼四面栽杨柳，白马骊珂暂回首。","玉壶美酒任君沽，妾身十五已当垆。"]},{"t":"乌栖曲 其二","f":"七言绝句","c":["微灭银灯隔重幔，宛转娇声恣啼唤。","不辞今夕尽风流，只愁明日见君羞。"]},{"t":"乌栖曲 其三","f":"七言绝句","c":["帐中弱态含娇妩，一夜为云更为雨。","汝南鸡啼天未明，与君还尽片时情。"]},{"t":"乌栖曲 其四","f":"七言绝句","c":["月衔半岭灯将灭，罗衫掩泪送君别。","入门独自剔残灯，寻思无限夜来情。"]},{"t":"塞上曲","f":"五言古诗","c":["将军出北平，匈奴争遁走。","鼓振天地昏，令出风雷吼。","边霜裂旌旗，塞月寒刁斗。","系俘受降城，屯兵井陉口。","归来见至尊，自献单于首。"]},{"t":"白头吟","f":"五言古诗","c":["貌如雨中花，节似霜中柏。","貌改节不移，别君意悽恻。","妾心如女萝，君情如飞絮。","萝生空缠绵，絮飞何处去。","嫁君当红颜，辞君当白首。","请君看镜中，双鬓何如旧。","死树难再荣，死灰难再热。","寄语新欢人，莫遣头如雪。","含悲下中堂，此情空脉脉。","君心能再回，白头应再黑。"]},{"t":"捣衣篇","f":"五言古诗","c":["皎月入房帷，凉风吹衣襟。","游子远行役，少妇鸣清砧。","良夜既以永，怀人益以深。","孤鸿唳天际，促织吟堂阴。","余亦别家久，涕泣不能禁。"]},{"t":"妾薄命","f":"五言古诗","c":["南国有佳人，容华世莫比。","嫁与东邻儿，愿言结生死。","良人轻别离，匆匆辞故里。","朝醉阊阖门，暮宿长安市。","新爱移平生，恩情付流水。","欲促远人归，裁书寄双鲤。","遗之同心结，兼以合欢被。","人匪金石坚，容颜何足恃。","天涯君不归，河清难再俟。"]},{"t":"有所思","f":"五言古诗","c":["徙倚向花丛，罗衣湿清露。","乌鹊隐茂林，寒蝉抱高树。","焚香理素琴，聊以抒心愫。","美人期不来，中宵泪如注。","月色满花阴，花阴空伫立。","何以赠所驩，悲歌聊当泣。","啾啾阶蛩吟，喔喔邻鸡急。","幽会杳无期，空令长太息。"]},{"t":"拟古 其一","f":"五言古诗","c":["把袂登河梁，秋风惨行色。","去去天一涯，此心长恻恻。","酒殽纷错陈，哽咽不能食。","思君有梦魂，从君无羽翼。","浮云方西驰，羲轮忽已匿。","微款俱未伸，相持空太息。","会面未有期，功名当努力。"]},{"t":"拟古 其二","f":"五言古诗","c":["落日不回照，颓波无西流。","人生处世间，倏忽如蜉蝣。","百年伤局促，其忧乃千秋。","一朝时命尽，悲风起松楸。","累累丘土中，谁辨王与侯。","贵亦不必喜，贱亦不必忧。","圣贤多微言，达者聃与周。","斗酒相娱乐，虚名安足谋。"]},{"t":"拟古 其三","f":"五言古诗","c":["闺房何凄清，思君意如捣。","追恨当别时，光景太草草。","愁款积胸臆，恍惚不能道。","别君未须臾，依然结怀抱。","安得回君车，与君再倾倒。"]},{"t":"拟古 其四","f":"五言律诗","c":["徙倚高楼上，西北多浮云。","浮云望不极，妾泪徒纷纷。","丈夫思报国，仗剑远从军。","十年辽水上，生死不相闻。"]},{"t":"拟古 其五","f":"五言古诗","c":["洛阳有异卉，灼灼生路傍。","颜色如朝霞，百步闻馨香。","五陵多游冶，观者如堵墙。","竟日欢不足，秉烛飞羽觞。","凉秋降白露，气序回清商。","嗟哉此异卉，倏忽无辉光。","容华不足恃，欢爱靡故常。","因之感薄俗，意绪重惨伤。"]},{"t":"感遇 其一","f":"五言古诗","c":["山居绝尘鞅，众虑寡所营。","长啸谷声应，抚琴薰风生。","云流古洞湿，雨过寒潭清。","年光自代谢，草木随枯荣。","且尽杯中酒，遑图身后名。"]},{"t":"感遇 其二","f":"五言古诗","c":["出门尽秋色，策杖登寒山。","云来幽径迷，风急衣裳单。","林深豺虎嘷，洞古虬龙蟠。","路远人烟绝，日昃不得餐。","蒿藜蔽田野，中心自悲酸。","嚱吁望绝巘，始知行路难。","不如归林卧，长啸赋猗兰。"]},{"t":"咏荆轲","f":"五言古诗","c":["荆卿一剑客，击筑游燕都。","许身太子丹，生死誓不渝。","文夫报知己，何惜此微躯。","悲歌度易水，慷慨自驱车。","匕首中铜柱，非由剑术疏。","报秦虽不济，千载仰雄图。"]},{"t":"薤露","f":"五言古诗","c":["日出何杲杲，薤露不长保。","人生在世间，岂能长寿考。","穰穰陌上尘，离离坟畔草。","殇子与彭篯，胡然较迟早。","瞻彼薤露晞，感叹伤怀抱。"]},{"t":"咏怀","f":"五言古诗","c":["岁序如转毂，一去无还期。","形容久不逮，临镜始叹悲。","悠悠梦寐间，觉寤何其迟。","处世三十年，履历多险巇。","世事古犹今，此意当自知。","奈何微脆躯，与俗争奔驰。","奔驰觉生累，守静性可怡。","老庄有明训，役役将何为。"]},{"t":"与陈汝大鳌峰宴集 其一","f":"五言古诗","c":["四郊散秋色，层台结夕阴。","孤磬出丛薄，倦鸟投故林。","残霞落酒杯，微月照衣襟。","良朋式至止，临风谐赏心。","既蜡阮生屐，复为梁父吟。","■然发长啸，天外有馀音。"]},{"t":"与陈汝大鳌峰宴集 其二","f":"五言古诗","c":["振衣陟鳌顶，石磴何嵬峨。","松阴如车盖，亭亭山之阿。","深岩逗秀色，古树垂女萝。","醉来穷幽壑，勃窣经危坡。","孤鸿唳天际，野鸟当筵歌。","人生寡良和，不饮将如何。"]},{"t":"游圆峰阁","f":"五言古诗","c":["古阁枕溪滨，年代已湮没。","山势何嶙峋，溪声无停歇。","老树倚云根，寒泉溜山骨。","我来陟孤岑，石径苍苔滑。","朝餐岭上霞，夜漱波心月。","处处烟景移，步步清兴发。","临风开素襟，空山坐超忽。"]},{"t":"东际亭晚眺","f":"五言古诗","c":["虚亭苍翠间，烟霞变奇景。","微钟起梵音，空潭自清影。","行来竹霭深，坐久松风静。","冥然道心生，倏尔尘缘屏。","吟眺犹未阑，残阳在西岭。"]},{"t":"拟登天台山","f":"五言古诗","c":["晨兴理轻策，扪萝登嶕峣。","荒榛隐烟雾，绝巘摩穹霄。","泉声洒飞瀑，山容建霞标。","下有百丈潭，泠泠喧石桥。","凉燠异岩壑，雨旸变昏朝。","遐瞩发清旷，溽暑生凉飙。","偓佺讵云远，羡门犹可招。","骋此物外观，听彼云中谣。","微风奏天籁，淡云缀轻绡。","结根比华岱，幽邃同中条。","高情豁然畅，尘襟亦已消。","安得遇至人，与之同逍遥。"]},{"t":"春泛若耶","f":"五言古诗","c":["春风散藻景，山水动微暄。","桂棹泛兰渚，摇摇过前川。","汀花媚幽壑，岸柳垂轻湍。","环洲屡回复，杂树何缤纷。","微波生镜湖，疏钟来云门。","扬帆意超忽，溯流情孤鶱。","逆楫芰荷脆，随波兰芷繁。","和风驻瑶瑟，落日沉金尊。","山川缅如故，畴昔谁能存。","佳境岂易觌，幽怀愿无谖。"]},{"t":"怀陈平夫","f":"五言古诗","c":["别子虽未久，念子意何深。","揽衣立阶除，凉风吹素襟。","残钟度微月，天籁杂悲吟。","盈盈一水隔，悠悠千里心。","空山白云满，六溪何处寻。"]},{"t":"寄题林晋伯别墅","f":"五言古诗","c":["夫子且遁世，结庐居青门。","鸣泉泻悬崖，山光当层轩。","澹澹云影疏，谡谡松声繁。","林密失寒燠，山深忘朝昏。","薄田足禾黍，幽涧多芳荪。","柴门瞰清溪，一径通花源。","时时命小舟，去去过前村。","惬此丘中赏，忘彼朝市喧。","伊余秉微尚，委怀在丘园。","安得相比邻，长啸醉山樊。"]},{"t":"登鼓山大顶","f":"五言古诗","c":["晓望屴崱峰，振衣涉蓁莽。","树色远葱茏，练瀑空中响。","峭壁插苍穹，丹崖悬百丈。","鬼斧凿鸿濛，玄岩閟罔两。","我来叩崆峒，素心怀孤往。","萝蔓刺衣裾，烟霞随屦杖。","倚石漱清流，顿令神骨爽。","薄暮日渐暝，月印苍苔上。","忽闻天籁鸣，泠泠惬心赏。","愿言脱尘缨，不复絓世网。"]},{"t":"赠陈价夫荐夫","f":"五言古诗","c":["明珠无连胎，奇卉寡并蒂。","物类有如此，无乃造化忌。","夫何六溪中，产君兄与弟。","意气倾时流，词华振当世。","顾盼生雄姿，中原敢凌厉。","探讨无勌勤，玄心已超诣。","二陆久不兴，芳名尔当继。"]},{"t":"剑浦送顾世卿","f":"五言古诗","c":["行行出剑津，送君还东吴。","未能展嬿婉，别离在须臾。","含涕牵君衣，相视意踟蹰。","我无双飞翼，何由与君俱。","君行登青云，我尚蟠泥途。","相隔天一方，道路阻且迂。","会面虽有期，秖恐容华殊。","悲风振原野，怪鸟争哀呼。","送君从此去，回首日云晡。"]},{"t":"晚渡淮水","f":"五言古诗","c":["孤帆涉淮水，天气苦寒冱。","积雪明长崖，斜阳横古渡。","渔灯隔浦来，人烟数家聚。","前途多风尘，故山隔云树。","栖栖问去津，悠悠叹行路。","远涉犹未穷，徘徊日将暮。"]},{"t":"田家杂兴","f":"五言古诗","c":["春风动郊墟，村村事农务。","桑柘荫比邻，鸧鹒鸣高树。","访旧入城稀，持馌归田暮。","鸡犬识井闾，牛羊谙村路。","此中寡所营，悠然有真趣。"]},{"t":"憩转华庵","f":"五言古诗","c":["精庐傍人境，虚寂无垢氛。","食施隔林鸟，衲挂前山云。","池光既澄洁，香气尤氤氲。","猕猴识戒律，狸犬嫌腥荤。","谈深不顾返，西岭将斜曛。","终当远城市，高卧辞人群。"]},{"t":"对月迟王元直不至","f":"五言律诗","c":["孤馆寂无人，寒威满林樾。","天长雁影迟，露冷蛩声歇。","当尊翠霭深，倚杖苍苔滑。","故人期不来，惆怅花间月。"]},{"t":"春日山居招袁无竞","f":"五言律诗","c":["晨起倦簪沐，便觉日停午。","梁间燕哺雏，竹外鸠呼雨。","碧藓盈阶除，幽花映窗户。","裁诗招所驩，愁心绕烟树。"]},{"t":"送郑业师之汉阳","f":"五言古诗","c":["春风吹柳枝，处处鸣鶗鴂。","七十四老翁，犹作天涯别。","若比少壮游，此情倍呜咽。","贫来褐不完，老去头如雪。","游非尚子怀，辩岂君卿舌。","出门靡所甘，苦为饥寒迫。","湘江道路长，楚水烟波阔。","兹行毋滞淫，门人望回辙。"]},{"t":"怀陈履吉久居山中","f":"五言古诗","c":["闻君居荒村，寥寥谁与侣。","田叟时往还，樵夫或共语。","吟思倚杖时，钓忆临流处。","高怀绝世氛，閒心寄烟渚。","此别已徂秋，凉风满庭树。"]},{"t":"怀沈从先","f":"五言古诗","c":["与君未倾盖，吴门费相寻。","十日不能得，嗟哉谁知音。","故人不我弃，题书贻空林。","感此岁月异，伤兹年鬓侵。","寥寥千古意，悠悠万里心。","花残吴苑暮，月落枫桥阴。","望君不可见，思君空自深。"]},{"t":"答葛震甫","f":"五言古诗","c":["闽海与吴门，相隔几千里。","君虽吴门居，又隔洞庭水。","不知贱子名，何由入君耳。","云中有片鸿，江头足双鲤。","投来皆璚瑶，报之愧兰芷。","临风怀美人，感叹胡能已。"]},{"t":"慰佘宗汉丧子","f":"五言古诗","c":["一官不称意，拂衣游五湖。","书空羞咄咄，对酒呼乌乌。","行年已半百，有子啼呱呱。","丈夫耻内顾，仗剑遵长途。","及君还故里，岁月已云徂。","此儿风格异，蹀躞称家驹。","膝前还复著，鲤庭时能趋。","昨日致书来，云君殒其雏。","知己为痛悼，坐客同嗟吁。","有生本非有，无生亦非无。","达生乃贤者，西河非吾徒。","君今丧子后，还如无子初。","金石有销铄，况此脆弱躯。","古人齐彭殇，此意良非迂。","造化诚小儿，无为此拘拘。"]},{"t":"哭林逊肤先生","f":"五言古诗","c":["先人同时交，什九泉下尘。","遗老独有君，倏然返其真。","君今归黄垆，不患无所亲。","世上少相识，泉下多故人。","生交有聚散，死交千万春。","死者足相乐，生者徒悲辛。"]},{"t":"喜微师自水西归","f":"五言律诗","c":["开士从何来，云自山中归。","去住无定迹，有如閒云飞。","随方皆净土，何处非禅机。","城市虽红尘，不染静者衣。"]},{"t":"赋得华林暮雪","f":"五言古诗","c":["屏山何逶迤，精庐依北郭。","日暮寒风生，旷野同云作。","俄看雪片繁，渐觉襌衣薄。","瑶华结珠幡，玉屑飘金铎。","跏趺双树林，疑是天花落。"]},{"t":"望月有怀唐宗贞陈彦宗","f":"五言律诗","c":["微月入庭除，疏松散清影。","山深岚翠浓，露落衣裳冷。","当时月下人，踪迹同萍梗。","对月思所驩，此情空耿耿。"]},{"t":"剑浦送康元龙游吴","f":"五言律诗","c":["余自吴门归，君望吴门去。","来往本无期，延津忽相遇。","一望故山云，一问他乡路。","语罢各分离，愁心满烟渚。"]},{"t":"听陈振狂弹琴因怀刘道子","f":"五言律诗","c":["夜坐松桂丛，孤琴理残月。","流泉澄幽阴，微风助清越。","愁因寄指深，兴以馀音发。","悠然山水心，怀人向天末。"]},{"t":"南屿田家 其一","f":"五言古诗","c":["绿水荫柴门，苍山绕茅屋。","老树鸣春鸠，颓垣眠小犊。","鹅鸭自成群，儿童戏相逐。","游从里社归，税藉农桑出。","荣辱非所知，饱煖愿已足。","羲皇世代遐，此地传遗俗。"]},{"t":"南屿田家 其二","f":"五言古诗","c":["空山布谷鸣，春风散墟落。","夫妻同荷锄，南亩事东作。","衡门隐者居，斗酒田家乐。","閒惟念子孙，老不知城郭。","安能受一廛，鼓腹同耕凿。"]},{"t":"宿云窝赠林熙吉","f":"五言古诗","c":["吾党有一士，结茅岘山麓。","庭前罗异卉，屋后绕脩竹。","托迹在岩丘，结交尽麋鹿。","水石同弟昆，农桑课童仆。","时为梁父吟，閒取离骚读。","服食惯参苓，往来狎绮角。","能忘朝市喧，不与世情逐。","谁知锦水滨，却有愚公谷。","朴被时一来，同抱孤云宿。"]},{"t":"怀陈惟秦","f":"五言古诗","c":["相思一何深，相别一何久。","条风吹蘼芜，新火钻榆柳。","春光渐以阑，莫负尊中酒。"]},{"t":"题王玉生山水","f":"五言古诗","c":["辋川迹已陈，千载寡奇笔。","王生嗣其徽，少负山水癖。","寸颖幻烟霞，尺素生泉石。","古木荫溪湄，虚亭倚山隙。","一径转危冈，两岸分泉脉。","澹澹柘林黄，萧萧枫树赤。","岩壑互向背，云阴变朝夕。","人境信有之，愿言卜丘宅。"]},{"t":"猛虎行","f":"五言古诗","c":["上山采蘼芜，下山采蘼芜。","采采犹未已，白日将崦嵫。","归来逢猛虎，咆哮当路隅。","徬徨何所之，林莽多人居。","岂无桑间人，轻薄同秋胡。","此身虽可噬，此节安可渝。","甘心饲猛虎，矢志同罗敷。"]},{"t":"寄林去疾","f":"五言古诗","c":["相闻十馀载，相隔三百里。","君瞻鳌顶云，我梦鲤湖水。","何以赠所欢，因风寄兰芷。"]},{"t":"酬陈汝大","f":"古风","c":["曰余少肮?，寝迹山泽间。","世路罕所营，翰墨聊为驩。","结交二三子，气味芬若兰。","道谊互相砥，文章时往还。","所嗟非比邻，别易会良难。","君其勖诸子，令名当自完。","继之既以逝，大雅声云残。","吾党嗣遗音，矢志回狂澜。","旗鼓渐以振，逸轨尚可攀。","景光幸自爱，勉旃毋多谭。"]},{"t":"寄李惟实","f":"五言古诗","c":["岭南多畸人，李君称俶傥。","神锋既俊逸，胸怀尤爽朗。","弱冠奋青云，声华满天壤。","诗宗大历前，文轶班扬上。","足迹半四方，游道渐以广。","倾盖在都门，投分慰心赏。","敝帚安足珍，乃获千金享。","易水赋离歌，中心发悲怆。","归卧空山中，犹作真人想。"]},{"t":"贻陈汝翔","f":"五言古诗","c":["柯屿山水奇，之子钟灵秘。","吾党推白眉，词坛标赤帜。","衡门可栖迟，丘园还自贲。","服食采三秀，衣裳裁薜荔。","天倪既已和，纯白无不备。","但作襧衡狂，不下杨朱泪。","暌违日以长，临风思把臂。"]},{"t":"酬陈伯孺春日见访之作","f":"五言古诗","c":["予宁不得意，幽居嗟陆沉。","稚子门外呼，有客来相寻。","论心意已惬，握手情何深。","新诗馀万言，居然正始音。","谈深梅雨歇，坐久春鸠吟。","日暮别我去，怅然劳此心。"]},{"t":"五君咏 其一 陈汝大","f":"五言古诗","c":["汝大长者流，涉世嗟不偶。","玄牝有精诣，黄庭能自守。","混迹居泥途，飘然出尘垢。","作赋馀万言，读书穷二酉。","振响主词盟，伊余忝其后。","非博生前名，所志在不朽。"]},{"t":"五君咏 其二 陈汝翔","f":"五言古诗","c":["汝翔好奇古，遁迹在柯屿。","词藻何离离，才情尤楚楚。","能追正始音，不作齐梁语。","臭味既已同，素心自相许。","睽乖劳我思，山中正延伫。"]},{"t":"五君咏 其三 陈平夫","f":"五言古诗","c":["平夫貌不扬，意气何卓荦。","耻抱齐门竽，甘作荆山璞。","诗解匡生颐，谈折充宗角。","一饮动百巡，贤圣分清浊。","古道信寡谐，正音久辽邈。","努力崇令名，典籍有先觉。"]},{"t":"五君咏 其四 陈伯孺","f":"五言古诗","c":["伯孺秉异姿，弱冠富经籍。","拓落守太玄，异同辨坚白。","作赋已驰名，耽奇自成癖。","丹青发妙赏，磊磊生泉石。","把臂结词盟，微悰永无斁。"]},{"t":"五君咏 其五 陈幼孺","f":"五言古诗","c":["荐夫意气豪，逢人作白眼。","冥心契道诠，矢志稽坟典。","伯仲既齐名，君才良不忝。","大雅久沉沦，俯仰知音鲜。","凌厉向词坛，片语人矜善。","结志在千秋，令名尔当勉。"]},{"t":"赴京道中寄惟起惟扬二弟 其一","f":"五言古诗","c":["我行值炎暑，倏忽还徂秋。","眷言念同气，惄然生百忧。","驰晖不可驻，逝水无停流。","感兹岁月驶，怅以道路脩。","悲端起中夜，梦寐居林丘。"]},{"t":"赴京道中寄惟起惟扬二弟 其二","f":"五言古诗","c":["林丘渺何许，远在鳌峰麓。","参差多岩峦，蒙笼匝花竹。","遗踪追考槃，高吟动淇澳。","一落尘网中，与世相徵逐。","俯仰思故园，悽风满愁目。"]},{"t":"赴京道中寄惟起惟扬二弟 其三","f":"五言古诗","c":["愁目不可极，怅望心魂惊。","仳离足感叹，况乎骨肉情。","愁多无定绪，路远难计程。","危时幽愤积，逆旅孱躯轻。","凉风天际来，呖呖哀鸿鸣。"]},{"t":"赴京道中寄惟起惟扬二弟 其四","f":"五言古诗","c":["鸿鸣一何哀，客心一何苦。","昨发濲溪滨，今宿桐江浒。","平沙翻惊飙，崩崖荡零雨。","中宵蚊蚋喧，白昼冯夷舞。","嗟哉行路难，含悲望乡土。"]},{"t":"赴京酬陈汝大见送之作","f":"五言古诗","c":["羲轮转南陆，天气何郁蒸。","驾言出江泛，婉娈辞良朋。","握手长太息，涕下同沾膺。","伊余下乘资，致远胡能胜。","临觞发丽藻，要我以飞腾。","匪惟缱绻笃，徒令感叹增。","小石无完璞，勺水无坚冰。","既愧明德茂，敢期勋业弘。","三复君子言，旦夕怀冰兢。","芳规在往哲，努力将凭陵。"]},{"t":"答袁无竞","f":"五言古诗","c":["乍别已不欢，久别情转恶。","凄凄零雨濛，郁郁炎蒸烁。","遵途忧风波，对境怀丘壑。","濡毫无妙理，把酒强为乐。","遐心寄兰荃，秋阴生杜若。","缅怀挥袂初，风景宛如昨。","远道伫徽音，高标忆河朔。"]},{"t":"苕溪送元直南还","f":"五言律诗","c":["送客情已悲，何当更送汝。","送汝情已悲，何当在逆旅。","此情各自知，临行复何语。","握手立斯须，相看泪如雨。"]},{"t":"长安书怀孟郊体","f":"五言古诗","c":["烛灭方知黑，其明同瞽师。","脉绝方知死，安得称良医。","文章屡弃置，犹有俗所嗤。","弹射岂不精，所惜觉悟迟。","得失论工拙，胜负分雄雌。","世无鲍叔牙，此意谁能知。","家山八千里，策马燕风悲。","中情徒郁结，泠泪空双垂。"]},{"t":"丧车行","f":"五言古诗","c":["岁序当杪冬，鸡鸣闻巷哭。","填衢广柳车，载道残魂木。","哀哀薤露声，炯炯方相目。","骨肉有馀悲，亲朋寡颦蹙。","当其在世时，营营苦不足。","百年同隙驹，一梦同蕉鹿。","灵爽归山丘，枯髅别华屋。","城郭不相容，弃之邙山麓。"]},{"t":"初夏邀黄仲高孝廉张孺愿太学钱叔达山人张公鲁徐仲和秀才及社中诸子集澄澜阁","f":"古风","c":["良辰集群彦，暂谢区中缘。","驾言出西郭，飞觞湖水瀍。","澄澜敞高阁，峰阴流绮筵。","丹嶂互隐伏，粉堞相回旋。","依岸垂柳密，出水新荷圆。","珍禽响丛薄，锦鳞沉深渊。","芳思结瑶草，清音鸣朱弦。","愿以桂楫汎，同将兰?搴。","风和岚翠燠，日落暮景延。","幽赏既已惬，旅怀由兹宣。","白驹聊可絷，奉君终岁年。"]},{"t":"送黄明立北上","f":"五言古诗","c":["路远无倦蹄，天长无倦翼。","千里始停御，九万方一息。","未骋康庄途，终当受衔勒。","未能抟扶摇，安得惜羽翮。","之子腰袅姿，兼负鹍鹏力。","行将垂青云，非久困槽枥。","一去登天闲，且向南冥适。","飞腾自有期，临岐免悽恻。"]},{"t":"下第述怀","f":"五言古诗","c":["匠石屡不顾，定匪明堂材。","渊客屡不采，定匪明月胎。","十年三弃置，中情空自哀。","伤哉吾道非，岂乏干时媒。","叹彼行役苦，畏兹年鬓催。","进退两踯躅，坐立空徘徊。","升斗岂吾志，结念居南陔。"]},{"t":"游铅山观音洞","f":"古风","c":["高秋出郭门，名区访灵鹫。","径路既逶迤，林峦错如绣。","怪石竞瑰琦，奇峰自辐辏。","玲珑似雕镂，?砑欲争斗。","倚伏形体殊，剥蚀肤理皱。","中有大士岩，丹梯转深窦。","窍从混沌开，屋以穹窿覆。","诸厓地脉藏，一隙天光漏。","巍巍逼苍旻，阴阴失清昼。","澄泓嵓罅停，琮琤石齿溜。","宁云蓬岛遥，应笑华阳陋。","造化播神奇，此理胡能叩。","低回及崦嵫，岚翠生怀袖。"]},{"t":"桑溪禊饮诗二首 其一","f":"古风","c":["春风载柔，遵彼长林。","我有旨酒，与子同斟。","幽怀既惬，玄想弥深。","悠悠逝波，实怆我心。"]},{"t":"桑溪禊饮诗二首 其二","f":"五言古诗","c":["暮春有馀閒，出郊骋游目。","桑溪激清湍，澄泓递洄洑。","微暄起川涘，轻阴垂灌木。","群贤互箕踞，浮觞溯溪曲。","周遭信堤岸，斟酌劳童仆。","石矗防仄倾，流驶虑颠覆。","幽赏豁尘襟，馀芗散春服。","尊罍犹未罄，羲轮欲回毂。","俯仰成古今，动静悟往复。","谁哉契我心，兰亭有高躅。"]},{"t":"题陈伯孺画","f":"五言古诗","c":["群山既葱茏，诸溪何蜿曲。","孤亭倚高冈，人家荫乔木。","苍松盘路岐，危桥度空谷。","地僻无冬春，山深绝寒燠。","乘閒问友生，策蹇劳童仆。","步步出烟云，悠悠入花竹。","潺湲满清听，空翠生巾服。","閒身寄林丘，野性谐麋鹿。","瞻彼城市中，风尘空碌碌。"]},{"t":"帝京篇","f":"古风","c":["文皇定鼎都燕蓟，三辅黄图誇壮丽。","九重宫阙何嵯峨，百二山河咸拱卫。","五凤高楼逼太清，六龙御宇泰阶平。","曈昽晓日升金阙，缥缈红云拥玉京。","玉京金阙倚天开，隐隐銮舆复道来。","云迷翠幰依龙衮，露滴金茎泛羽杯。","平明长乐钟声响，九天日月开仙仗。","豸史台中晓听乌，虎贲阶下朝鞭象。","月照彤墀环佩齐，风生青琐旌旗飏。","高台突兀比章华，上苑纡回同博望。","我家京洛何煌煌，山河锦绣轶隋唐。","断发文身俱稽颡，雕题黑齿尽梯航。","三载公车计偕吏，严乐邹枚乘传至。","黄纸承恩金马门，绿衣锡宴慈恩寺。","敕赐当街上五花，金鞭络绎更堪誇。","市中春色浓如锦，身上宫袍烂似霞。","妆台舞榭层云里，粉白蛾黄兼皓齿。","怙宠翻令女伴憎，承欢却得天颜喜。","更有中涓美少年，朱颜白晰珥貂蝉。","当筵解唱霓裳曲，出直常挥碧玉鞭。","一代豪华称戚里，回天转日谁能比。","薄暮酣歌阊阖门，平明取醉新丰市。","繁华三五上元灯，蜀锦吴绫结作棚。","任从玉漏催银烛，不顾银河转玉绳。","马上佳人金络索，筵前公子玉壶冰。","悬得华灯灯七宝，搆成绮阁阁千层。","中宵露冷罗衣湿，姣童两两当筵立。","夜永宁愁凤脑残，宠移岂顾龙阳泣。","侯家绣柱玉盘龙，朝朝鼎食奏歌钟。","翠翘金凤三千队，画阁雕阑十二重。","绣枕春宵开菡萏，罗帏夜月绚芙蓉。","五侯七贵豪华客，油壁香车过柳陌。","花前调笑片时春，百万黄金轻一掷。","春风日日恣遨游，北里南邻乐未休。","玉颜到处堪回辙，珠箔谁家不上钩。","青钱多买醉，红袖暗藏阄。","投来青玉案，费尽锦缠头。","蹁跹红袖人如玉，艳舞娇歌欢不足。","琥珀深杯醉玉楼，珊瑚宝树罗金谷。","灼灼桃花两颊红，娟娟柳叶双眉绿。","愁萦弱水远重重，梦绕巫山高六六。","王孙公子好游閒，往来射猎向西山。","驱将鹰犬垂鞭去，射得狌狸带箭还。","九衢三市相迤逦，车尘白日连天起。","六郡良家尽锦衣，四方贾客多纨绮。","锦衣纨绮竞豪奢，结侠追欢意气赊。","论交半是萧朱辈，托命多于赵李家。","华堂宴会春风绕，一派弦歌声袅袅。","香气频闻宝鸭薰，漏声忘却铜龙晓。","春来春去自年年，听尽笙歌与管弦。","但知芳草春风满，谁识莺花岁序迁。","自古奢华岂能久，转眼红颜成白首。","往日堂前罗异花，于今门外生衰柳。","世事悠悠未可知，桑田沧海须臾期。","金张许史今何处，富贵骄奢空尔为。"]},{"t":"听莺曲","f":"古风","c":["条风淡荡春将半，倚栏忽听莺声乱。","隔竹绵蛮别样啼，绕林睍睆相呼唤。","相唤相呼不住声，声声偏动冶游情。","王孙载酒青楼醉，美女寻芳紫陌行。","青楼紫陌春风遍，一种娇声千万变。","彷佛秦筝出谷闻，依稀羌笛随风啭。","秦筝羌笛韵悠扬，几处欢娱几断肠。","闺中少妇悲征戍，路上行人忆故乡。","故乡渺何许，莺声何太苦。","征戍隔辽阳，闻莺空自伤。","莺来莺去自年年，听此啼声倍可怜。","百年愁鬓声中改，九十春光舌上迁。","莫叹韶华如转毂，爱莺且赋听莺曲。","但得长闻柳外声，何辞频进杯中醁。"]},{"t":"送远曲","f":"七言律诗","c":["津亭下叶纷如雨，客子远游何处所。","悠悠一别无还期，相对悲啼不能语。","此去山中经几万，劝君惟有加餐饭。","须臾分手各东西，犹听前林征马嘶。"]},{"t":"别离曲","f":"七言古诗","c":["丝缰白马黄金勒，仆御门前苦促逼。","叮咛握手暂踌蹰，欲住须臾竟不得。","心知此别无还期，犹问君归是几时。","心知此别书难寄，犹问征鸿何日至。","为君整辔君上鞍，频频勒马回头看。","无情马足如飞电，路转桥回君不见。","归来妆阁双泪垂，此身误嫁游侠儿。"]},{"t":"寄衣曲","f":"七言古诗","c":["流黄机上鸳鸯锦，明灭疏灯照孤枕。","空闺冷月自娟娟，绝塞金风何凛凛。","起视明河漏已残，沙场遥望路漫漫。","罗帏锦帐人何在，毳幕毡裘地更寒。","手剔残灯取刀尺，制得征衣寄征客。","去年寄去无回音，此日无由识宽窄。","宽窄如今未可知，几回欲剪又迟疑。","金刀未下肠先断，弱线初缝泪自垂。","泪垂点点俱成血，污在征衣不能灭。","殷勤为拭衣上痕，恐令孤客添愁绝。","掩泪裁衣远寄将，妾身不及此衣裳。","衣裳犹得亲君体，贱妾空居天一方。"]},{"t":"汲井曲","f":"七言律诗","c":["银床斜压梧桐井，牵动残丝五色绠。","臂捲罗绡宝钏高，波凝玉乳金瓶冷。","沈沈鸭绿浸鸦黄，辘轳一声愁断肠。","碎光摇动阑干湿，草根滴露阴蛩泣。"]},{"t":"秋夜曲","f":"七言古诗","c":["画幕含春度清吹，高烧绛蜡金盘腻。","铜龙滴露夜声沈，老兔崩云秋影坠。","银筝断续檀槽语，紫雾迷濛罩金缕。","蝉衫麟带委罗屏，枕花湿透巫峰雨。","牵丝晓井啼乌急，寒螀吊月香兰泣。","红光渐射菱花台，又拂娇蛾写春碧。"]},{"t":"老将行","f":"七言古诗","c":["老夫元是良家子，少年流落戎行里。","能将一剑净烟尘，几入重围身不死。","累累金印肘间悬，塞上驰驱五十年。","已羡功勋载盟府，久看姓字书燕然。","一朝谢病归岩壑，门外萧条可罗雀。","身经百战未龙钟，犹向人前誇矍铄。","宝剑年多锋锷销，枥中老骥鸣萧萧。","戎衣挂壁成尘土，旧日红旗颜色凋。","一自投閒经几载，请缨壮志还应在。","遥望沙场愿裹尸，犹思铜柱标炎海。","锋镝今年去备边，连营烽火通甘泉。","多少材官俱束手，无人贾勇能登先。","将军闻此气勃勃，目眦裂尽冠冲发。","便往投书献至尊，雄心誓欲探虎窟。","据鞍顾盼出辕门，垂老还堪报主恩。","但令此去清沙漠，不管金鎗臂上痕。"]},{"t":"北邙行","f":"七言古诗","c":["洛阳城外邙山麓，旧鬼哀呼新鬼哭。","黄昏髑髅作人语，白昼乌鸢攫人肉。","新坟古冢争嵯峨，世间人少北邙多。","北邙山中松柏树，听尽车前薤露歌。","人生处世多辛苦，贤愚贵贱同抔土。","不如归去学还丹，丹成白日生羽翰。"]},{"t":"结交行","f":"古风","c":["酌君金兕觥，听我结交行。","今人结交只结面，三杯浊酒倾生平。","酒酣拔剑多意气，死生患难毋相弃。","出门酒醒各东西，此情便已生同异。","结交难，重可悲，人情反覆谁能知。","笑谈各已藏矛戟，对面真如隔九疑。","君不见陈馀与张耳，当年刎颈徒为尔。","又不见鲍叔与夷吾，千载相知能有几。","仇隙多生谑浪间，睚眦起在刀锥里。","翟公宾客竟如何，一旦门前张雀罗。","田文座上客常满，一朝失势皆分散。","结交行，难重陈，世途处处皆荆榛。","今朝相对且饮酒，明日悠悠行路人。"]},{"t":"猛虎行","f":"楚辞体","c":["樵采当荒郊，林皋猛虎声咆哮。","欲往避之，日在崦嵫，旷野啼䲭鸮。","四顾徬徨而股栗，猛虎张颐展爪扑人食。","余告虎：“吁嗟麟兮，不食生物践生草。","尔虎白额斑狸而黑文，貌岂不如麟，胡为不仁而扑我。","”猛虎前致词：“我虎居深村，饥来啖牛羊。","牛羊啖不足，方思啖人肉。","人居城市与人伍，扑食同类何可数。","谁言虎猛能咥人，世人之猛过于虎。","”"]},{"t":"侠客行","f":"七言古诗","c":["两人市中相耳语，欲报深雠谁敢去。","壮士闻之气郁陶，平生侠烈同荆高。","发上指冠泪如雨，借问君雠在何许。","一剑朝辞都市傍，素车直指邯郸路。","刺杀雠人函首归，争看颈血犹沾衣。","主人欲奉千金报，问以姓名终不告。","辞君跃马出都门，君但报雠毋报恩。"]},{"t":"去妇词","f":"七言古诗","c":["红妆洗尽颜憔悴，一片愁心几行泪。","良人重色轻别离，旧日恩情顿相弃。","含悲含怨出深闺，宛转踌躇更惨悽。","枝头菡萏分连理，枕上鸳鸯散并栖。","鸳鸯菡萏归何处，十载绸缪今别去。","往事翻同坠井瓶，馀生却类飘风絮。","忆昔当年初嫁君，明珰翠袖红罗裙。","帐开绮阁连宵月，梦绕巫山一段云。","荏苒光阴如转毂，人情日久多翻覆。","薄命从来怨玉颜，娇姿一旦辞金屋。","万转千回不下堂，悲啼那忍别姑嫜。","君恩似水终难返，妾意如胶讵敢忘。","心知别去难重见，手把君衣苦留恋。","此生无计入君家，芳魂愿化孤飞燕。"]},{"t":"筑城词","f":"七言古诗","c":["丁夫抱杵城头筑，朱颜少妇城边哭。","哭声未绝城已崩，无数丁夫遭杀戮。","杀戮丁夫就此埋，半为黄土半人骸。","长城未毕山东乱，四海纷纷归楚汉。","吁嗟吕政胡为乎，亡秦乃在废扶苏。"]},{"t":"古战场","f":"楚辞体","c":["汉家将军猛如虎，手执长殳腰大斧。","白首从征恨数奇，可怜性命轻如羽。","鼓声死兮弓绝弦，狼奔鼠窜无行伍。","良家百万试锋铓，枯骨如山委黄土。","燐火星星点白杨，黄云漠漠依边树。","千载犹闻战血腥，夜深不禁啼猿苦。","魑魅山魈当路号，哀声长乱黄昏雨。","游魂难返玉门关，怨魄年年成杜宇。"]},{"t":"古别离","f":"古风","c":["君身如车轮，去去无回辙。","妾泪如井泉，涓涓滴不竭。","欢爱能几时，伤哉此离别。","萧萧征马向人嘶，欲别未别心惨悽。","深闺不识天涯路，但向门前看马蹄。","送君试折长堤柳，立马踌蹰岂能久。","明年柳发今年枝，还记今年送别时。"]},{"t":"征妇怨","f":"七言律诗","c":["今年贼陷临洮府，杀死官军何可数。","征夫塞外骨成山，少妇闺中泪如雨。","死生消息总难知，欲往招魂又自疑。","机中几度闻嘶马，又恐夫归投杼下。"]},{"t":"废居歌","f":"七言古诗","c":["东邻败屋西邻锁，残柳萧萧燃鬼火。","昔日繁华今日衰，空堂白昼居狐狸。","子孙流落不知处，岁久荒凉谁敢住。","井涸池枯灶绝烟，寒螀四壁啼秋雨。","当时宅中歌舞人，于今已化北邙尘。"]},{"t":"古怨","f":"古风","c":["当时初嫁君，貌比杨花好。","今日与君离，貌比杨花老。","杨衰能再荣，妾貌终枯槁。","君如记妾旧容华，但看明年杨白花。"]},{"t":"绿珠诗","f":"七言古诗","c":["盘龙洞口双蛾翠，玉唾流香脂粉腻。","三斛明珠艳质归，千重锦障秋波媚。","玉笛声寒响断云，凰钗蛟佩舞明君。","光生凤蜡春厨煖，香屑龙炉夜阁熏。","曲曲莺喉歌懊恼，红颜不向青铜老。","宝砌苔痕蚀百花，名园梓泽生秋草。","一死难酬卫尉恩，鬓云斜坠玉钩翻。","碧莎黄土碎香骨，朱楼白日啼妖魂。","涧中金水流呜咽，半寸珊瑚千点血。","麝气春凝柳絮风，佩声夜泣梨花月。"]},{"t":"代闺人答轻薄少年","f":"古风","c":["妾本燕赵姿，委身事君子。","忆昔深闺私语时，指天誓日同生死。","一朝执戟赴长安，彼此恩情隔万山。","经年去住无消息，何处留连不肯还。","闻君日日耽游冶，蹴鞠斗鸡兼走马。","醉里常抛金弹丸，狂来碎却珊瑚把。","自矜豪俊又繁华，百万黄金散狭邪。","昨宵赵女颜如玉，今日燕姬色似花。","如花似玉争歌舞，欢娱岂识凄凉苦。","楼上朝朝望白云，枕边夜夜啼红雨。","流年青鬓叹蹉跎，冷落深闺可奈何。","捲帘忽听莺声老，又是春光一度过。"]},{"t":"王震甫以王叔明山水见贻答谢","f":"七言古诗","c":["王生嗜古元成癖，古今图画如山积。","壁上时时烟雾飞，案头隐隐生泉石。","吾闻胜国有王蒙，丹青绰有巨然风。","幽溪细路已盘曲，烟岚树木何菁葱。","此图珍秘几年所，廉者不求贪不与。","知余夙有卧游情，一旦披图便相许。","奚奴捧送神飞翻，山斋赏鉴忘朝餐。","焚香再拜谢君赐，照乘明珠未是恩。"]},{"t":"题宾月楼空江秋笛二卷后","f":"古风","c":["爨下有焦桐，柯亭有枯竹。","何期得遇蔡中郎，一取为琴一为笛。","中郎已死知音稀，每有奇物谁能知。","汨没泥沙弃水火，令人往往心伤悲。","国初至今二百载，其人与骨今安在。","二图沦落在人间，墨迹依稀犹未改。","吾乡陈伯炜、郑浮丘，两人前辈称风流。","坐宾楼上三更月，吹笛空江万籁秋。","名公诗句题应遍，画图潇洒尤堪羡。","恍若笛声江上闻，尚疑月色楼头见。","当年弃置废簏中，蠹鱼蚀尽尘埃蒙。","余偶得之发大叫，心颜怡悦开双瞳。","吁嗟乎，奇物显晦自有数，岂但柯亭之竹峄山桐。"]},{"t":"赠歌者","f":"七言古诗","c":["习家池上春昼长，主人爱客飞羽觞。","梨园子弟纷成行，少年白晰称陈郎。","何晏之粉荀令香，技掩秦青音绕梁。","翩翩广袖能回翔，脩眉高髻内家妆。","月中一曲舞霓裳，轻敲檀板按宫商。","顿令四座生辉光，苏州刺史空断肠。","奈何与子非一乡，安得相从乐未央。","人生及时须徜徉，莫令两鬓生秋霜。"]},{"t":"题王昆仲画障","f":"七言律诗","c":["寒流瀰瀰泻石壁，严霜剥树枯干瘠。","鬼斧斸石江浒蹲，怒蛟吹水奔涛逆。","鼪鼯狐魅昼攫人，丛林灌木无行迹。","我览生绡毛骨寒，披索枯肠动吟魄。"]},{"t":"采真篇送林叔度游雁宕","f":"楚辞体","c":["壶山烟客持玄箓，凌辰御气仙山麓。","星冠七叶芙蓉颜，螭衣霞佩仙家服。","辞家将作采真游，雁宕山中访灵族。","踏断遥空一线虹，历遍洞天三十六。","云为御兮风为车，驾青虬兮参白鹿。","蓬瀛弱水岂微茫，圆峤方壶堪借宿。","祇从县圃馔瑶芝，不向人间希辟谷。","知君名姓注仙班，聊赠云璈歌一曲。"]},{"t":"送柯秀才还莆","f":"古风","c":["逢君何太迟，别君何太早。","朝发越王城，暮指壶公道。","壶公山色凌青天，云雾苍茫暗玉鞭。","匣里祇存冯子铗，杖头犹挂阮生钱。","馀钱归去堪沽酒，醉后新诗三百首。","赋才元不让三都，何恤纷纷讥覆瓿。","人生知己古称稀，此去何人荐陆机。","秋风已就图南翮，看汝扶摇天际飞。"]},{"t":"述游篇","f":"古风","c":["去年仲冬束行李，掩泪辞亲赴燕市。","今年五月将中旬，方能税驾归田里。","中间辛苦难具陈，万里风波愁杀人。","从来痛定才思痛，回看往事徒沾巾。","闽溪山水何太恶，水似瞿塘山剑阁。","仙霞岭上气不平，黯淡滩头胆将落。","浙中水浅易胶舟，苍头牵缆如伛偻。","一日才行十数里，舲前兀坐空百忧。","岁除才到云阳下，县官正闭奔牛坝。","停舟三日不得行，关吏相逢便相咤。","扬子长江天际流，江豚吹浪神鼍浮。","长年捩舵神色丧，可怜身世同轻沤。","黄河之水名九曲，由来舟楫愁倾覆。","石尤风急水奔腾，隔江少妇将儿哭。","北方景物更荒凉，满目黄沙古战场。","瘦马驱驰髀肉损，酸风射眸肢体僵。","驰马冲寒过涿鹿，四郊倏忽飞滕六。","千山万径少人行，暮抵良乡无处宿。","长安上策不见收，百金用尽存貂裘。","难从北阙操齐瑟，犹戴南冠学楚囚。","男儿致身苦不早，驱车复出长安道。","风景萧条倍去时，尘土侵人颜易老。","三吴两浙竞繁华，此际令人转忆家。","归家幼子牵衣泣，鬓衰面黑咸咨嗟。","奔走天涯过半载，岁月无情不相待。","人生得志在丘园，何必飘零寄湖海。","行路难，空悲酸，世情反覆同波澜。","有璞莫向王庭献，有铗莫向侯门弹。","笑杀刘蕡空不第，且将高卧学袁安。"]},{"t":"石溪歌赠林隐君","f":"楚辞体","c":["南剑有溪名君竹，脩竹苍苍溪水绿。","中有幽人号石溪，诛茅垒石溪之曲。","溪流日夜声潺湲，幽人啸傲石溪间。","石可枕兮溪可漱，富贵浮云真等閒。","幽人今年八十几，足迹何尝到城市。","白岩啸月遇崆峒，青嶂眠云梦黄绮。","怜余本是武陵人，欲向溪头一问津。","桃花好逐溪流出，世上如今不是秦。"]},{"t":"瞻凤歌为张叔韬赋","f":"古风","c":["长溪山水奇，凤山幻灵境。","重冈叠嶂自回环，万壑千岩相掩映。","中有畸人号凤山，时时长啸此山间。","彩云明灭元堪睹，梧竹萧森更可攀。","一朝跨凤归仙府，丹崖翠壁空尘土。","辽鹤千年去不归，慈乌夜半啼声苦。","箧里惟存一画图，忽然飞去胡为乎。","延津无处重寻剑，合浦何期更得珠。","帝悯诸孤怀怨慕，五丁曾遣相呵护。","神物由来不久湮，珠还剑合仍相遇。","张生得此喜还悲，陟岵兴歌泪满颐。","几回欲拟招魂赋，到处曾求薤露诗。","此物遗亡二十载，迄今精爽还应在。","千仞犹疑览德辉，九苞彷佛增文采。","诸子山中日夜号，凤山依旧倚天高。","不须人世悲麟丧，还羡君家有凤毛。"]},{"t":"王生行","f":"七言古诗","c":["王生少负耽奇癖，落魄风尘人不识。","祗从湖海恣遨游，羞向人前嗟厄塞。","胸中神识一何奇，儒雅风流应在兹。","篆隶由来追史籀，时时复作无声诗。","城西一室大如斗，室中奇物无不有。","花鸟图书可自娱，樽罍彝鼎传来久。","赏鉴能同张茂先，翩翩意气更堪怜。","胡琴劈碎宁论价，古剑酬人不计钱。","与余倾盖称莫逆，问奇肯过扬雄宅。","竹里酣歌任往来，花间啸傲忘朝夕。","朝夕相从酒一樽，交情如此君毋谖。","但能博物复饮酒，世事悠悠安足论。"]},{"t":"赤岩吟为大田令谢君赋","f":"楚辞体","c":["剑潭之东多石壁，四面巉岏如火赤。","开辟至今千万年，岩前蓊郁皆蓬藋。","上有嵯峨万仞之丹梯，下有潺湲千顷波流碧。","山魈罔两盘其中，虎豹豺狼据为宅。","任是樵苏日往来，岂识岩中有奇迹。","岩中奇迹人不知，可怜空使山灵悲。","谁能凿破混沌窍，攀萝附葛相追随。","谢君本是探奇客，年少鸣琴宰岩邑。","每学卢敖汗漫游，登临折尽东山屐。","披蓁燃炬入岩中，猛兽山妖都辟易。","万年灵秘一朝开，悬岩绝壁何奇哉。","一声长啸翠微顶，顿使延平潭里白日生风雷。","搆将台榭连云起，浮屠屹立层霄里。","独向岩前望九垓，百二关河如黑子。","吾闻神州三十六洞天，此赤岩兮胡为乎不传。","徐生披图学宗生，案头隐隐生云烟。","愿得借君一苇过剑浦，题诗刻石岩之巅。","岩巅墨迹永不毁，邹峄之碑乃可拟。","吁嗟乎，山川显晦自有时，世间何物无知己。"]},{"t":"赋得易水寒送人游燕","f":"七言古诗","c":["燕山嵯峨易水流，北风吹水声飕飕。","荆卿驱车不顾返，仗剑欲报燕丹雠。","可怜燕耻犹未雪，壮士衷肠空激烈。","千年往事水犹寒，萧萧壮发能冲冠。","怜君故是荆卿比，翩翩侠气横燕市。","击筑还过易水滨，一声长啸悲风起。"]},{"t":"过邓汝高别墅","f":"七言古诗","c":["一区别墅东山曲，几片青山隐茅屋。","门前垂柳覆清溪，屋后长松亚脩竹。","寂寂衡门无俗喧，主人留客烹鸡豚。","衣冠朴素礼真率，依稀如入桃花源。","弹棋击剑复饮酒，世上浮名竟何有。","君今踪迹已青云，我也栖迟甘白首。","与君相对欢且悲，人生会合能几时。","恐君作吏风尘去，此地开尊更有谁。"]},{"t":"寄闵寿卿山人","f":"七言古诗","c":["去岁逢君浮玉山，江风飒飒吹离颜。","今岁重过扬子渡，烟波咫尺难相遇。","铁瓮城头一唤君，江声汹涌那能闻。","寸心强对南徐月，双眼徒瞻北固云。","此生应叹交欢浅，日日思君长展转。","几回飞梦到君傍，江水茫茫空断肠。"]},{"t":"破镜行为陈大赋","f":"古风","c":["美人有宝镜，价值千黄金。","曾与郎君同照影，又与郎君同照心。","一朝分散如萍梗，此心虽同不见影。","金刀剖处鸾凤分，十年踪迹不相闻。","可怜两人持一片，此生何处重相见。","劝君对此休自悲，神物会合终有时。"]},{"t":"冬夜同汝翔振狂在杭集汝大山斋","f":"七言古诗","c":["玉衡指东露华冷，朔飙暗度梧桐井。","张檠乱谑开双颐，铜龙咽漏宵将丙。","仆御执炙兼进卮，筋力跛倚神俱疲。","客眸耿耿若岩电，搜肠呕肝断须髭。","五人同骋谈天口，隔墉魑魅踉跄走。","挥手出门天宇昏，沿衢木栅悬灯守。","严霜砭肌心恻悽，辘轳声断金井西。","解衣匍匐登床睡，四邻咿喔啼天鸡。"]},{"t":"赠胡外史","f":"七言古诗","c":["钱塘风景真奇绝，吴山苍翠湖光白。","山川灵秀萃何人，之子飘然自高格。","生来踪迹压尘埃，湖海狂游亦壮哉。","振衣频陟云龙顶，仗剑曾登戏马台。","燕秦楚越行皆遍，又泛扁舟过海甸。","九鲤湖边信短筇，武夷山上开华宴。","游兴年来尚未央，温陵剑水复清漳。","三秋石鼓簪黄菊，五月枫亭摘荔香。","羡君怀抱何潇洒，知君不是悠悠者。","世路由来遇合难，风尘莫怨知音寡。","伊余癖性好遨游，与子交驩几度秋。","春风竹外频来往，夜月花间递唱酬。","唱酬来往情偏好，漫把交情同草草。","囊里无钱休叹嗟，尊中有酒须倾倒。","胡生胡生何太奇，余每谈诗君解颐。","自堪意气称吾党，不但前身是画师。"]},{"t":"赠王少文","f":"七言古诗","c":["王生今年才十几，籍籍香名满人耳。","已诧文章泻大河，更誇神骨澄秋水。","目下三行腹五车，志如鸿鹄书龙蛇。","遨游竟日车多果，烂漫千言笔有花。","羡子襟怀何卓荦，羡子高谈何岳岳。","五色争看鸑鷟文，片言能折充宗角。","日来相见即相欢，同心臭味如金兰。","高才岂复论长吉，年少还应陋子安。","莫笑相逢频倒屣，如此宁馨谁可拟。","堪叹茫茫宇宙间，眼中之人惟有尔。"]},{"t":"九日怀惟起弟客吴","f":"七言古诗","c":["去年九月客吴门，忆汝凄凉欲断魂。","今年汝作吴门客，一望关河千里隔。","我家兄弟大参商，岁岁年年俱异乡。","梦回闽海风尘远，目极吴门匹练长。","秋风飒飒秋光老，登高望远伤怀抱。","天涯游子滞还期，篱下黄花为谁好。"]},{"t":"蜀道难送王震甫之临邛省刺史兄","f":"七言古诗","c":["蜀道本是蚕丛域，古来元不通中国。","秦帝金牛计太奇，五丁费尽开山力。","鬼斧神功山为开，悬崖绝壁真奇哉。","滟滪瞿塘水势猛，波流日夜声喧豗。","中有畏途称剑阁，羊肠鸟道山形恶。","天梯石栈度偏难，鬼见为愁蛇为却。","猿狖呼群接臂行，山魈野魅作人声。","愁云惨淡日无色，行人此际难为情。","蜀道之难已如此，临邛险恶尤无比。","风俗由来似吐番，州城半绕平羌水。","君家伯氏贤大夫，五马蹀躞专城居。","几度经过九折阪，宁为叱驭无回车。","闽蜀山川何隔越，寻兄万里堪愁绝。","匕首长飞象耳云，马头几看峨眉月。","于今西北正烽烟，羌笛胡笳听惨然。","中宵起坐肠空断，客路思家泪欲连。","蜀道之难应莫叹，长途惟有加餐饭。","鹡鸰原上正相思，劝君休起乡关恨。"]},{"t":"送陈明府应召之京","f":"古风","c":["冶城八月秋风起，仙吏驱车入帝里。","白叟黄童拥道周，攀辕卧辙情无已。","一官闽海几年馀，汉室循良更孰如。","鲁恭政简能驯雉，羊续官清不爱鱼。","声名久已闻天子，玺书召对明光里。","满县秾桃烂似霞，半肩行李清于水。","新秋乘传到长安，五色花骢獬豸冠。","几多狐鼠争投窜，当道豺狼胆自寒。","酌君酒，与君别，寇君难借空呜咽。","至尊垂拱问苍生，但道江南民力竭。"]},{"t":"江上答客伤王少文","f":"七言古诗","c":["去岁江头同送客，江水茫茫江月白。","今岁江头送客归，问君动定空沾衣。","别去光阴才一载，可怜世事须臾改。","当日江间折柳人，于今枯骨知何在。","客子闻言双泪垂，君亡不待余归时。","访君不入君华屋，日伴孤猿坟上哭。"]},{"t":"七夕曹能始宅上观妓","f":"七言古诗","c":["凉风吹动黄姑渚，正值牵牛逢帝女。","一年佳会阻星河，数刻交欢罢机杼。","主人留客当今宵，鸣筝少妇红罗绡。","娇声宛转鸾凰曲，媚眼低回乌鹊桥。","引羽流商歌愈缓，玉绳渐落明星烂。","履坠簪遗乐未休，钟沉漏尽愁将旦。","临别殷勤赠七襄，秋宵虽短此情长。","烛龙已驾扶桑晓，天上人间两渺茫。"]},{"t":"建溪逢游宗振","f":"七言古诗","c":["与君神交今十载，彼此飘零隔湖海。","击筑应难逢渐离，鼓刀何处寻朱亥。","余也今年过建溪，君方弹铗居城西。","客里相逢发长啸，飘飘吐气凌虹霓。","怜君橐中无所有，犹解馀钱去沽酒。","肯将踪迹落红尘，自许交情同白首。","世事悠悠叹二毛，灯前相对两绨袍。","须臾酒尽东西去，江上潮平月正高。"]},{"t":"同游宗振陈伯岑集陈季迪斋中","f":"七言律诗","c":["六月溪行苦烦暑，日暮维舟向江渚。","乘兴行歌访故人，科头跣足花间语。","花间相对忘主宾，驩呼无异平生亲。","今朝潦倒斋头客，明日飘零江海人。"]},{"t":"西瓯道中寄答伯孺病中见送之作","f":"七言古诗","c":["故人卧病空皮骨，精气销忘神恍惚。","枕上犹于笔砚亲，题诗送我游京阙。","诗来字字皆悲辛，半嗟疾病半嗟贫。","况兼离别情思恶，空令游子重伤神。","三叠离歌声太苦，几度哀吟泪如雨。","君方贫病类相如，我也飘零同主父。","行色匆匆一梦间，无由赋别六溪湾。","空流万里穷交泪，未识经春衰病颜。","一别山川成隔越，怀人长对天边月。","于今枚叔更何人，能向君前谈七发。"]},{"t":"西湖飞来峰歌","f":"七言古诗","c":["我生性爱游名山，黄冠布褐常跻攀。","一丘一壑稍险怪，往往大啸开心颜。","此峰幽邃称奇绝，何处飞来忘岁月。","自是神灵运化工，谁将鬼斧施剞劂。","山形突兀又玲珑，悬厓阴洞遥相通。","红泉滴沥归深涧，碧磴岧峣接太空。","森罗青壁如屏障，窱䆗萦纡非一状。","岩下时喧万壑声，石间尽刻诸天像。","翠色遥飞九里松，白云长出两高峰。","冷泉露下澄清溜，灵隐风高送暮钟。","我到山中歇还陟，骇目惊心劳应接。","奇迹应誇天下无，仙都自与尘凡别。","洞门吟眺欲斜晖，坐破苍苔未忍归。","几片寒云生杖屦，半林微月照僧衣。","殷勤记取归时路，日暮云深不知处。","由来造化妒神奇，只恐飞来又飞去。"]},{"t":"灵隐寺寻耶溪上人","f":"七言古诗","c":["浮玉山中曾把臂，风景依稀如隔世。","常叹空门无定踪，此生何处求真谛。","秋风一棹过钱塘，闻说吾师在上方。","扶杖入山急相访，灵隐寺中松隐堂。","方鞋破衲出相见，怪我年来华发变。","相逢不作世间言，指点前山云几片。","半榻跏趺双树边，笑谈隐隐生云烟。","论交共结三生约，出世同参一指禅。","新诗别后多如此，总是禅机非绮语。","胜地何须论虎溪，高风不用推支许。","须臾残照下雷峰，送客松关第几重。","悠悠此别何时遇，愁听云堂薄暮钟。"]},{"t":"饮黄白仲娑罗馆兼柬屠纬真使君","f":"古风","c":["主人避客栖空谷，长日柴门稀剥啄。","我来欲證大因缘，袖中片刺烦童仆。","仓皇倒屣出相迎，青眼相看无世情。","狂来叱咤千夫废，醉后雄谈四座惊。","吾曹本是玄都客，当日同因酒过谪。","行满何须恋世缘，功成依旧归仙籍。","色相由来非我身，凡夫谁识有真人。","片时结搆成炉鼎，一粒玄珠守谷神。","仙师授我还丹秘，逢人岂肯轻开示。","能将神气返虚空，自有灵光照天地。","黄白仲，屠纬真，暂时踪迹落红尘。","何时打得虚空碎，同出青天驾鹤轮。"]},{"t":"吴门寻沈从先不遇","f":"七言古诗","c":["当年踏遍吴门路，十日寻君不知处。","年来踪迹虽相闻，邻人又道移家去。","阊阖城中多路岐，异乡客子那能知。","东寻西访竟不得，惟有残月相追随。","几回欲向朱门问，知君不与朱门近。","欲向红尘问故人，知君寄迹非红尘。","行尽朱门兼白屋，夜深空作穷途哭。","出城昏黑迷归舟，满天风露江干宿。"]},{"t":"七夕词","f":"七言律诗","c":["遥天万里银河碧，双星却笑孤眠客。","玉露金风半夜寒，罗襦绣幕千山隔。","天上人间共此宵，天孙翻近美人遥。","应知楼上蛾眉女，妒杀空中乌鹊桥。"]},{"t":"题画马扇面赠陈幼谦","f":"七言古诗","c":["真龙产自于阗国，促腕高蹄称汗血。","顾影骄嘶赤电生，过都历块红尘灭。","此物何年入汉家，番酋作贡过流沙。","天闲不羡乘黄选，内厩宁论白鼻騧。","扇头一见生惊诧，貌出权奇更高价。","已识雄姿胜渥洼，况看妙手惊曹霸。","吁嗟此马今岂无，安知枥下非神驹。","九方不作孙阳死，世上于今只按图。"]},{"t":"孝友堂慈竹歌为张稚通赋","f":"七言古诗","c":["主人家在苕溪曲，不种奇花种脩竹。","客来看竹问何名，主人竹下吞声哭。","自言此竹生质奇，不产终南非嶰谷。","物性能同慈母心，龙孙爱护知寒燠。","谁移此竹种庭阶，老母当年手自栽。","已看翠色凌萱草，自有清阴覆绿苔。","老母辞堂今几载，此竹青青犹未改。","黄土年来上板舆，红尘久已生莱綵。","可怜母逝竹空存，见竹还思慈母恩。","主人一语一呜咽，座客闻之皆断魂。","从今品竹修新谱，不独湘江有泪痕。"]},{"t":"题顾长卿小影","f":"七言古诗","c":["郎君年少称高格，发未胜冠才覆额。","同誇秀骨迈凡儿，已有雄文惊座客。","此日重披旧画图，神情虽是容华殊。","挥毫写照方童稚，转眼相逢成壮夫。","悠悠岁月催人老，人生颜色难长好。","休将青鬓度年华，自致云霄须及早。"]},{"t":"分得黄金台送屠田叔转运使赴京","f":"七言古诗","c":["燕山日落悲风起，百尺高台留故址。","满地狐踪丘陇间，千金马骨荆榛里。","至今行客说燕昭，爱士高风久寂寥。","侵阶碧草空留色，翳土黄金已尽销。","我家定鼎都燕蓟，正是黄金台上地。","万里星槎上汉来，诸侯露冕朝天至。","台前贤士集如云，拄笏弹冠谒圣君。","阳气自生吹黍谷，英雄岂说乐将军。","屠君拥传辞闽海，自有高才轻郭隗。","休叹盐车上太行，何须吊古登寒垒。","至尊侧席正求才，太室明堂日日开。","白璧虞卿先拜赐，黄金宁用筑空台。"]},{"t":"题刘松年溪阁纳凉小景","f":"七言律诗","c":["谁家亭馆临溪渚，四面苍崖夹平楚。","树色溪声白昼寒，行天赤日无炎暑。","宾主相看礼数忘，笔床茗椀对垆香。","图中清福难消受，愿借虚亭半日凉。"]},{"t":"题高漫士晚阁溪云图","f":"七言古诗","c":["主人爱溪还爱云，去年走谒武夷君。","九曲溪流太清泚，千峰云气何氤氲。","幔亭得预曾孙宴，归带白云千万片。","天风倏忽下蓬瀛，吹散长空成组练。","漫士何年写此图，一溪云气长模糊。","恍疑接笋峰前见，还记天游顶上居。","一别溪头峰六六，经年不举看云目。","愿学宗生作卧游，画图一见心能足。"]},{"t":"题春山积雨图","f":"古风","c":["元章不作房山死，谁写云山缣素里。","耳畔如闻滴沥声，眼中似见岚烟起。","浓云朦?树无根，涧水奔流野色昏。","竟日风霾浑失昼，行人何处辨孤村。","画图如此虽堪惜，莫贮囊中珍十袭。","只恐时时风雨来，生绡一幅淋漓湿。"]},{"t":"送闵寿卿隐武夷","f":"古风","c":["世人游武夷，往往思卜宅。","一出清溪谢白云，山灵无计留双屐。","始信人间事可哀，幔亭佳宴不重开。","浮生只爱红尘老，人世难逃白发催。","怜君弃家经几载，服食还丹颜未改。","已识仙都注有名，尚疑遗蜕函犹在。","自入闽天誓不还，因缘合在武夷山。","独携一杖千峰里，閒放孤舟九曲间。","此山元是神仙窟，接笋天游双崒嵂。","玉女妆残峰顶霞，金鸡叫落滩头月。","君今筑室此中居，永绝尘缘与世疏。","回视形骸同粪土，能将神气返空虚。","我也行年三十几，半生踪迹多城市。","入药空烧九转红，著书枉识关门紫。","海外徒闻更九州，此身期伴赤松游。","何时重预曾孙宴，同醉仙人十二楼。"]},{"t":"送俞本之山人还金昌","f":"七言古诗","c":["满径黄花桑落酒，送客关门折衰柳。","涉世空怀失路悲，干时自乏谭天口。","片刺侯门不得通，桂薪玉粒哭途穷。","半年逆旅貂裘敝，一剑飘然马首东。","劝君休下杨朱泪，客里秋风易憔悴。","伏枕愁为越国吟，吹箫归向吴门醉。","此日诸侯厌布衣，可怜穷达世情非。","君归莫叹行装薄，多少空囊人未归。"]},{"t":"忆昔行题友人小像","f":"七言古诗","c":["少年携手同行乐，我甫胜冠君总角。","岁月悠悠去不还，眼前风景犹如昨。","此日看君新画图，神情虽是颜容殊。","所嗟童稚尚如此，莫怪故人成老夫。","我也半生甘落魄，君亦胡为恋丘壑。","高举犹怀鸿鹄心，待时且作龙蛇屈。","旧事经今二十秋，披图空感昔时游。","与君相见且饮酒，莫遣青铜催白头。"]},{"t":"都门送吴允兆还吴兴","f":"七言古诗","c":["燕山三月杨柳新，别酒一杯送故人。","故人仗剑意慷慨，仰天大笑辞平津。","我唱骊驹君驻马，送君半是穷交者。","暮角凄凉起驿楼，春云惨淡生原野。","酒阑歌罢马频嘶，千里征途望霅溪。","独有王孙归未得，天涯空叹草萋萋。"]},{"t":"出都门答别邓汝高员外","f":"七言古诗","c":["十年三上长安道，阙下献书俱不报。","拂袖还山别故人，风尘满目伤怀抱。","长安裘马多轻肥，先达何人怜布衣。","惟君慷慨念贫贱，交情如此今人稀。","凄凉旧事那堪数，半榻孤灯寒夜雨。","载酒曾同醉锦溪，看山犹记眠芳墅。","转盼光阴十载馀，怜余踪迹仍樵渔。","空文何以干明主，儒术由来生计疏。","余也今年三十几，依然落魄归田里。","白首何妨老故园，红尘从此辞燕市。","拔剑哀歌日易昏，垂杨未折已销魂。","人生离别足感叹，穷达悠悠何必论。"]},{"t":"途中感遇效同谷七歌 其一","f":"楚辞体","c":["吾生本是疏狂客，几回落魄长安陌。","弃置应惭骨相屯，壮年自失干时策。","日驱羸马口微吟，仰天大笑乾坤窄。","呜呼一歌兮歌慨慷，燕山六月飞严霜。"]},{"t":"途中感遇效同谷七歌 其二","f":"楚辞体","c":["归舟归舟黄河曲，挥汗如浆苦炎燠。","水浅舟胶不得行，逢人耻作穷途哭。","高堂慈母念子深，倚闾此际枯愁目。","呜呼二歌兮歌惨切，仗剑指天天为裂。"]},{"t":"途中感遇效同谷七歌 其三","f":"楚辞体","c":["有弟有弟俱牛衣，家徒四壁常苦饥。","燕闽相去道路远，别来一载音书稀。","知汝日夜望我归，梦魂常绕天涯飞。","呜呼三歌兮歌已短，一领征衣泪痕满。"]},{"t":"途中感遇效同谷七歌 其四","f":"楚辞体","c":["有姊已老有妹贫，平生惟此骨肉亲。","知余流落兼苦辛，家庭怅望应伤神。","廿年踪迹半道路，平生壮志成灰尘。","呜呼四歌兮歌转涩，猿狖声哀山鬼泣。"]},{"t":"途中感遇效同谷七歌 其五","f":"楚辞体","c":["老妻半世空糟糠，少妇席未煖君床。","男年十五女七岁，去年别我俱恓惶。","丈夫成名既不早，胡然久居天一方。","呜呼五歌兮歌愈急，朱颜灯下流黄湿。"]},{"t":"途中感遇效同谷七歌 其六","f":"楚辞体","c":["有朋有朋多穷交，平生风谊如同胞。","扬云拓落众所弃，数子不敢轻相嘲。","此日飘零勿复道，与君矢志甘衡茅。","呜呼六歌兮歌且缓，伐木声残肠欲断。"]},{"t":"途中感遇效同谷七歌 其七","f":"楚辞体","c":["扰攘烽烟何太急，四海纷纷飞羽檄。","但见纵横戎马多，何处哀鸣鸿雁集。","书生徒抱杞人忧，中宵起舞空悲泣。","呜呼七歌兮歌已终，黄昏旷野凄寒风。"]},{"t":"彭城行","f":"七言古诗","c":["彭城半绕黄河水，楚宫岁久生荆杞。","杀气清秋暗战场，愁云白日低残垒。","楚汉当年几战争，喑哑叱咤悲风生。","楚兵一夕尽归汉，帐前健儿皆楚声。","乌骓不逝虞姬死，垓下歌声成变徵。","百二关河属汉家，八千子弟徒为尔。","霸图百战总成灰，吊古还劳过客哀。","千载沐猴成一笑，年深戏马留空台。","黄河日夜东流去，荒城寥落悲狐兔。","世事兴亡一瞬间，英雄枯骨馀丘墓。","休将楚汉论雌雄，此地曾闻唱大风。","试向咸阳城上望，离离衰草满新丰。"]},{"t":"黄节妇复明歌","f":"古风","c":["黄氏母，夫亡守志多辛楚。","血泪洒黄泉，泪枯双目瞽。","母目瞽，儿心苦，朝夕吮眸眸未愈。","母子精诚良可哀，一朝忽尔双眸开。","母目开，父目瞑，老泪依然滴孤枕。"]},{"t":"分得九疑山送屠田叔守辰州","f":"七言古诗","c":["楚都山水称奇险，突出高峰青九点。","天外巫黔路渺漫，峰阴溪涧流深浅。","峰峰相间色参差，无数青螺镜里窥。","变幻烟霞看莫辨，满天云雨望堪疑。","重华当日巡南服，驻跸苍梧穷地轴。","一夕龙髯上鼎湖，数声鸾吹传空谷。","鸾吹龙髯去不还，湘江帝子惨朱颜。","愁眉久锁锋前黛，血泪长留竹上斑。","山色含颦望巡狩，时时似听箫韶奏。","飞瀑寒流到处奇，丹崖朱洞天然秀。","潇湘烟月洞庭云，远岫联绵一带分。","鹧鸪夜叫黄陵庙，狐兔秋悲虞帝坟。","古迹荒凉不堪语，果有啼烟兼啸雨。","使君剖竹向荆门，正近潇湘洞庭浦。","有时行部拥双旌，定吊娥皇与女英。","风前好荐琼芳把，月下如闻环佩声。","九疑峰影何重叠，峰下褰帷劳应接。","怀古宁辞驻一麾，搜奇不惜停双屐。","摇摇桂棹楚江濆，袅袅秋风木叶闻。","遗我不须搴杜若，骚成只待寄湘君。"]},{"t":"题盛行之画梅卷","f":"古风","c":["盛君画梅太奇绝，老干如龙更如铁。","笔底幽魂冷不彻，满纸枯株三丈雪。","六月披图身欲僵，一堂坐客皆闻香。","就中先辈多评章，佳者长沙之李华亭张。","当时此物果谁有，杨公成玉扬州守。","公也珍之若琼玖，自谓此图传不朽。","子孙弃之同敝帚，百年竟落他人手。","峡水林君偶得之，不惟爱梅兼爱诗。","犹记当初兵火时，居民鼠窜家流离。","书籍图画焚无遗，此图藏之高树枝。","倭奴虽黠那能知，淫雨沾湿寒风吹。","鬼神呵护无损亏，吁嗟此图亦已奇。","付与妙手重装池，千秋万岁无离披，千秋万岁无离披。"]},{"t":"题薛晦叔小像","f":"七言律诗","c":["谁将缣素开生面，神骨如冰目如电。","童乌文藻自堪誇，洗马风流今再见。","画史挥毫未入神，十分才得几分真。","有时鹤氅行微雪，人比丹青更出尘。"]},{"t":"题陈仕卿蕉雨亭","f":"七言律诗","c":["虚亭四面芭蕉绿，疏雨潇潇听断续。","几点啼残屋上鸠，数声滴破隍中鹿。","洗尽红尘翠色寒，美人含泪倚朱阑。","题诗好趁初晴后，醉墨淋漓湿未乾。"]},{"t":"题朱竹","f":"古风","c":["根如赭虬髯，叶如丹凤尾。","有时截作钓鳌竿，珊瑚乱拂桃花水。","有时掷杖化为龙，白日青天赤鳞起。","能将红雾变苍烟，产在朱明几洞天。","须臾绛节生彤管，只向松间滴露研。"]},{"t":"陈伯孺兄弟水明楼春宵听雨歌","f":"七言古诗","c":["我家有斋名绿玉，斋前种得千竿竹。","君家亦有水明楼，半亩方塘山影流。","君频访我鳌山麓，我每寻君溪水曲。","与君来往十年馀，到此楼中几回宿。","今春买棹来相寻，峡江风起波涛深。","楼中宾主黯相对，四山阴翳生淫霖。","檐前坐听声声雨，聊把琴书供笑语。","烛尽犹然兴未阑，诗成自觉心相许。","潇潇风雨莫深愁，百尺楼中且暂留。","凭君貌出巴山夜，一幅丹青当卧游。"]},{"t":"霞林樵隐为梁逸人赋","f":"七言古诗","c":["山中一道明霞起，照得林峦色俱紫。","初疑晴彩结为帷，还讶馀光散成绮。","林间彷佛见高标，白日青天挂绛绡。","梁君霞外神仙客，时向山中称隐樵。","斧柯来往壶公谷，伐得晴霞成几束。","晓起常依洞里行，夜深祇傍岩边宿。","担头挑得赤城归，却似桃花片片飞。","斫来自足山家业，服处真成隐者衣。","殷红满目看如绚，朝暮阴晴千万变。","此物由来高可餐，愿向深林求一片。"]},{"t":"美人买铁马歌和幼孺","f":"七言古诗","c":["瑶宫仙子遗环佩，百结流苏向空坠。","半天乱逐片云飞，无数琅玕一时碎。","赵璧隋珠半已残，重将彩线串团圞。","良工持向街头卖，临风忽听声珊珊。","珊珊送入妖娇耳，玉笋提携心暗喜。","探得青蚨出锦囊，买来挂在雕檐底。","一阵微风一阵声，美人含笑闻琮琤。","飘扬祇益春心动，凄切翻令午梦惊。","铜壶夜静催银箭，留得檀郎宿深院。","却爱邻姬睡乍酣，玎珰莫向空中战。"]},{"t":"题陈伯孺效漫士山水小景","f":"古风","c":["龙门待诏高廷礼，兴到挥毫写山水。","黯淡峰峦朦?云，一生学得南宫体。","三绝声名重昔时，画成题咏墨淋漓。","总缘人品压流辈，以兹并重无声诗。","流传岁久虫鱼蚀，半尺冰绡难论值。","龙门去后墨池乾，画史谁能继其迹。","陈子湾溪我辈人，应疑待诏是前身。","一时词翰推双美，点染云山更有神。","满目烟霞浓复淡，复岭重冈连断岸。","偏于米老得风神，难与龙门辨真赝。","岁月惊看忽十年，灯前隐隐生云烟。","诗成戏笔题其上，留作人间宝墨传。"]},{"t":"题马远山水","f":"七言律诗","c":["幽人野性耽空谷，一簇葵花数竿竹。","磐石嵚崎出涧阿，流泉湍激交林麓。","清宵露坐月光迟，稚子支筇背后随。","林下水边无俗物，既堪图画又堪诗。"]},{"t":"咏古镜","f":"五言律诗","c":["青铜留美质，玄锡出良工。","剥蚀殉秦冢，悲欢照汉宫。","挂壁菱花艳，藏匣桂轮空。","佳人时拂拭，莫使素尘蒙。"]},{"t":"咏百花画帐","f":"五言律诗","c":["罗帷图百卉，晏寝自生香。","不羡雕栏艳，犹如金谷芳。","娇枝沾暮雨，弱干耐秋霜。","更有双连理，夜发合欢床。"]},{"t":"咏薰炉","f":"五言律诗","c":["范金呈丽饰，长向兰闺爇。","笼袖玉肌温，薰床珠被热。","永夜焰常燃，残更芬不灭。","佳人梦乍醒，枕畔添香屑。"]},{"t":"咏美人昼眠","f":"五言律诗","c":["金钗斜欲溜，玉枕倦相依。","瞢腾含媚眼，展转皱罗衣。","汗沾香粉腻，幔隔黛痕微。","梦只萦闺阁，不逐楚云飞。"]},{"t":"咏美人理发","f":"五言律诗","c":["犀梳流半月，蝉鬓乱浓云。","钗梁卸巧饰，膏沐散馀芬。","垂肩遮宝珥，委地拂罗裙。","新作盘龙结，含笑问夫君。"]},{"t":"咏美人观画","f":"五言律诗","c":["国色看如画，丹青疑是真。","谁能分丽质，各欲竞丰神。","江滨有两艳，下蔡见双身。","只恐朱颜谢，不及卷中人。"]},{"t":"题画鹤","f":"五言律诗","c":["在阴胎化质，缣素写珍禽。","差池出玄圃，凄切逐瑶琴。","凝霜时振羽，警露有馀音。","乘轩虽窃宠，终衔恩遇深。"]},{"t":"题画鹿","f":"五言律诗","c":["画图呈瑞应，灵物著天休。","浮江同濯濯，呼侣各呦呦。","青莎腾或倚，丰草伏还游。","苍玄几变色，遐算踰千秋。"]},{"t":"赋得欲笑翻成泣","f":"五言律诗","c":["悲欣无定态，啼笑一时并。","粉痕欢眼注，铅水妩容生。","两犀方奋齿，双箸忽吞声。","谁云射雉乐，翻作泣鲛情。"]},{"t":"七夕咏牛女","f":"五言律诗","c":["银河低綵幔，珠箔捲针楼。","星丸弹灵鹊，云锦幕牵牛。","欢憎今夕促，泪续去年流。","何当延兔影，长将凤驾留。"]},{"t":"美人篇戏赠陈参军","f":"五言律诗","c":["兰梦方徵吉，倾城得细君。","纤看眉上月，浓爱鬓边云。","听琴猜断索，织锦辨回文。","共誇新妇好，真可配参军。"]},{"t":"和陈参军送客未还闺中有望","f":"五言律诗","c":["别虽无百里，情亦似三秋。","薰香虚侍寝，看月怯登楼。","心慵朝镜掩，望切晚妆留。","知君南浦泪，不独送人流。"]},{"t":"为屠田叔太守新姬催妆","f":"五言古诗","c":["灯光满九衢，弦筦待名姝。","羞嗔夫婿促，娇倩侍儿扶。","鬒浓耀宝饰，佩响按罗襦。","含颦疑有态，敛色看成都。","欲泣声先颤，将行步复须。","梁惊栖玳瑁，枕怯索珊瑚。","除钗劳屡唤，近帐费低呼。","情通呈脸晕，语涩静唇朱。","兰膏薰戺闼，香气郁流苏。","展转动金钏，绰约见冰肤。","使君今有妇，五马不踟蹰。"]},{"t":"出塞曲 其一","f":"五言律诗","c":["羽檄交驰急，横戈赋远征。","五更边地角，双泪汉臣缨。","夜月关山影，秋风陇水声。","何时安绝漠，归去报承明。"]},{"t":"出塞曲 其二","f":"五言律诗","c":["穷冬生朔雪，寒色满交河。","绝塞人烟少，荒城戍角多。","关山同汉月，部落半羌歌。","欲破匈奴胆，君王莫许和。"]},{"t":"陌上桑","f":"五言律诗","c":["贱妾是罗敷，条桑向路隅。","捲衣伸玉腕，掩袂谢金夫。","干弱摇丝笼，枝繁罩绣襦。","蚕饥归去急，五马枉踟蹰。"]},{"t":"巫山高","f":"五言律诗","c":["宫殿伤芜没，峰峦入杳冥。","猿声经峡惨，山色近湘青。","神女魂何处，襄王梦已醒。","朝昏见云雨，犹自想精灵。"]},{"t":"梅花落","f":"五言律诗","c":["繁花生绝塞，春至几枝空。","舞杂梁园雪，飘随庾岭风。","妆台香点砌，官阁影辞丛。","少妇高楼上，含悽曲调中。"]},{"t":"折杨柳","f":"五言律诗","c":["别时曾一折，羌管不堪听。","愁锁眉同翠，娇回眼共青。","征途悲雨雪，古驿望流星。","却恨飞空絮，随波化作萍。"]},{"t":"关山月","f":"五言律诗","c":["一片关山月，悲欢望不同。","穹庐光照海，沙碛影连空。","轮满开秦镜，弦斜倚汉弓。","年年三五夜，魂断玉楼中。"]},{"t":"陇头水","f":"五言律诗","c":["秦川分两水，呜咽不能休。","饮马冰犹冻，磨刀血半流。","东西随陇坂，远近入边州。","万古声无尽，惟添征戍愁。"]},{"t":"紫骝马","f":"五言律诗","c":["蹀躞横行意，悲鸣恋主身。","金鞭垂汉月，玉勒控边尘。","影绝追奔易，蹄高转战频。","不辞流汗血，未可事和亲。"]},{"t":"铜雀伎","f":"五言律诗","c":["铜台遗令在，玉座主恩非。","旧曲流哀管，馀香散舞衣。","穗帷空寂寞，罗绮失光辉。","日日西陵望，君王归不归。"]},{"t":"送人赴安西","f":"五言律诗","c":["离亭征马嘶，送子赴安西。","后会知何日，前途方鼓鼙。","天寒白草瘦，沙阔黄云低。","所惜同心远，能无心惨悽。"]},{"t":"题方广岩廨院","f":"五言律诗","c":["参禅觅野寺，凉月满空山。","行到丛林里，溪流隔几湾。","老僧拥衲坐，孤鹤闻钟还。","回首来时路，渺茫烟霭间。"]},{"t":"塞上逢故人","f":"五言律诗","c":["胡笳声正喧，一骑向秋原。","偶尔闻乡语，因之伤旅魂。","停鞭问姓氏，掩泪叙寒暄。","未尽悲欢意，沙场日又昏。"]},{"t":"送僧还山","f":"五言律诗","c":["深林长闭关，岁久欲西还。","落日人烟少，秋风梵磬閒。","锡飞孤鹤外，衲过断云间。","应叹无期别，相寻何处山。"]},{"t":"元夕集宗少府宅 其一","f":"五言律诗","c":["胜地春光早，开尊卜夜驩。","更深银烛短，风细玉箫寒。","露气凝疏幌，花阴罩画栏。","六街冶游子，香雾扑雕鞍。"]},{"t":"元夕集宗少府宅 其二","f":"五言律诗","c":["令节逢元夕，春光此地偏。","竹枝游女唱，桂酌主人传。","渐觉银河坠，还惊珠斗悬。","悠然归路晚，万井散灯烟。"]},{"t":"溪行","f":"五言律诗","c":["空山收晚照，秋色满川原。","砧杵谁家妇，鸡豚何处村。","丛林喧怪鸟，绝壁挂孤猿。","白发高堂上，遥遥正倚门。"]},{"t":"重宿灵源洞怀珠上人","f":"五言律诗","c":["重借蒲团宿，吾师已度杯。","烟霞虚白社，衣钵入黄梅。","犹忆无生偈，空馀般若台。","灵源今夜月，依旧照苍苔。"]},{"t":"送陈平夫归六溪","f":"五言律诗","c":["送尔出关门，潮生野渡喧。","离心数行雁，愁思一声猿。","月暗迷前浦，林疏见远村。","今宵灯影里，相忆倍销魂。"]},{"t":"乱后经电白县有怀故园","f":"五言律诗","c":["一夜搀抢落，东南乍息兵。","黄云依旧垒，白骨委孤城。","八口蛮烟路，千家野哭声。","故园残月影，偏向马头明。"]},{"t":"樵川道中","f":"五言律诗","c":["停舟当薄暮，古寺报昏钟。","茅店斜临水，柴门半倚松。","云萝催暝色，霜叶老秋容。","片月飞清影，寒山翠几重。"]},{"t":"送邓郡丞擢河东转运","f":"五言律诗","c":["征马忽闻嘶，飞花趁马蹄。","一官司斥卤，万里隔云泥。","路入滹沱近，城连恒岳低。","知君才驻节，名已震关西。"]},{"t":"舟次小箬溪遇邵广文梦弼话别","f":"五言律诗","c":["邂逅白云边，停桡一问玄。","去沽桑落酒，来醉广文毡。","月色催更柝，霜花压钓船。","相逢俱逆旅，明日各风烟。"]},{"t":"剑津夜泛","f":"五言律诗","c":["夕翠飞丹壑，葱茏色不分。","神龙前代化，山鬼隔村闻。","零露清残月，流星入断云。","溪边高阁在，何处遇雷君。"]},{"t":"度何岭忆家","f":"五言律诗","c":["乡泪正纷纷，猿声到处闻。","孤峰遥耸翠，怪石自成文。","忆弟吟春草，思亲指白云。","投繻向关吏，何意学终军。"]},{"t":"塔岭道中","f":"五言律诗","c":["树老根盘郁，峰奇势不齐。","单车穿宿莽，双巘夹清溪。","古驿喧猿语，荒郊印虎蹄。","王孙归未得，愁见草萋萋。"]},{"t":"仙霞晓发","f":"五言律诗","c":["早起肃行役，寒威何太严。","防身惟短剑，沽酒有长髯。","故国山河尽，愁心日夜添。","鸡声催出客，残月挂茅檐。"]},{"t":"度西阳岭","f":"五言律诗","c":["绝巘疑无路，披蓁雾里行。","千寻皆鸟道，四壁半猿声。","田父扶犁出，山僧倚锡迎。","停骖聊买醉，霜月满孤城。"]},{"t":"舟次龙丘遇尹光禄留饮赋谢","f":"五言律诗","c":["黑发朝参懒，听松枕石眠。","胸中才八斗，门下客三千。","望气关常紫，挥毫草正玄。","自惭同侣笑，休觅孝廉船。"]},{"t":"西湖立春","f":"五言律诗","c":["春色薄城阴，东风到武林。","暖回邹子律，病作越人吟。","儿女他乡泪，莺花故国心。","西湖有狂客，相对酒杯深。"]},{"t":"王百谷招饮半偈庵","f":"五言律诗","c":["岁晚过吴市，飘零念此身。","投君三指刺，醉我百壶春。","名下无虚士，天涯有故人。","相逢谈半偈，江上月华新。"]},{"t":"毗陵舟中","f":"五言律诗","c":["行行惊岁暮，孤棹滞天涯。","远岸经桥合，寒流抱郭斜。","何人分竹叶，无使寄梅花。","苦为微名累，萧萧两鬓华。"]},{"t":"南徐除夕","f":"五言律诗","c":["倚棹南徐下，燕山北望遥。","客程犹未半，残岁只今宵。","乡泪当孤烛，愁心逐夜潮。","高堂有白发，何意向云霄。"]},{"t":"扬子江望金山寺","f":"五言律诗","c":["才过扬子渡，便觉气萧森。","地势分南北，江流自古今。","浪翻塔影动，云拥寺门阴。","未惯风波苦，空馀涕泪深。"]},{"t":"漂母庙","f":"五言律诗","c":["淮水流无尽，荒城古庙存。","何人怜国士，老妪识王孙。","虽有千金报，宁酬一饭恩。","平生知己意，难与世人言。"]},{"t":"任邱道中","f":"五言律诗","c":["马足怯春霜，燕山路正长。","生涯惭小草，离绪寄衰杨。","白骨新邱垄，黄沙古战场。","平安空有信，来往少同乡。"]},{"t":"李惟实过集客舍","f":"五言律诗","c":["击筑过燕市，逢君醉浊醪。","龙门叨御李，虫刻愧投桃。","岁月虚长铗，风尘暗大刀。","可怜灯影里，相对两青袍。"]},{"t":"出都门怀程五表兄","f":"五言律诗","c":["献策不得意，呼童便束装。","人皆悲失路，我独喜还乡。","拓落嘲玄草，驱驰愧绿杨。","归寻河朔侣，同擘荔枝香。"]},{"t":"游虎邱寺","f":"五言律诗","c":["一棹过兰若，斋心礼法华。","荒坟深踞虎，古木乱栖鸦。","宝塔凌空迥，幽岩逗月斜。","生公讲亭在，何处有袈裟。"]},{"t":"同吴之卫马云卿饮张幼于曲水草堂","f":"五言律诗","c":["两度过吴市，今来得问奇。","榻从花下设，人在竹间窥。","座客皆黄发，先生自白眉。","名园依曲水，芳宴共题诗。"]},{"t":"谐赏园别顾世卿","f":"五言律诗","c":["共醉尊中酒，惊看别后颜。","神龙分剑浦，羸马出阳关。","园似游金谷，人如行玉山。","相逢又相别，空有泪潺湲。"]},{"t":"午日过江郎山","f":"五言律诗","c":["车度蒙茸里，侵衣树色凉。","土音闻越客，山色见江郎。","萍梗悲游子，菖蒲忆故乡。","龙舟何处竞，箫鼓断人肠。"]},{"t":"至家","f":"五言律诗","c":["故里经年别，今朝慰倚闾。","关河空阻绝，岁月易居诸。","燕麦埋荒径，莺花老旧庐。","莫嫌金已尽，还有一囊书。"]},{"t":"行脚僧","f":"五言律诗","c":["何年辞故院，足迹遍云天。","有寺皆投宿，逢人便结缘。","木杯穷岁月，锡杖老风烟。","人境元成幻，行藏总是禅。"]},{"t":"旱 其一","f":"五言律诗","c":["入秋犹不雨，望已绝三农。","处处忧豺虎，村村祭土龙。","人情皆悯岁，天意岂乾封。","米价腾如此，军储不罢供。"]},{"t":"旱 其二","f":"五言律诗","c":["上天未悔祸，四野正皇皇。","溪涧水亦涸，桔槔何处忙。","诛求今正急，谁敢议开仓。","苦乏谋生策，须求辟谷方。"]},{"t":"嵩山寺赠净上人","f":"五言律诗","c":["古寺门空闭，青林紫衲僧。","风传斋后磬，雨暗座前灯。","经不念中品，禅能参上乘。","夜深谈半偈，无愧佛图澄。"]},{"t":"芝山寺逢游元封兼怀宗振","f":"五言律诗","c":["当年曾一面，此夜遇禅居。","乍见不相识，惊看鬓渐疏。","阿咸元自达，痴叔竟何如。","别后馀玄草，毋忘寄敝庐。"]},{"t":"春兴","f":"五言律诗","c":["入春才数日，春意满疏林。","苔补阶前色，禽传竹外音。","山容开晓霁，云气散轻阴。","虚室无尘想，泠然物外心。"]},{"t":"访瀚上人","f":"五言律诗","c":["遁迹芝山寺，长年不出龛。","行深忘色相，客至但和南。","传世灯千劫，随身经一函。","无言即真意，禅理岂须谈。"]},{"t":"溪行晚眺","f":"五言律诗","c":["溪上欲黄昏，潮平浪不翻。","钟声云外寺，灯影水边村。","荒坂牛羊下，前林鸟雀喧。","桃花最深处，莫是武陵源。"]},{"t":"清明客中寄惟起弟","f":"五言律诗","c":["迢递京华路，风尘多苦辛。","可怜三月暮，又负一年春。","故里莺声老，天涯柳色新。","孤灯风雨夜，忆汝倍伤神。"]},{"t":"同王玉生惟扬弟登剑州明翠阁因怀宗思兼先生","f":"五言律诗","c":["高阁倚崚嶒，年来几度登。","危栏紫野竹，怪石抱枯藤。","上界空香坠，前山翠色凝。","因思旧游者，望断白云层。"]},{"t":"王台驿","f":"五言律诗","c":["古驿枕溪流，群山抱驿楼。","滩声寒午梦，莺语动春愁。","芳草王孙路，桃花渔父舟。","白云与流水，相对共悠悠。"]},{"t":"舟行 其一","f":"五言律诗","c":["空山驻夕阳，山色更苍茫。","隔岸蘋花白，满汀芦叶黄。","寒蝉抱树咽，金气侵衣凉。","此际溪行者，能无思故乡。"]},{"t":"舟行 其二","f":"五言律诗","c":["舟行正暮秋，晚眺思悠悠。","驿路当溪断，渔家傍竹幽。","山阿全隐寺，石罅乱回舟。","坐听寒溪水，潺湲日夜流。"]},{"t":"秋日同汝翔伯孺惟起集汝大山斋","f":"五言律诗","c":["高斋秋气清，残暑坐来轻。","竹外商飙度，松间天籁生。","一杯桑落酒，千载薜萝盟。","我辈疏狂甚，谁当嵇阮名。"]},{"t":"剑浦得幼孺书","f":"五言律诗","c":["别君经一年，迢递各云天。","彼此有消息，全凭书札传。","雁飞九峰外，梦到六溪边。","把臂知何日，开缄空惘然。"]},{"t":"病中迟陈道育不至","f":"五言律诗","c":["幽斋啼暮禽，扶病自沉吟。","孤烛当残夜，疏钟度远林。","月窥松隙小，云闭竹房深。","空有怀人意，杳无车马音。"]},{"t":"赠陈元之刺史","f":"五言律诗","c":["先生宗炳流，山水卧中游。","隐矣能自适，澹然何所求。","紫云当日梦，黄菊此时秋。","投老六溪上，依稀如十洲。"]},{"t":"慰陈振狂失钓艇 其一","f":"五言律诗","c":["一夜秋江涨，闻君失钓航。","声应停欸乃，歌忽罢沧浪。","荻岸空残月，芦矶但夕阳。","溯回知所去，宛在水中央。"]},{"t":"慰陈振狂失钓艇 其二","f":"五言律诗","c":["枯缆何时绝，飘然叹断蓬。","岂知渔父枻，翻作楚人弓。","鹤侣今谁载，鸥群旧已空。","中宵频起望，或有石尤风。"]},{"t":"慰陈振狂失钓艇 其三","f":"五言律诗","c":["青钱费几缗，买棹作渔人。","岸火焚孤缆，秋风罢钓纶。","飘零疑海怪，去住听波臣。","不返缘何事，君其问水滨。"]},{"t":"岁暮怀郑六初","f":"五言律诗","c":["忽忽岁云暮，天涯客未还。","梦回瓜步月，人隔秣陵关。","驿路梅花瘦，空斋竹影閒。","何时理归棹，相对说青山。"]},{"t":"夜坐","f":"五言律诗","c":["空斋寒似水，独坐倍凄然。","叶响林间雨，风声竹杪泉。","应门双鹤睡，照佛一灯悬。","暝色生萝径，飞来绝壑烟。"]},{"t":"岁尽","f":"五言律诗","c":["范叔寒如此，其如复逼年。","文章能作祟，吾道合迍邅。","吏预催官税，门多索子钱。","纵然贫到骨，不敢怨皇天。"]},{"t":"苦雨 其一","f":"五言律诗","c":["淫雨经旬月，蓬蒿掩敝庐。","饥乌藏树杪，行蚁徙阶除。","天意高难问，云游迹渐疏。","山中蓑笠在，长日自挥锄。"]},{"t":"苦雨 其二","f":"五言律诗","c":["竟日云阴合，千峰雨脚连。","田禾烂欲死，平陆溃成川。","竹径坐来恶，蕉房听可怜。","因之废栉沐，白日枕书眠。"]},{"t":"苦雨 其三","f":"五言律诗","c":["九夏苦无雨，冬来何太繁。","冥冥翻浪急，莽莽塞天昏。","野服沾松翠，空墙绣藓痕。","山斋幽寂甚，愁绪岂堪论。"]},{"t":"约汝大汝翔振狂惟秦在杭藤山看梅 其一","f":"五言律诗","c":["藤山梅万树，冬尽一齐开。","粉面怀人瘦，香魂入梦来。","翠微将失色，玉屑渐成堆。","昨得花神檄，迟君共举杯。"]},{"t":"约汝大汝翔振狂惟秦在杭藤山看梅 其二","f":"五言律诗","c":["梅坞馀残雪，疏枝冷不禁。","去招梁苑客，同作灞桥吟。","十里花为市，千家玉作林。","慎毋披鹤氅，树里恐难寻。"]},{"t":"同汝翔在杭看梅先宿芦中矶 其一","f":"五言律诗","c":["雪后寻梅坞，芦中问钓矶。","榻同陈仲举，诗得谢玄晖。","朔气凝青幌，寒香动翠微。","前林春色好，折得几枝归。"]},{"t":"同汝翔在杭看梅先宿芦中矶 其二","f":"五言律诗","c":["白龙江上路，五里即梅林。","暂借芦中宿，同谐物外心。","清霜明竹屋，凉月坠花阴。","姑射仙人梦，朝来不可寻。"]},{"t":"芦中矶晓起喜汝大惟秦至","f":"五言律诗","c":["犬吠荜门前，遥惊石榻眠。","携来双竹杖，穿破一林烟。","袖出梅花谱，囊添曲米钱。","岁寒盟不负，同醉白云边。"]},{"t":"晓起看梅","f":"五言律诗","c":["花神催晓梦，枕上忽闻馨。","路指梅林白，尊携竹叶青。","萝衣沾宿露，藜杖带寒星。","积雪看如絮，前村作杳冥。"]},{"t":"秋夜汝大见访留酌","f":"五言律诗","c":["故人当夜至，倒屣出相迎。","坐久诗情发，霜寒酒力轻。","残更听渐促，微月欲西倾。","分手柴门寂，惟闻天籁声。"]},{"t":"哭同年黄绍馨孝廉","f":"五言律诗","c":["同领乡书者，才名君最先。","赋成栖鹏日，笔绝获麟年。","堂有双黄发，家无二顷田。","交情尽一哭，泪洒寝门前。"]},{"t":"喜林逸民山人再至","f":"五言律诗","c":["相见各欢悲，风光异昔时。","如何赤城客，又赴白云期。","情以重来密，诗从别后奇。","试看双鬓里，添得几茎丝。"]},{"t":"春日閒居 其一","f":"五言律诗","c":["草阁春方暮，柽阴日未斜。","蜗涎分断壁，莺语共邻家。","曲坞藏脩竹，轻云覆落花。","卑栖有至性，长此卧烟霞。"]},{"t":"春日閒居 其二","f":"五言律诗","c":["茅屋依青嶂，蒲团坐白云。","新茶烧竹煮，老柏杂香焚。","壁古苔纹见，林深鸟语闻。","冥心忘早晚，花外已斜曛。"]},{"t":"春日閒居 其三","f":"五言律诗","c":["一室通幽径，群峰列翠屏。","空阶半夜雨，新竹几行青。","山果猿争拾，岩扉鹤自扃。","花间闻剥啄，客借太玄经。"]},{"t":"春日閒居 其四","f":"五言律诗","c":["焚香坐翠微，山色入荆扉。","日午鸟啼歇，门閒人迹稀。","休粮孤鹤瘦，积雨野蔬肥。","欲识静中意，白云天际飞。"]},{"t":"宿陈七吸江亭","f":"五言律诗","c":["高谈当子夜，人世几今宵。","共步芦中月，因歌竹外桥。","孤琴清澹露，寒磬落归潮。","此地堪栖隐，频来岂用招。"]},{"t":"乌石山赠僧","f":"五言律诗","c":["鹫岭白云边，茅庵只数椽。","污泥皆净土，人境即诸天。","山现空中色，花明定后禅。","蒲团今已烂，趺坐不知年。"]},{"t":"风雨","f":"五言律诗","c":["风雨来何骤，虚堂白昼阴。","木催愁破屋，巢落不归禽。","水入花畦乱，云埋竹坞深。","残虹开晚霁，飞瀑满遥岑。"]},{"t":"宿林熙工面壁洞 其一","f":"五言律诗","c":["精舍锦溪东，依然梵宇同。","一灯禅榻寂，孤磬世缘空。","花散诸天雨，松生万壑风。","池光与月色，相对意无穷。"]},{"t":"宿林熙工面壁洞 其二","f":"五言律诗","c":["古洞傍岩阴，烟萝一径深。","白云皆幻迹，碧草自禅心。","日午风幡影，月明霜磬音。","已空人我相，任是世人寻。"]},{"t":"同林熙吉邓汝高游锦溪竹林","f":"五言律诗","c":["一路尽苍苔，浓阴画不开。","山依迂涧转，泉逐断桥来。","同坐松间石，还倾竹下杯。","隔溪烟磬晚，欲别又迟回。"]},{"t":"水西迟陈伯孺不至","f":"五言律诗","c":["之子来何暮，相思漫倚楼。","望穷平楚月，魂断锦溪流。","对酒不成醉，看云何处留。","几回沙浦上，数尽往来舟。"]},{"t":"送陈十二仲溱归柯屿幽居","f":"五言律诗","c":["怜君复失意，别我向南还。","落日□□渡，春风柯屿山。","马行青草远，人语绿杨閒。","归去应垂钓，溪流第几湾。"]},{"t":"过白云寺","f":"五言律诗","c":["寻僧到白云，便觉远尘氛。","古道少人迹，流莺处处闻。","泉声归涧寂，山色过桥分。","坐听疏钟起，空林正夕曛。"]},{"t":"送刘季德还岭南","f":"五言律诗","c":["尽此一杯酒，送君心黯然。","魂飞瘴岭外，路指海云边。","春老花随马，潮平月到船。","相思当后夜，闽粤异风烟。"]},{"t":"送张叔韬博士自永嘉还长溪","f":"五言律诗","c":["青毡坐未煖，白马永嘉还。","梦绕龙湫水，门当天姥山。","悲风起渡口，落月伤离颜。","一望一惆怅，思君空闭关。"]},{"t":"怀郑四琰客边","f":"五言律诗","c":["仗剑干明主，壮心殊未休。","风尘闽海梦，烟月蓟门游。","相忆坐与卧，去家春又秋。","君怀弃繻志，当斩楼兰头。"]},{"t":"送黄博士典试之楚 其一","f":"五言律诗","c":["送汝正秋初，河桥柳渐疏。","忽飞闽海鹢，去食武昌鱼。","湖水连官驿，湘云拥使车。","圣朝方急士，早上荐贤书。"]},{"t":"送黄博士典试之楚 其二","f":"五言律诗","c":["万里楚天色，君行意若何。","收将和氏璞，听遍郢人歌。","帆影洞庭尽，马蹄衡岳多。","胜游知有赋，莫惜吊湘娥。"]},{"t":"送周乔卿","f":"五言律诗","c":["交驩才半载，岁晏复离群。","马上程三日，囊中钱几文。","行藏元似寄，世态总如云。","莫笑吾贫甚，梅花可赠君。"]},{"t":"歌者陈郎戏作姬妆即席调赠","f":"五言律诗","c":["梨园推丽质，结束作妖姬。","妙舞风前合，清歌云外迟。","綵衣裁袖窄，翠钿压眉低。","何必悲黄鹄，愁多貌不移。"]},{"t":"建溪中秋怀马季声诸子","f":"五言律诗","c":["对君不能欢，乡心有万端。","青天一片月，白社几人看。","叶落知林瘦，溪深觉夜寒。","南飞见乌鹊，何意独凭栏。"]},{"t":"关门晓发","f":"五言律诗","c":["关门何处通，路入乱云中。","鸡唱逐残月，马蹄随晓风。","泉飞秋涧响，叶尽暮山空。","感此封疆异，离心谁与同。"]},{"t":"九日集张幼于曲水草堂","f":"五言律诗","c":["虚亭来爽气，秋色满疏篱。","楚客纫兰佩，吴姬唱竹枝。","假山遥对户，曲水暗通池。","不负登高兴，浑忘故国思。"]},{"t":"寄惟起弟","f":"五言律诗","c":["别来音信稀，忆汝忽沾衣。","细雨孤帆远，长天一雁微。","魂随青嶂断，梦与白云违。","明岁黄花节，知余归未归。"]},{"t":"浒墅关逢王百谷","f":"五言律诗","c":["才作吴门别，重逢在水涯。","青蚨沽绿酒，彩鹢载黄花。","坐久潮初满，谈深日易斜。","虎邱一片月，相送到京华。"]},{"t":"金昌赠钱功父","f":"五言律诗","c":["半偈庵头别，春风又几年。","相逢犹问姓，感旧各茫然。","尔我形容改，江湖梦寐牵。","此心倍悲喜，莫怪太留连。"]},{"t":"云间旅情","f":"五言律诗","c":["一帆辞槜李，两日到云间。","江路依松转，柴门映竹关。","颜随秋色老，梦逐暮潮还。","忽听华亭鹤，怅然思旧山。"]},{"t":"京口夜泊迟陈大不至","f":"五言律诗","c":["落日横京口，停云更黯然。","经旬同去住，此夕异风烟。","目断寒芦外，魂销短烛前。","榜歌频起听，永夜不能眠。"]},{"t":"同彭正休陈子卿游金山遇张函一孝廉闵寿卿山人恩公若公","f":"五言律诗","c":["万顷江如练，中流涌翠微。","浪翻孤塔影，云恋定僧衣。","客路同声少，空门聚首稀。","斜阳各南北，惆怅水烟飞。"]},{"t":"同陈子卿过广陵访夏玄成吴叔嘉留饮席上分得灯来二字 其一","f":"五言律诗","c":["岁晚天涯客，孤舟度广陵。","论交疑是梦，对酒喜如渑。","郭静涛声远，天寒露气凝。","不愁归路黑，江上有渔灯。"]},{"t":"同陈子卿过广陵访夏玄成吴叔嘉留饮席上分得灯来二字 其二","f":"五言律诗","c":["客路逢知己，飘零未可哀。","冻云依树合，残月隔花来。","喜对高阳侣，惭非邺下才。","观涛吾有赋，秉烛为君裁。"]},{"t":"酬陆无从率尔见赠之作","f":"五言律诗","c":["陆氏机云后，谁当夫子贤。","赋能工白雪，官已薄青毡。","地僻门如水，庭閒草似烟。","芜城分手处，感激赠新篇。"]},{"t":"交河早发","f":"五言律诗","c":["京华望不极，晓起戒行程。","马怯霜桥路，鸡残月店声。","晨光催断角，暝色破孤城。","此际栖栖者，思乡无限情。"]},{"t":"河间宵征","f":"五言律诗","c":["不尽风尘苦，宵行路更难。","清霜蛩语急，斜月马蹄寒。","砧捣闺心碎，笳吹乡梦残。","驿楼看尚远，何处解征鞍。"]},{"t":"忆故园梅花","f":"五言律诗","c":["衰柳长途恨，寒梅故国思。","微霜虚矮屋，残月冷疏篱。","陇外人难寄，林中客到谁。","藤山欢赏处，又是隔年期。"]},{"t":"北地","f":"五言律诗","c":["北地非吾土，重游信可哀。","鸦声喧白骨，马足起黄埃。","野旷衰杨柳，田荒变草莱。","江南风物好，一望一徘徊。"]},{"t":"至京","f":"五言律诗","c":["客途劳役息，帝里物华新。","马踏交河月，莺传上苑春。","曙光开柳陌，云气恋枫宸。","应待临轩日，抽毫赋大人。"]},{"t":"辛夘除夜姑蔑舟中","f":"五言律诗","c":["客路行无尽，终天恨转深。","乾坤乌鸟泪，风雨狖猿吟。","爆竹催残腊，梅花忆故林。","未能委沟壑，聊慰北堂心。"]},{"t":"送郭士龙","f":"五言律诗","c":["送尔不能歌，相看意若何。","离心寄云水，春梦隔关河。","草色晴尤媚，莺声暖渐和。","梁间悬榻在，莫惜数来过。"]},{"t":"送叶廷荩","f":"五言律诗","c":["我本倦游者，送君增苦颜。","潮声螺女渡，归梦壶公山。","春色莺啼外，行程鸟道间。","所嗟璚树远，何日更追攀。"]},{"t":"病中得王少文诗","f":"五言律诗","c":["山楼才信宿，偃卧各经旬。","负此看花约，蹉跎欲暮春。","诗从愁里荅，神向梦中亲。","谁复怜同病，相思长苦辛。"]},{"t":"哭张隐君","f":"五言律诗","c":["先令云亡日，君犹恸哭过。","芝焚方自叹，薤露忽成歌。","耆旧乡中少，交游梦里多。","因之动凄楚，肠断更如何。"]},{"t":"与惟秦夜话因怀惟起客水西","f":"五言律诗","c":["春宵何太短，忽忽已三更。","灯散疏林影，蛩传古砌声。","谈深尘虑息，坐久月华生。","为忆溪行者，应含两地情。"]},{"t":"寒食日熙吉玉生惟秦振狂伯孺少文集绿玉斋","f":"五言律诗","c":["佳节逢寒食，孤斋聚德星。","谈应同稷下，会可比兰亭。","粥煮杨花白，尊浮竹叶青。","春光能有几，取醉莫教醒。"]},{"t":"喜兴公弟游方广嵓归","f":"五言律诗","c":["犬吠竹间扉，游山客乍归。","杖头岚翠在，衣上水帘飞。","路入羚羊谷，舟停鸥鹭矶。","惭余多胜具，此地却相违。"]},{"t":"石嵩废寺","f":"五言律诗","c":["寺废久无钟，禅关掩万峰。","空廊惟卧虎，弃钵不归龙。","墙塌埋残碣，苔深翳古松。","倘非樵子引，那识往来踪。"]},{"t":"春暮送周乔卿","f":"五言律诗","c":["忽惊春已去，况复送君归。","别意有如此，前途花正飞。","蝉声风外急，山色雨中微。","后夜看明月，相思独掩扉。"]},{"t":"送林宗大之玉田","f":"五言律诗","c":["飞花满驿亭，送子出郊坰。","马影云边见，蝉声雨后听。","沙看两岸白，山到五峰青。","试向中宵望，何人是客星。"]},{"t":"送陈道育下第归玉融","f":"五言律诗","c":["怜汝复弃置，归寻海上山。","相逢俱落魄，何以破愁颜。","古渡春流外，孤城瘴雾间。","离心当此夜，空对白云閒。"]},{"t":"赠隐者","f":"五言律诗","c":["东郊称大隐，耕凿古风存。","水竹开三径，桃花自一村。","閒心馀白发，生事寄青尊。","爱尔幽栖处，依稀似鹿门。"]},{"t":"赠渔者","f":"五言律诗","c":["不作风尘客，生涯寄钓纶。","江湖孤棹远，烟雨一竿贫。","鼓枻同渔父，藏名比富春。","武陵溪尚在，为我问迷津。"]},{"t":"梦","f":"五言律诗","c":["梦里交驩者，平生识面稀。","赠香疑贾女，解佩似江妃。","锦水烟波阔，巫山云雨微。","蘧然惊醒处，清泪满罗衣。"]},{"t":"江上送惟起弟","f":"五言律诗","c":["别意孤帆远，行装一剑贫。","何堪哀痛后，复际此风尘。","旅馆常怀母，长途好爱身。","江干一杯酒，相对总沾巾。"]},{"t":"送高广文之蜀 其一","f":"五言律诗","c":["金粟台前别，征帆夕照催。","猿声巫峡听，马帐锦城开。","闽海风尘隔，巴流日夜回。","此乡多俊彦，若个子云才。"]},{"t":"送高广文之蜀 其二","f":"五言律诗","c":["蜀道难如此，分携思不穷。","秋风登剑阁，夜月度蚕丛。","客路凭羸马，离心寄断鸿。","讲堂闻尚在，好去继文翁。"]},{"t":"赠方伯书","f":"五言律诗","c":["风尘初识面，尊酒罄交驩。","人已如玄度，才能逼建安。","青云名不薄，白雪和应难。","此别何时遇，秋宵梦木兰。"]},{"t":"得舍弟吴中书","f":"五言律诗","c":["汝别三旬久，家书两度看。","帆前江月迥，马首岭云残。","路远愁装薄，秋高怯被寒。","孤身千里客，若个劝加餐。"]},{"t":"赠性言上人 其一","f":"五言律诗","c":["多年坐沃洲，此日伴师游。","白社閒中梦，丹枫客里秋。","浣衣江月冷，扶杖岭云流。","欲證无生诀，萍踪不可留。"]},{"t":"赠性言上人 其二","f":"五言律诗","c":["南朝四百寺，师在几招提。","法以莲花悟，诗将贝叶题。","游踪闽海曲，归兴秣陵西。","相见即相别，秋风惜解携。"]},{"t":"题徐氏池亭 其一","f":"五言律诗","c":["名园依北郭，避俗此盘桓。","鹤迹留苔径，莺声满药栏。","池添春雨涨，楼对暮山寒。","但得频投辖，相过意未阑。"]},{"t":"题徐氏池亭 其二","f":"五言律诗","c":["桃源何处所，此地即仙家。","林密藏春霭，楼虚纳晚霞。","轻风三径竹，微月一庭花。","晏坐尘心远，寒塘独听蛙。"]},{"t":"怀惟起弟","f":"五言律诗","c":["远客怜吾弟，离愁有阿兄。","久无鸿雁信，空听鹡鸰声。","岁月三秋晚，寒温两地情。","山斋长寂寞，日日计归程。"]},{"t":"碧山庵逢亮上人","f":"五言律诗","c":["清溪带远山，曲径入松关。","客以参禅至，僧当乞食还。","一瓢秋色澹，孤磬夕阳閒。","别去仍回首，禅房云气间。"]},{"t":"送李驿使之官雷阳","f":"五言律诗","c":["驱马将何适，微官傍海涯。","公庭饶蜃气，墟落半蛮家。","路指羊城入，山邻象郡赊。","地偏少束带，高枕咏皇华。"]},{"t":"过挹翠亭","f":"五言律诗","c":["精舍祗园近，翛然远市喧。","山光隔竹少，月色傍花繁。","松影摇虚阁，萝阴翳短垣。","小舠时可泛，彷佛武陵源。"]},{"t":"九日大风雨与黄道晦陈惟秦饮屋后小山","f":"五言律诗","c":["九日忽风雨，登高事已非。","秋声繁灌木，商意薄轻衣。","众壑浮青霭，千峰失翠微。","小山培塿甚，吟眺亦忘归。"]},{"t":"得朗公诗却寄","f":"五言律诗","c":["真僧虽出世，踪迹尚人群。","妙法登坛演，名香入定焚。","楼含孤嶂月，衲挂半溪云。","千里封题寄，新诗过所闻。"]},{"t":"哭林文烈 其一","f":"五言律诗","c":["十载神交旧，年来倍忆君。","每疑音问阔，谁谓死生分。","识面真无日，浮生总似云。","难将知己泪，一洒故人坟。"]},{"t":"哭林文烈 其二","f":"五言律诗","c":["相违三百里，消息太茫然。","对月思玄度，披图忆辋川。","讣来当此日，死去自何年。","墓木今成拱，才歌薤露篇。"]},{"t":"得宁夏消息 其一","f":"五言律诗","c":["叛卒雄心旧，元戎血刃新。","中原多戍垒，边郡半征尘。","时事何旁午，吾生实不辰。","愿闻烽火息，老作太平人。"]},{"t":"得宁夏消息 其二","f":"五言律诗","c":["乱离犹未定，百姓夜虚惊。","官府勾丁壮，乡闾练甲兵。","笳声吹陇水，杀气暗边城。","不识书生辈，何人敢请缨。"]},{"t":"至日对客","f":"五言律诗","c":["葭管灰初动，残花满故篱。","谁知开径日，正是闭关时。","短晷闺中线，生涯镜里丝。","相逢聊一醉，莫问岁华驰。"]},{"t":"渡岘江访林熙吉 其一","f":"五言律诗","c":["江路当残雪，斜阳满客衣。","林疏村店出，浪急钓船稀。","远屿临流断，罡风到岸微。","炊烟看渐近，何处是渔矶。"]},{"t":"渡岘江访林熙吉 其二","f":"五言律诗","c":["青山两岸阔，一叶度空江。","叫雁云中独，浮鸥浪里双。","霜花飘野渡，水气拍船窗。","渔唱来前浦，随风自有腔。"]},{"t":"旗山勾漏洞 其一","f":"五言律诗","c":["溪山何逶逦，数里入鸿濛。","斜日猿声外，残云鸟道中。","乱峰诸洞隐，万竹一泉通。","趺坐松间石，尘心觉尽空。"]},{"t":"旗山勾漏洞 其二","f":"五言律诗","c":["丹成不记年，古洞白云边。","众水争趋壑，孤峰欲接天。","路危逢乱石，山尽见平田。","日暮休归去，还期遇葛仙。"]},{"t":"旗山勾漏洞 其三","f":"五言律诗","c":["葛仙何处去，勾漏访遗踪。","陟巘齐攀竹，听泉独倚松。","石床荒藓合，丹灶薄云封。","转入深林外，前山又一重。"]},{"t":"旗山勾漏洞 其四","f":"五言律诗","c":["仙都在人境，一步一嵓峦。","怪石各有态，脩篁难计竿。","松烟烧处煖，萝磴坐来寒。","别去仍回首，馀生几度看。"]},{"t":"濑下晚泛","f":"五言律诗","c":["一水平如镜，西风晚度时。","茅茨燃鬼火，榛莽翳神祠。","潮势冲溪尽，峰形过濑奇。","山川劳应接，进艇不嫌迟。"]},{"t":"登岸","f":"五言律诗","c":["兰若知何处，跻攀尚数程。","逢沙愁濑浅，登岸得舟轻。","古石莓苔色，空林猿鸟声。","除将樵采者，更有几人行。"]},{"t":"山行","f":"五言律诗","c":["脩竹夹篮舆，岚光欲染裾。","小桥流水急，古路冻云疏。","村屋乘冬结，山田隔岁锄。","空林闻犬吠，不异武陵居。"]},{"t":"放船","f":"五言律诗","c":["孤舟回乱石，流水响潺湲。","渔网蒹葭外，人烟竹柏间。","断云迷晚渚，残照下秋山。","远寺昏钟起，樵歌出谷还。"]},{"t":"赠潮上人","f":"五言律诗","c":["真僧住洞天，苦行已多年。","说法苔衣上，安禅瀑布边。","瓢餐千涧月，衲挂半林烟。","夜静诸缘息，跏趺久不眠。"]},{"t":"赠波上人","f":"五言律诗","c":["随师居净土，礼佛向空门。","夜半磬犹击，旬中发几髡。","蒲团同鹤睡，贝叶借猿翻。","壁挂袈裟湿，因过雪里村。"]},{"t":"别方广岩","f":"五言律诗","c":["灵境探应遍，言寻旧路归。","殷勤记嵓石，惆怅别林扉。","出洞寺全隐，下山泉渐微。","行行频矫首，人世到来稀。"]},{"t":"春日晓起","f":"五言律诗","c":["山色犹含暝，柴门逐晓开。","流星坠高柳，湿雾隐残梅。","出谷莺声冷，巢林鹤梦回。","无缘独吟眺，春意满莓苔。"]},{"t":"送郑承武之东鲁 其一","f":"五言律诗","c":["送君当此去，匹马向东阿。","夜泪灯前尽，春愁梦里多。","乱云过泗水，斜日下黄河。","虽有远游兴，能无思薜萝。"]},{"t":"送郑承武之东鲁 其二","f":"五言律诗","c":["惜别意何长，莺声满夕阳。","残碑问邹峄，遗殿吊灵光。","下马多新店，逢人少故乡。","归期须及早，莫待寄衣裳。"]},{"t":"晚至石竹山","f":"五言律诗","c":["寻真当薄暮，暝色满松关。","绝壁猿声断，遥空鹤影还。","云边春草路，天际夕阳山。","应识仙都近，钟声杳霭间。"]},{"t":"月夜度石梁登摘星台","f":"五言律诗","c":["四野苍烟暝，千峰夕照催。","踏兹明月影，独上摘星台。","山自鸿濛剖，人从鸟道来。","石梁称险绝，不用说天台。"]},{"t":"赠岩上人","f":"五言律诗","c":["昔住毗卢殿，今居石竹山。","春云禅衲煖，夜月梵钟閒。","香积供狙饭，禅房倩鹤关。","平生爱空寂，相对欲忘还。"]},{"t":"石竺山迟陈道育不至","f":"五言律诗","c":["正苦经年别，终违数里程。","谈应虚玉麈，梦已断瑶笙。","报客空劳鹤，怀人独听莺。","一灯松影里，吟卧若为情。"]},{"t":"读顾道行先生碑刻","f":"五言律诗","c":["使者登攀处，春风又几年。","诗留孤嶂里，人老五湖边。","屐齿埋荒藓，碑棱隐断烟。","摩厓惬幽赏，惆怅隔山川。"]},{"t":"东郊晚行","f":"五言律诗","c":["出郭高舂后，郊原起夕阴。","山山曳残雨，步步响新禽。","老树莓苔厚，空林紫翠深。","招提何处所，云际有钟音。"]},{"t":"涌泉废寺 其一","f":"五言律诗","c":["古寺荒凉久，凄然感废兴。","残灰六十载，破衲两三僧。","黠鼠据香积，妖狐吹佛灯。","黄金重布地，不识有谁能。"]},{"t":"涌泉废寺 其二","f":"五言律诗","c":["净室已丘墟，荆榛久未除。","空山樵子路，前代梵王居。","石柱颓残后，金身煨烬馀。","披云寻故址，一步一踌躇。"]},{"t":"喝水岩赠瓢庵头陀","f":"五言律诗","c":["何年此卓锡，钟磬度昏朝。","瀑水引归钵，茅庵结似瓢。","蹑云双草屩，坐月一团焦。","隔寺有禅侣，相寻不惮遥。"]},{"t":"灵源洞怀振狂在杭","f":"五言律诗","c":["南郭人何处，东山屐已非。","春风忆苕水，夜月梦芦矶。","以我招寻惯，如君同调稀。","摩挲旧题刻，空见白云飞。"]},{"t":"拟送僧归日本 其一","f":"五言律诗","c":["远指扶桑外，龙宫是绀园。","慈航寻海舶，晨磬待朝暾。","已悟西方教，渐通中国言。","悬知无佛处，师去定称尊。"]},{"t":"拟送僧归日本 其二","f":"古风","c":["遥天迷去住，但看指南车。","重译同归舶，阳侯护法书。","?风心自定，海怪咒堪除。","此去无禅侣，应寻绝岛居。"]},{"t":"拟送僧归日本 其三","f":"五言律诗","c":["归程兼昼夜，天水共微茫。","但指日出处，此中吾故乡。","皈依多獦獠，供养有夷王。","遥想珠龛下，常焚异国香。"]},{"t":"拟送僧归日本 其四","f":"五言律诗","c":["别去上星槎，沧溟道路赊。","夷音宜咒呗，左衽自袈裟。","演法从天竺，传灯到海涯。","不知千劫里，何劫到中华。"]},{"t":"病僧 其一","f":"五言律诗","c":["苦厄那能度，医王亦抱疴。","苔侵双屐湿，尘翳一瓢多。","锡杖频扶手，金刚为伏魔。","跏趺在禅榻，或恐是维摩。"]},{"t":"病僧 其二","f":"五言律诗","c":["闻钟苦夜长，形影自凄凉。","忏悔除前障，呻吟检古方。","坐非同面壁，卧岂倦津梁。","气运有时尽，千花塔里藏。"]},{"t":"集郑氏乌石别墅 其一","f":"五言律诗","c":["众山环曲径，乱竹掩衡门。","塔影云中寺，人烟郭外村。","新蝉喧白昼，归鸟报黄昏。","此地清幽甚，依稀似习园。"]},{"t":"集郑氏乌石别墅 其二","f":"五言律诗","c":["虽是居城市，却无城市喧。","僧归残雨寺，樵度隔云村。","花落鸟声歇，草多萤火繁。","斜阳人散后，留鹤守柴门。"]},{"t":"法云寺对月","f":"五言律诗","c":["空界云阴敛，祗园月色澄。","光生初动磬，影送未归僧。","入水悟禅意，照林疑佛灯。","更阑纵吟眺，衣上露华凝。"]},{"t":"挽陈太学 其一","f":"五言律诗","c":["龙驾南巡日，何人批逆鳞。","谁知伏阙者，却是布衣臣。","抗疏青云薄，忧时白发新。","至今遗庙在，蘋藻自千春。"]},{"t":"挽陈太学 其二","f":"五言律诗","c":["欲回江汉辇，痛哭叩重阍。","死谏孤臣节，生还圣主恩。","青山藏疏草，白日照忠魂。","寂寞荒坟上，西风啼暮猿。"]},{"t":"树下禅僧 其一","f":"五言律诗","c":["跏趺依古树，偃息对峰阴。","草屩莓苔湿，麻衣烟霭深。","猿啼知定性，叶落见禅心。","明日随缘去，游踪何处寻。"]},{"t":"树下禅僧 其二","f":"五言律诗","c":["老树不知年，无言息树边。","着头多雀秽，遍体有蜗涎。","木叶寒时佩，花裀定后眠。","月中行客过，疑是野狐禅。"]},{"t":"过郑吏部墓 其一","f":"五言律诗","c":["荒坟不计年，过客泪潸然。","朽骨藏于此，吟魂何处边。","野狐啼暮雨，石马卧秋烟。","安得斯人起，重令大雅传。"]},{"t":"过郑吏部墓 其二","f":"五言律诗","c":["西郭冢累累，经过下马谁。","先生一抔土，词客百年悲。","藤护将崩石，苔封未断碑。","应知灵爽在，叹我不同时。"]},{"t":"赠史使君 其一","f":"五言律诗","c":["风流史使君，三载竹符分。","吏舍积青草，公庭生白云。","山城有弦诵，瘴海无妖氛。","父老关门送，不持钱一文。"]},{"t":"赠史使君 其二","f":"五言律诗","c":["一麾初出守，三十已专城。","露冕诸侯贵，攀辕百姓情。","俸贫难养鹤，庭静但闻莺。","试看长溪水，惟君能共清。"]},{"t":"赠黄生懋政","f":"五言律诗","c":["怜君湖海客，寄迹少年场。","音律周公瑾，丹青顾长康。","侠常弹短剑，贫不厌空囊。","名姓应难问，多于酒肆藏。"]},{"t":"过郑君大白云庄","f":"五言律诗","c":["何处辨山家，轻云处处遮。","乱峰围拱木，一径入梅花。","草榻依林设，柴门逐水斜。","主人无所事，杯酒送年华。"]},{"t":"晚泊七里滩","f":"五言律诗","c":["寒云生近浦，落日满前汀。","旅梦惊潮破，渔歌过濑停。","一竿秋水碧，孤棹晚山青。","向夕推篷望，中天见客星。"]},{"t":"山中古庙 其一","f":"五言律诗","c":["山深香火微，庙宇冷斜晖。","壁古龙蛇暗，厨荒鼠雀饥。","岁时村妇拜，水旱土人祈。","箫鼓田间过，知为祭赛归。"]},{"t":"山中古庙 其二","f":"五言律诗","c":["一路人烟绝，空山见古坛。","鼎存周款识，像塑汉衣冠。","鸟迹残碑篆，虬枝老树蟠。","可怜年代久，风雨庙门寒。"]},{"t":"山中古庙 其三","f":"五言律诗","c":["古庙白云边，神妆尚俨然。","灵应山鬼托，龛任野狐眠。","开刱知何代，销沉不计年。","居民流窜尽，累岁断香烟。"]},{"t":"元直秀才观微上人过宿","f":"五言律诗","c":["风流看许掾，定慧得支公。","白社当年结，清言此夕同。","乱蛩吟竹坞，一犬吠花丛。","相对残灯下，能令尘虑空。"]},{"t":"送瀚上人游越 其一","f":"五言律诗","c":["师行无定踪，此去路千重。","投宿月中寺，经过雪里峰。","閒身临水衲，禅意隔潮钟。","明岁西湖上，相寻九里松。"]},{"t":"送瀚上人游越 其二","f":"五言律诗","c":["虽云游浙水，未必浙中游。","遇客皆为侣，逢山便可留。","独行半风雪，一别几春秋。","所惜谈诗夜，从今少惠休。"]},{"t":"送瀚上人游越 其三","f":"五言律诗","c":["真僧欲度世，岂肯倦津梁。","白足他山月，缁衣满路霜。","一灯传异代，六祖是同乡。","此去逢行脚，新诗好寄将。"]},{"t":"得谭比部寄先永宁书感而赋答","f":"五言律诗","c":["凄风生敝庐，忽枉故人书。","不复知存没，犹然问起居。","一缄千里外，双泪几年馀。","孔李通家旧，毋令鱼雁疏。"]},{"t":"送危博士之官马平","f":"五言律诗","c":["茫茫江水阔，相送片帆孤。","炎海川途远，蛮天气候殊。","瘴烟发青草，云树黯苍梧。","想到谈经日，三鳣坠有无。"]},{"t":"送陆画师还钱塘","f":"五言律诗","c":["客怀当暮冬，去矣不从容。","草屩千峰雪，柴门九里松。","贫惟安豹隐，老任笑龙钟。","为问经行处，云山貌几重。"]},{"t":"峬山看梅过曾文表墓","f":"五言律诗","c":["一路尽氤氲，看花倍忆君。","白杨知己泪，宿草故人坟。","树影含残照，猿声哭暮云。","凄凉身后事，地下可能闻。"]},{"t":"送杨太学之金陵","f":"五言律诗","c":["劳歌动别筵，酒散各云天。","折柳当春暮，看花正少年。","莺声孤店月，草色六朝烟。","无限怀人意，金陵何处边。"]},{"t":"故黎平太守袁公挽歌 其一","f":"五言律诗","c":["永别城中路，新成郭外坟。","旐题前太守，书失右将军。","广柳驱残月，甘棠翳暮云。","应知千载后，不朽是遗文。"]},{"t":"故黎平太守袁公挽歌 其二","f":"五言律诗","c":["谁知五马客，竟作九原人。","出郭有魂气，还家惟影神。","墓中难待晓，地下不行春。","斯世无同调，悲歌泪满巾。"]},{"t":"故黎平太守袁公挽歌 其三","f":"五言律诗","c":["白马出关门，愁闻鼓吹喧。","山灵收正气，月色引归魂。","贵至二千石，书馀几万言。","翩翩丹旐过，犹讶转朱轓。"]},{"t":"故黎平太守袁公挽歌 其四","f":"五言律诗","c":["赤绂人何处，青山骨可藏。","乡邻悲道路，父老泣蛮方。","图史虚东壁，松楸冷北邙。","明君思起草，犹问秘书郎。"]},{"t":"林伯仪自金陵还莆过访话别","f":"五言律诗","c":["为客经淮楚，归途访索居。","云山一骑远，烟柳六朝疏。","问路知乡近，还家及岁除。","陆生装薄甚，惟有一囊书。"]},{"t":"癸巳除夕","f":"五言律诗","c":["又见韶华换，空为老大悲。","齿添新岁历，酒祭一年诗。","流落忧前路，欢娱忆少时。","生憎箫管恶，苦向隔邻吹。"]},{"t":"送邓汝高进士还朝 其一","f":"五言律诗","c":["献岁赴王程，全家向北平。","断冰淮口渡，残雪蓟门城。","烟柳迷征盖，风花引使旌。","长安春色好，莫起故园情。"]},{"t":"送邓汝高进士还朝 其二","f":"五言律诗","c":["柳色催离况，椒花恋别筵。","梦繁人去后，春到客行先。","挂席河通楚，驱车路向燕。","相思明月夜，惆怅隔山川。"]},{"t":"游通谷洞","f":"五言律诗","c":["小径斜通谷，跻攀及晚晴。","草荒寻鸟道，磴险作蛇行。","暮色千峰合，春流一镜平。","石间旧题刻，半是紫苔生。"]},{"t":"登乌石山","f":"五言律诗","c":["绝巘分青霭，高台接绛霄。","钟声多近寺，墨迹半前朝。","径小疑藏洞，山穷忽遇桥。","凭栏时纵目，沧海望中遥。"]},{"t":"同微师至面壁洞","f":"五言律诗","c":["竹径云阴乱，松门夜色虚。","佛多同客礼，洞半借僧居。","幡动风来后，钟残月上初。","何须别栖隐，此地即吾庐。"]},{"t":"题惟扬弟法云寺书舍","f":"五言律诗","c":["谁知菩萨界，亦有子云居。","厨趁僧炊后，膏分佛照馀。","窗窥施食鸟，笥窜蠹经鱼。","方衲时相叩，秖应来借书。"]},{"t":"绝粒僧","f":"五言律诗","c":["苦行凡心绝，休粮道气清。","斋惟供弟子，食不乞王城。","已觉形骸幻，能令香味轻。","云游经处处，不用载瓢行。"]},{"t":"送颜廷愉将军料兵海坛山","f":"五言律诗","c":["少年初建节，走马向孤城。","蜃气云中市，狼烟海上营。","晓霜明雪戟，夜月捲霓旌。","幕府防秋急，看君独请缨。"]},{"t":"同微公元直兴公弟至鼓山","f":"五言律诗","c":["看山俗虑清，况复与僧行。","径密草交色，林回鸟换声。","披云孤衲重，挂月一瓢轻。","不用忧迷路，灯光见化城。"]},{"t":"鼓山寺","f":"五言律诗","c":["空门有夙因，岁岁往来频。","方丈墨犹湿，祇园花又新。","佛应怜熟客，山但借閒人。","不分居城市，红尘老此身。"]},{"t":"灵源洞与微公赋","f":"五言律诗","c":["洞藏青嶂里，路出白云层。","苔色侵禅榻，松阴暗佛灯。","树撑危石坠，藤束古崖崩。","不用寻僧语，同游自有僧。"]},{"t":"赵用拙招游白云洞迷路而返却寄","f":"五言律诗","c":["古洞知何处，山僧路亦迷。","行来千嶂外，犹隔数峰西。","径险猿难度，林深鸟自啼。","渔郎真梦境，浪说武陵溪。"]},{"t":"喜果慧禅师见访","f":"五言律诗","c":["多年居古洞，偶尔到王城。","老益禅心定，贫谙世谛轻。","空犹嫌有相，火久断无明。","再拜求真偈，流传度众生。"]},{"t":"赠赵用拙居士","f":"五言律诗","c":["留发不披缁，行藏众所疑。","慧因闻道早，壮悔出家迟。","果以今生满，僧应夙世为。","悬知他日遇，改却旧须眉。"]},{"t":"问伯孺病","f":"五言律诗","c":["时事已如此，看君转自愁。","不堪燃桂苦，况抱采薪忧。","药以何钱买，粮应几日休。","妻儿皮骨在，相向泪交流。"]},{"t":"赠张少府 其一","f":"五言律诗","c":["恋越终辞楚，幽栖似鹿门。","烟霞长作侣，车马不闻喧。","世事惟高枕，生涯只灌园。","自耽泉石趣，岂是学桃源。"]},{"t":"赠张少府 其二","f":"五言律诗","c":["黑发弃轩冕，归耕南亩田。","不飞云外舄，时挂杖头钱。","野性耽丘壑，幽居远市廛。","中峰高隐处，长抱白云眠。"]},{"t":"甲午赴京留别社中诸子","f":"五言律诗","c":["瓠落甘南郭，飘零又北征。","愁心悲远道，短发恋微名。","别苦嫌情重，时危幸橐轻。","劳歌听已惯，任作断肠声。"]},{"t":"别陈惟秦","f":"五言律诗","c":["劳歌君莫吟，吟即泪沾襟。","若比前年别，此情应更深。","梦能知道路，交只恋山林。","何处还相忆，天涯一片心。"]},{"t":"溪行即事寄汝翔平夫","f":"五言律诗","c":["客路空回首，浮生未息机。","愁多难得醉，梦短不成归。","石势流边缺，滩声过后微。","翻因旅泊处，转忆旧渔矶。"]},{"t":"泊黯淡滩登观音寺","f":"五言律诗","c":["古寺俯空滩，溪深客到难。","浪疑南海涌，山作普陀看。","幡影临流湿，钟声出谷寒。","禅心如止水，元不碍风湍。"]},{"t":"金凤山逢许道人","f":"五言律诗","c":["高人隐洞天，鸟道入云烟。","且莫论真诀，大都无世缘。","丹炉长自爇，火候岂轻传。","别去不留意，相逢皆偶然。"]},{"t":"渔梁道中怀叶志卿","f":"五言律诗","c":["当年联辔处，已是七周星。","野店曾同宿，流泉忆共听。","殊音来往客，愁思短长亭。","不尽怀乡感，因君增涕零。"]},{"t":"七里滩夜泛","f":"五言律诗","c":["严滩行未尽，雨气逼黄昏。","峡束天疑小，溪深水不浑。","榜歌何处客，灯影几家村。","最是堪愁绝，三声半夜猿。"]},{"t":"桐庐晓发","f":"五言律诗","c":["挂帆山县晓，云气满溪阴。","虽有风尘役，能无丘壑心。","人烟依水近，塔影坠江深。","所叹垂纶者，高踪不可寻。"]},{"t":"紫阳洞","f":"五言律诗","c":["石室奇如此，全无斧凿痕。","虚岩悬作屋，曲窦巧成门。","避日晴犹湿，屯云昼自昏。","平生游历惯，到此亦惊魂。"]},{"t":"三茅观寻许灵长不遇","f":"五言律诗","c":["山色翠氤氲，松关闭白云。","礼星孤磬发，受箓妙香焚。","夜静天花落，秋高木叶闻。","无由寻许掾，长揖问茅君。"]},{"t":"寄怀黄道晦 其一","f":"五言律诗","c":["各送皆先别，君留更一宵。","江头两分手，相对各魂销。","南望驿楼远，北看帆影遥。","折来亭畔柳，此日定萧条。"]},{"t":"寄怀黄道晦 其二","f":"五言律诗","c":["长贫家累少，有道世缘轻。","山许高人占，田归别主耕。","老惟安落魄，隐不爱虚名。","下榻怜吾弟，秋来几到城。"]},{"t":"晚至毗陵","f":"五言律诗","c":["榜人穷日力，向晚到荆溪。","近驿舟航满，沿城灯火齐。","角声悲断续，山色黯东西。","客子愁无寐，昏雅莫乱啼。"]},{"t":"句曲道中望茅山","f":"五言律诗","c":["停车句曲望，缥缈见仙家。","旷野分青霭，遥天结紫霞。","山秋生异草，溪午出胡麻。","欲證延年诀，其如道路赊。"]},{"t":"游牛首山弘觉寺","f":"五言律诗","c":["前身疑老衲，所至爱禅林。","肯惜跻攀力，偏宜清净心。","山钟吴地秀，园布汉时金。","日午僧寮寂，岩扉闭塔阴。"]},{"t":"牛首祖堂寻雪浪禅师不遇","f":"五言律诗","c":["云气掩禅栖，山空鸟自啼。","塔阴依日转，铃语坠风低。","白社虚牛首，青山费马蹄。","无由问真偈，归路夕阳西。"]},{"t":"鸡鸣寺赠印空上人","f":"五言律诗","c":["不用觅三车，心能转法华。","问年忘岁月，留客借云霞。","乞食朝行脚，焚香夜结跏。","志公金骨在，长日礼干花。"]},{"t":"喜林天懋至得家书","f":"五言律诗","c":["故人传信至，喜极却忘餐。","虽有平安字，未开犹胆寒。","算程何日寄，秉烛几回看。","两月思乡泪，今宵应暂乾。"]},{"t":"卢子明张子明何性中胡彭举林叔度小集客舍","f":"五言律诗","c":["客中方落莫，诸子偶来过。","有相皆丘壑，无言非薜萝。","红尘穷巷少，青眼异乡多。","总是飘蓬者，为欢能几何。"]},{"t":"瓦棺寺赠全上人","f":"五言律诗","c":["禅房云气深，一榻傍蕉阴。","不种生天果，常怀出世心。","鹫峰脩白业，象教礼黄金。","何以精名理，先师有道林。"]},{"t":"同陆纂父郭圣仆雨夜集曹重甫客舍得凉字","f":"五言律诗","c":["客居非蒋径，亦自过求羊。","绿酒人来贳，黄花节后香。","敝裘霜气肃，残烛雨声凉。","漏尽欲为别，秋宵苦不长。"]},{"t":"送何性中还回稽","f":"五言律诗","c":["之子竟落魄，故人空断魂。","烟霞归旧隐，风雨出关门。","红叶足秋色，白衣多泪痕。","看君年尚少，莫即恋丘园。"]},{"t":"送王献子山人客粤西","f":"五言律诗","c":["君行当象郡，投宿尽蛮家。","椰暗黎村叶，梅寒庾岭花。","神符宵厌蛊，人面昼防蛇。","若到南中日，先寻勾漏砂。"]},{"t":"送林吾宗南还时余将入燕","f":"五言律诗","c":["相逢虽暂喜，相别倍含情。","渡水雁孤影，出关鸡一声。","愁从归路减，寒近故乡轻。","所叹飘零者，风霜向北平。"]},{"t":"送林叔度之庐江寻刘使君","f":"五言律诗","c":["怜君方倦游，岁晚复依刘。","衰草逢霜死，寒涛逐雪流。","淮南丛桂老，江北荻花秋。","渡口一相送，目穷天际头。"]},{"t":"题静海寺庆良上人房","f":"五言律诗","c":["入寺已高舂，禅关暮霭封。","潮喧临水梵，云引过江钟。","驯象诸天教，卢龙近郭峰。","几年湖海别，此地又相逢。"]},{"t":"灵谷寺","f":"五言律诗","c":["一径万松通，钟山俯梵宫。","谷声虚应掌，塔影峻凌空。","不坏金身古，无梁宝殿雄。","未忘生灭相，长此泣遗弓。"]},{"t":"咏雨中新草","f":"五言律诗","c":["烧痕才转绿，含雨未萋萋。","且缓佳人斗，方闻玉勒嘶。","苔深看莫辨，柳亚望初齐。","为语寻春者，无令踏作泥。"]},{"t":"不寐感怀示元直","f":"五言律诗","c":["孤馆听寒漏，灯残夜未央。","雁声悲带雨，蛩语急含霜。","旅梦醒难续，乡心醉暂忘。","念君初作客，不敢说凄凉。"]},{"t":"赠魏考叔","f":"五言律诗","c":["所居虽近市，苔锁荜门幽。","巾舄遵王制，图书应客求。","挥毫无俗韵，下榻有名流。","满壁沧洲在，依稀顾虎头。"]},{"t":"别金陵","f":"五言律诗","c":["人境元如梦，兹游真惘然。","一帆扬子月，双屐白门烟。","遇寺多留偈，逢僧尽问禅。","独馀千佛岭，待我再来缘。"]},{"t":"怀王粹夫","f":"五言律诗","c":["我游当蓟北，君隐在墙东。","两地魂俱断，中宵梦不同。","烛销山店雨，笳散戍楼风。","雪后无南雁，乡书何处通。"]},{"t":"同温允文史声伯集张稚通清远居分得留字","f":"五言律诗","c":["此地本清远，主人情更幽。","游多乘兴至，客不问名留。","坐卧半临水，往来都泛舟。","醉馀溪上别，月色满中流。"]},{"t":"天圣寺","f":"五言律诗","c":["高阁对诸峰，禅关入乱松。","断碑留赑屃，古殿错蛟龙。","尘静难侵佛，林疏不碍钟。","潇湘图满壁，彤管有遗踪。"]},{"t":"碧浪湖泛月同在杭","f":"五言律诗","c":["扁舟过碧浪，孤月出林端。","兔影摇波碎，婵娟落镜寒。","湖光澄似练，山色秀堪餐。","别后几圆缺，今宵才共看。"]},{"t":"题顾学宪先生闻禽阁","f":"五言律诗","c":["高阁傍林阿，林深众鸟过。","飞当残照急，噪向晚晴多。","振翼同呼侣，归巢各认柯。","翟公门似水，日日可张罗。"]},{"t":"赠陈道源参军","f":"五言律诗","c":["冷曹堪傲性，大雅见遗音。","衙只听莺放，山多信马寻。","一官同鲍照，五字比陈琳。","俸薄难供客，时捐卖赋金。"]},{"t":"晓至甘露寺因憩观音洞","f":"五言律诗","c":["乘晓到香台，钟残僧梦回。","岩阿精舍隐，石窦普门开。","初日跃林出，罡风跨浪来。","披榛寻旧迹，一半委苍苔。"]},{"t":"甲午汶上除夕","f":"五言律诗","c":["旅馆逢除夕，空怀故国情。","荒村三户寂，土屋一灯明。","臈逐鸡声去，春随马足生。","客中非守岁，自是梦难成。"]},{"t":"怀张道辅","f":"五言律诗","c":["婚嫁中年毕，馀生老一区。","市声穷巷寂，山色小楼孤。","林密身堪隐，田荒口仅糊。","诗僧同酒伴，日日往来无。"]},{"t":"赋得逍遥游送邬子远山人","f":"五言律诗","c":["逍遥非避世，只是爱清閒。","汎月渡千涧，随云过几山。","游同僧共往，倦与鸟俱还。","踪迹多湖海，故园长闭关。"]},{"t":"题许灵长快雪亭","f":"五言律诗","c":["亭倚吴山麓，春晴雪未乾。","色分江影白，光入石门寒。","洞古藏犹湿，墙阴销欲残。","应怜高卧者，日日映书看。"]},{"t":"题吴象文抱膝轩","f":"五言律诗","c":["越绝风流客，栖迟一亩宫。","闭门人迹少，趺坐世缘空。","帘向雪中捲，径从花里通。","主人长抱膝，或恐是隆中。"]},{"t":"送张子环下第枉道之楚寻丁亨文法曹","f":"五言律诗","c":["天涯同失路，君岂不怀归。","客久行囊罄，家贫生计微。","同来知己散，便道故人稀。","独有荆南吏，或能怜布衣。"]},{"t":"暮出茌平宿二十里村店","f":"五言律诗","c":["征车贪远宿，宿处更荒凉。","出郭才数里，几家成一乡。","灯燃绵炬暗，茶煮柳条香。","不待晨炊去，主人无晓粮。"]},{"t":"赠瑕丘灌园郭叟","f":"五言律诗","c":["胜地近洙水，主人同汉阴。","未忘为圃意，偏称耦耕心。","草色怜颜巷，柏枝分孔林。","下车聊共语，莫作凤衰吟。"]},{"t":"滋阳道中逢金陵秀峰和尚因讯雪浪耶溪秋园诸上人","f":"五言律诗","c":["如何当此地，亦得见名僧。","托尽他乡钵，传来几代灯。","烟霞生有果，云水迹无凭。","问遍南朝寺，因师住秣陵。"]},{"t":"登云龙山放鹤亭","f":"五言律诗","c":["叠嶂隐香台，门当楚水开。","河流幡影去，云引磬声来。","寺古龙犹伏，亭空鹤不回。","因寻碑上字，剔尽雨中苔。"]},{"t":"舟中书怀 其一","f":"五言律诗","c":["一别变春秋，相随半是愁。","思乡餐䪺减，感旧泪空流。","金尽羞开箧，途遥厌换舟。","非无山水兴，客久畏淹留。"]},{"t":"舟中书怀 其二","f":"五言律诗","c":["岂是依人拙，此行谁可依。","途穷胜事少，身贱势交稀。","客路儒无术，关门吏有威。","时时戒童仆，莫比昼游归。"]},{"t":"将别幼孺","f":"五言律诗","c":["离人元作恶，况复是心知。","预洒临岐泪，各抄同赋诗。","分襟愁路促，恋别愿舟迟。","童仆追随久，犹能相向悲。"]},{"t":"松陵舟中送幼孺入苕川兼柬在杭使君及苕中诸旧游","f":"五言律诗","c":["怀土情虽切，他乡且暂留。","去寻苕水吏，独作太湖游。","顾影同看烛，含啼各买舟。","我来惭父老，不敢再依刘。"]},{"t":"溪夜时与惟秦兴公游武夷","f":"五言律诗","c":["往日游都倦，兹行心独閒。","片帆投月宿，一笠戴云还。","夜色沙边水，秋光烟外山。","旅怀长似此，那解鬓毛斑。"]},{"t":"中秋遇风雨","f":"五言律诗","c":["寒溪秋色满，临汎意如何。","高枕乱流去，挂帆千嶂过。","梦应通月窟，槎已到星河。","不负烟霞想，无妨风雨多。"]},{"t":"同惟秦兴公舟中夜坐","f":"五言律诗","c":["临流趺坐久，夕露坠衣繁。","山色晚逾翠，滩声宵更喧。","林深灯避影，云重月亏痕。","不爱闻鸡犬，停舟莫近村。"]},{"t":"赠惟秦","f":"五言律诗","c":["平生隐不出，出便为寻真。","世上风波免，途中闻见新。","抛家无内顾，学道有前因。","却笑虚名客，江湖劳此身。"]},{"t":"晓发","f":"五言律诗","c":["枕上榜歌起，溪中行侣稀。","缆牵烟缕细，帆挂月痕微。","曙逐鸡声尽，涛惊客梦归。","沿洄三五里，犹未见朝晖。"]},{"t":"赠黄君甫山人","f":"五言律诗","c":["烟霞久已亲，无语到红尘。","著姓同江夏，逃名比富春。","长贫玄草客，未老白云身。","不脱吴钩赠，君家在剑津。"]},{"t":"登接笋峰","f":"五言律诗","c":["丹梯悬削壁，铁索缆萦纡。","鱼贯嵓当面，猿攀石碍趺。","气同看月喘，声各入云呼。","蜿蚺过龙脊，茅房见一区。"]},{"t":"陷石堂","f":"五言律诗","c":["缘溪下复登，山色翠层层。","洞以水流辟，石从云压崩。","落花魂卧草，空树腹吞藤。","渐觉非人境，风光近武陵。"]},{"t":"赠安道人","f":"五言律诗","c":["丹房占翠微，静极悟玄机。","玉液喉间咽，金精肘后飞。","礼经随众惯，挥麈见人稀。","岂是无家客，三年不一归。"]},{"t":"赠江仲鱼","f":"五言律诗","c":["君家虽附郭，多在武夷居。","有水皆移棹，无山不结庐。","胸全藏洞壑，交半混樵渔。","怀友秋风里，从今或到予。"]},{"t":"怀颜廷愉","f":"五言律诗","c":["流落有如此，壮心终不酬。","文多为客难，剑未报君雠。","失职辞戎幕，移居近比丘。","世情容易变，莫向灞亭游。"]},{"t":"送兴公弟游吴越","f":"五言律诗","c":["献书予未遇，弹铗汝何依。","片刺投人拙，诸侯礼士稀。","出门家累断，为客众愁归。","不必羞贫贱，诗名在布衣。"]},{"t":"题画菊赠黄博士印坤","f":"五言律诗","c":["南山相对处，篱下有馀芳。","开向三秋晚，餐来五内香。","叶同颜不老，花与发俱黄。","岁岁金风起，披图一荐觞。"]},{"t":"寄陈平夫","f":"五言律诗","c":["闻说清溪上，经年但索居。","诗因閒转废，交到老偏疏。","酒癖难全减，雄心可便除。","灯前思旧好，空检往来书。"]},{"t":"过惟秦幽居","f":"五言律诗","c":["数歇经村落，到门红日西。","柳阴牛独寝，草舍燕双栖。","野绿云千亩，郊青雨一犁。","空林烟火起，留客晚蒸藜。"]},{"t":"同郑吉甫过仁王寺怀徐仲和久客莆中","f":"五言律诗","c":["灯火佛堂虚，经行月上初。","草生游子路，松偃化人居。","春尽莺花老，天长蝶梦疏。","如何逢九鲤，不寄半行书。"]},{"t":"病","f":"五言律诗","c":["一春馀几日，况复卧文园。","山色来欹枕，莺声老闭门。","拥衾无早晚，来札半寒温。","渐觉诗签减，惟看药裹存。"]},{"t":"雨中屠田叔使君招集乌石山同钱叔达陈幼孺王粹夫曹能始兴公弟分得深字","f":"五言律诗","c":["选胜坐危岑，山高紫翠深。","受潮千涧满，翳雨半峰阴。","衣中春寒薄，钟过暮霭沈。","使君行役近，犹不废登临。"]},{"t":"送张孺愿之漳南","f":"古风","c":["离亭柳正长，匹马向临漳。","别路闻莺语，遥空起蜃光。","?风吹海暗，蛮雨洗天凉。","去去频沽酒，兹行是瘴乡。"]},{"t":"屠田叔雨中过酌草堂分得穷字","f":"五言律诗","c":["谁谓诸侯贵，来过一亩宫。","天低峰影逼，云耗雨声穷。","残溜虚檐滴，新苔怪石蒙。","惭无池馆胜，不敢醉山公。"]},{"t":"寄张成叔","f":"五言律诗","c":["杯酒片时亲，都亭各问津。","玉河堤畔柳，又见一回新。","月冷闽天梦，花明越峤春。","闻君庐墓侧，白兔向人驯。"]},{"t":"悼殇子","f":"五言律诗","c":["五日人间世，千秋骨肉情。","未能留幻质，空自试啼声。","眷属知何劫，轮回又此生。","愁心安可慰，婚嫁累尤轻。"]},{"t":"咏佛手柑","f":"五言律诗","c":["兜罗软似绵，移种到人天。","妙相终成果，清香不让莲。","交枝疑合掌，屈指欲为拳。","肯向车中掷，留将供法筵。"]},{"t":"喜康元龙归自灵武","f":"五言律诗","c":["自逐征西府，空惊两鬓斑。","尘沙过陇水，风雪度萧关。","刁斗边城暗，烽烟戍垒閒。","故园初下马，一剑在腰间。"]},{"t":"挽周候官","f":"五言律诗","c":["双凫何处飞，父老泣沾衣。","旧客云同散，虚名露易晞。","关河孤榇远，风雨旅魂归。","他日过荒陇，松楸大几围。"]},{"t":"柬陈汝大","f":"五言律诗","c":["爱君栖隐处，一室白云深。","古壁藤花乱，空庭桐叶阴。","静能销世态，老得遂閒心。","自愧嵇生懒，经年不入林。"]},{"t":"送陈可栋还松溪","f":"五言律诗","c":["相见复离群，一杯歌送君。","轻红辞荔火，寒翠梦松云。","树影缘山转，溪流向县分。","蝉声脩竹里，明日不同闻。"]},{"t":"送陈汝翔游龙虎山","f":"五言律诗","c":["布褐与黄冠，遥寻正一坛。","灵符求玉印，神鼎问金丹。","礼斗七灯焰，降魔双剑寒。","龙沙遗谶合，计日待骖鸾。"]},{"t":"送陈彦宗之永嘉","f":"五言律诗","c":["皖城归未久，又复向东瓯。","总为饥寒出，不然何所求。","帆飞瘴雨湿，衣触火云流。","纵是囊羞涩，还须雁宕游。"]},{"t":"送余印卿秀才还濉阳","f":"五言律诗","c":["相违虽不远，相送亦应难。","宝剑脱为赠，瑶琴何处弹。","行装三伏雨，孤棹百重滩。","想到家林日，犹怀荔子丹。"]},{"t":"送郑震卿之吴越寻兄","f":"五言律诗","c":["汝兄游不返，汝去远相寻。","试问孤身客，飘零何至今。","见时应恸哭，语罢定伤心。","坐待离群雁，联翩向故林。"]},{"t":"送林应卿进士理梧州","f":"五言律诗","c":["拥传过藤峡，开衙傍郁林。","苍梧寒岫翠，青草瘴云深。","蛮吏多夷礼，猺民杂土音。","此乡山水好，公暇足登临。"]},{"t":"送张公鲁还甬东","f":"五言律诗","c":["知己难为别，况逢摇落时。","断猿吟树惨，羸马过山迟。","夜月严陵濑，秋风贺监祠。","清狂怀小阮，谁共竹林期。"]},{"t":"荅赠黄君甫","f":"五言律诗","c":["家居延水濆，剑佩七星文。","竹杖干山月，荷衣五岳云。","迹多方外见，名喜世间闻。","从此辞尘网，飘飘鸾鹤群。"]},{"t":"寄朱善侯秀才","f":"五言律诗","c":["虽然盖未倾，年少即闻名。","才似王文考，狂如祢正平。","鸡坛盟越国，龙剑出丰城。","自有惊人语，看君时一鸣。"]},{"t":"哭王孔振客死泸州","f":"五言律诗","c":["飘零万里客，客死更谁依。","路远讣音缓，家贫吊者稀。","巴歌舁榇曲，橦布附身衣。","蜀道难如此，游魂归不归。"]},{"t":"哭顾道行先生","f":"五言律诗","c":["谁谓江干别，竟成生死分。","梨园翻薤露，苔馆閟萝云。","地远讣难定，天高哭不闻。","酬恩空一剑，何敢挂孤坟。"]},{"t":"送叶秀才还松溪","f":"五言律诗","c":["兹行路几重，去矣不从容。","试问君归兴，何如秋色浓。","香残霜后菊，涛响月边松。","隔断相思梦，千峰与万峰。"]},{"t":"为亲乞禄诗赠丁文统邑丞 其一","f":"五言律诗","c":["薄宦不谋身，卑栖向海滨。","暂为黄绶客，少慰白头亲。","退食称觞便，休衙问寝频。","有人犹负米，五斗莫嫌贫。"]},{"t":"为亲乞禄诗赠丁文统邑丞 其二","f":"五言律诗","c":["岂是爱微官，因承禄养欢。","公厨充菽水，海错佐盘餐。","振藻宜花县，哦松傍药栏。","浮沈元世路，莫谓折腰难。"]},{"t":"题陈幼孺招隐楼 其一","f":"五言律诗","c":["丛桂许谁攀，经年不闭关。","池平吞月浅，林静受云閒。","草色春愁外，禽声午梦间。","开窗岚翠满，疑对八公山。"]},{"t":"题陈幼孺招隐楼 其二","f":"五言律诗","c":["石磴转松阴，高楼面翠岑。","薜萝春雨细，橘柚暮烟深。","夜月喧林犬，微风掠水禽。","一丘招隐处，应慰白云心。"]},{"t":"偶成","f":"五言律诗","c":["吟咏随真性，行藏听自然。","因穷閒半世，托病谢诸缘。","乞字人催债，脩琴铺索钱。","辛勤犹一事，洗砚竹根边。"]},{"t":"题博古斋赠蒋子才","f":"五言律诗","c":["寄迹多湖海，逃名且市廛。","一区扬子宅，四壁米家船。","玉辨荆山里，书收汲冢前。","耽奇同有癖，相过定留连。"]},{"t":"元日同闵寿卿钱叔达兴公弟过定光庵访乐上人","f":"五言律诗","c":["避俗懒迎客，斋心同结缘。","树枝增一腊，柏叶禁诸天。","法供更新水，香炉宿旧烟。","空门无岁月，尘世自知年。"]},{"t":"闵孝昭送其尊人隐武夷自归广陵赋此以送 其一","f":"五言律诗","c":["忍泪别严亲，长途剑卫身。","烟花归路客，风浪渡江人。","马踏梅天雨，莺残瓜步春。","从今闽海熟，定省莫辞频。"]},{"t":"闵孝昭送其尊人隐武夷自归广陵赋此以送 其二","f":"五言律诗","c":["送父隐九曲，辞归天一涯。","他年同拔宅，此日独还家。","别梦萦芳草，征帆过落花。","无劳虑甘旨，嵓洞足烟霞。"]},{"t":"再送曹能始","f":"五言律诗","c":["此日鸣驺去，当年战胜归。","故人供别酒，关吏识行衣。","起草依丹禁，含香觐紫微。","汉廷方贵少，年少似君稀。"]},{"t":"送林兆纶游武夷","f":"五言律诗","c":["飘飘鸾鹤群，去谒武夷君。","溪曲斜流月，峰多乱占云。","石床深草色，玉简翳苔文。","半夜天坛上，一声清磬闻。"]},{"t":"送张叔麟别驾归永嘉","f":"五言律诗","c":["言别泪潸然，况君非少年。","残莺孤店雨，羸马断桥烟。","剑已分雷焕，刀犹佩吕虔。","故山邻雁宕，莫惜系书传。"]},{"t":"同吴元瀚兴公弟暮过神光庵","f":"五言律诗","c":["薜萝深处入，一径自逶迤。","待月嫌林翳，看云怯石危。","岩阴灯影晦，山静磬声迟。","虽有重来约，重来知几时。"]},{"t":"同闵寿卿柳陈父吴元瀚兴公弟避暑仁王寺因憩天秀岩","f":"五言律诗","c":["结夏依禅窟，松关闭寂寥。","摩厓猜古篆，相地徙团瓢。","赤日过林尽，红尘到寺销。","清凉元有境，人自爱炎歊。"]},{"t":"题吴元瀚小像","f":"五言律诗","c":["披缁还戴笠，独自坐崚嶒。","有相元虚妄，无言即上乘。","形将同木槁，心已似波澄。","不是旧相识，翻疑何处僧。"]},{"t":"同萧二丈林子真兴公弟微上人定上人过遇公转华庵","f":"五言律诗","c":["因与山僧熟，祗园来往频。","一时无俗客，半日有閒人。","岩树云边暮，池花水畔春。","扫除嫌太洁，翻觉此身尘。"]},{"t":"西禅寺","f":"五言律诗","c":["野旷烟光薄，林深暑气微。","乱蝉鸣觉路，一犬护禅扉。","花竹通诸径，旃檀大几围。","云房吟卧久，直到晚凉归。"]},{"t":"夏日偶成柬惟秦","f":"五言律诗","c":["何方堪避暑，胜地觅清幽。","坐选云边石，吟寻水畔楼。","偏宜山友共，唯许野僧留。","一日一丘壑，安閒直到秋。"]},{"t":"夏日园居柬履吉","f":"五言律诗","c":["山静晚凉初，僧寮寂不如。","碍云嫌竹密，受月爱藤疏。","茶熟焚香饮，诗成洗砚书。","惟君知此况，愿数过吾庐。"]},{"t":"怀元直客金陵","f":"五言律诗","c":["经年客白门，书札见寒温。","共作几回梦，各销无限魂。","听莺桃叶渡，嘶马杏花村。","欲识思君泪，请看衣上痕。"]},{"t":"送陈广文弃官还温陵","f":"五言律诗","c":["白首厌微官，沧江恋钓竿。","隐耽初服贵，老怯旧毡寒。","绿酒枌榆社，清斋苜蓿盘。","好将平子赋，时对刺桐看。"]},{"t":"送白经历入觐","f":"五言律诗","c":["迁客朝天去，王程不可留。","谁知飞鞚日，政及赐环秋。","残雪燕山路，微霜济水舟。","从来白司马，未合老江州。"]},{"t":"送钱叔达还吴兴","f":"五言律诗","c":["住伤流落久，去惜别离难。","衣上三年泪，尊前片刻欢。","西风杨柳岸，夜雨蓼花滩。","山水含孤调，从今何处弹。"]},{"t":"过惟秦响山堂","f":"五言律诗","c":["习隐栖南亩，躬耕受一廛。","激流崩野岸，凿井割邻泉。","蟾黾游丝困，凫鹥乱苇眠。","考槃吾有志，敢吝买山钱。"]},{"t":"经废寺","f":"五言律诗","c":["宝殿莽萧萧，残僧宿敝寮。","壁馀昏后画，树绝挂时瓢。","碑毁龟趺损，梁荒鼠族骄。","听经知识少，驯虎度危桥。"]},{"t":"送王献子还袁州","f":"五言律诗","c":["相逢当夏首，相别忽秋残。","逆旅淹留久，空囊去住难。","芦飞鸿外白，枫落马头丹。","已乏绨袍赠，霜风今又寒。"]},{"t":"寄题邓国弼贮青亭","f":"五言律诗","c":["烟霞处处深，紫翠满遥岑。","夜静松分籁，天凉竹送阴。","野麇随独往，山鸟荅閒吟。","古木苍苍色，居人指邓林。"]},{"t":"题余伯明龙沙遗谶","f":"五言律诗","c":["相逢证九还，一窍指玄关。","道契鸿濛外，神游鹤驭间。","丹砂延绿发，白日驻红颜。","试问龙沙回，予名列几班。"]},{"t":"涪州张节妇","f":"五言律诗","c":["涪水澄如练，还同节妇心。","柏舟吟自苦，湘竹泪何深。","矢志终箕帚，留颜见稿砧。","贞魂应不朽，褒宠有纶音。"]},{"t":"方山严孝子","f":"五言律诗","c":["苦节甘辞禄，幽栖濑水边。","为忧亲白发，非薄宦青毡。","名列高贤传，山留处士阡。","遗孤垂老日，犹废蓼莪篇。"]},{"t":"芊江雪夜留别社中诸子","f":"五言律诗","c":["岁晏强为客，时危怯离家。","孤身冲雨雪，双泪别烟霞。","前路天难尽，故山云易遮。","半生于役苦，赢得鬓将华。"]},{"t":"不寐","f":"五言律诗","c":["展转怀乡国，愁心夜更繁。","猿声烟外峡，渔火水边村。","屡醒无完梦，频啼有乱痕。","廿年婴世网，销尽几多魂。"]},{"t":"嵢峡道中即事","f":"五言律诗","c":["腊尽天犹暖，林深翠未凋。","石多盘谷口，路半出山腰。","云色愁当岫，滩声怒过桥。","邮亭看尚远，落日见归樵。"]},{"t":"闺情","f":"五言律诗","c":["泪尽闺中烛，肠回锦上文。","蛾眉羞写月，鸾鬓罢梳云。","枕怯罗衾冷，香孤绮阁薰。","空床本无寐，况复夜蛩闻。"]},{"t":"度分水关","f":"五言律诗","c":["鸟道盘云际，停车怨陇头。","封疆分异域，关路割双流。","地尽辞闽峤，山穷见楚州。","多情故乡水，呜咽为含愁。"]},{"t":"吴江哭顾道行先生","f":"五言律诗","c":["图报惭无地，哭声空震天。","恩私诸子外，知遇十年前。","残箧玄经秘，仪床绛帐悬。","旧题诗满壁，一读一潸然。"]},{"t":"送邬子远还京口时邬有丧子之戚","f":"五言律诗","c":["相逢俱失意，相送柰愁何。","老去雄心减，春来归梦多。","旧山怀北固，新泪滴西河。","世路已如此，空为劳者歌。"]},{"t":"望月有怀和陆纂父","f":"五言律诗","c":["一别经圆缺，三秋望转明。","蛾眉今夕影，鸾镜旧时情。","貌逐清辉减，愁随素魄生。","关山千里隔，何处照盈盈。"]},{"t":"送蔡千户袭职还吴兴","f":"五言律诗","c":["龙韬堪报主，燕颔定封侯。","挂印还乡里，挥鞭出御楼。","归途寻越绝，行橐佩吴钩。","戎马东南急，凭君借箸筹。"]},{"t":"都门逢湛如和尚","f":"五言律诗","c":["金陵留偈别，燕市忽相逢。","不托侯门钵，閒闻禁苑钟。","经文翻北藏，禅理悟南宗。","行脚他乡久，空房偃旧松。"]},{"t":"访杨山甫","f":"五言律诗","c":["相过即留连，因君卜筑偏。","香销炉有烬，茶熟灶生烟。","采得芸驱蠹，栽将柳借蝉。","门前时载酒，来叩子云玄。"]},{"t":"同陆纂父暮酌程康伯花下得枝字","f":"五言律诗","c":["幽斋当薄暮，移酌傍花枝。","选树莺窥酒，穿林蝶罥丝。","月低流影缓，风细度香迟。","不惮频来此，交欢无几时。"]},{"t":"同陆纂父山人杨山甫保御集程康伯典客衙斋看芍药","f":"五言律诗","c":["异种分仙禁，娇姿冠众芳。","当阶翻绛艳，傍砌发浓香。","郑国佳人赠，吴宫西子妆。","画栏春色好，不用说维扬。"]},{"t":"曾人倩雨中过酌","f":"五言律诗","c":["故人休沐暇，穷巷过吟鞭。","散帙钩帘坐，寻诗解带眠。","马蹄淹暮雨，莺语乱春烟。","自与垆头熟，不愁无酒钱。"]},{"t":"周叔宗郁孟野俞羡长李长白黎慎甫雨集分得微霁","f":"五言律诗","c":["如丝看乍歇，庭际尚萧森。","已觉收残霭，翻疑结薄阴。","晚山消夕晕，好鸟间新音。","徙倚花林暮，斜阳生远岑。"]},{"t":"题曹能始计部潞河公署园亭","f":"五言律诗","c":["司农开别墅，一径满烟霞。","与鹤同临水，随蜂共放衙。","榆飘沿径荚，榴发傍墙花。","自足园池乐，无烦到习家。"]},{"t":"送金季黄山人游五岳","f":"五言律诗","c":["年来婚嫁毕，五岳寄閒心。","胜地随缘住，名山到处寻。","孤筇青嶂老，双屐白云深。","去矣辞尘网，高踪比向禽。"]},{"t":"潞河别曹能始 其一","f":"五言律诗","c":["悲歌燕市筑，归兴潞河船。","作客有何意，还山仍种田。","穷猿投散木，饥鹘倦遥天。","以我空囊故，怜君损俸钱。"]},{"t":"潞河别曹能始 其二","f":"五言律诗","c":["流落谁如我，艰危况别君。","渡淮三伏雨，瞻阙万重云。","杀气旌旗满，哀声鼓角闻。","临岐双涕泪，不独为离群。"]},{"t":"潞河别曹能始 其三","f":"五言律诗","c":["昔年同献赋，此日尚沉沦。","我有恓皇泪，君怜弃置身。","黄尘归路客，白发倚门亲。","不尽消魂意，哀歌难重陈。"]},{"t":"潞河别曹能始 其四","f":"五言律诗","c":["久已歌黄鸟，还劳赋白驹。","心雄犹短剑，目断更长途。","去住总归客，行藏空腐儒。","故园关百虑，何敢畏驰驱。"]},{"t":"潞河驿别周叔宗","f":"五言律诗","c":["经时俱作客，此地且盘桓。","去路黄尘满，征衣白日寒。","吴歌聊自和，燕月暂同看。","因悔长安陌，蹉跎未尽欢。"]},{"t":"出都门留别茅平仲周思敬朱汝脩吴孝甫张孺宗赵凡夫钟山甫韩兆之吴载伯阮步文张曰肩诸君","f":"五言律诗","c":["违时空献策，落魄出燕南。","恋阙情无极，离人思不堪。","绿杨莺睍睆，青草马骖驔。","总是飘蓬客，何时又盍簪。"]},{"t":"济上","f":"五言律诗","c":["归兴已如此，归帆尚济州。","沙汀芦受月，江岸蓼迎秋。","不尽闽天远，无情汶水流。","敢辞留滞苦，其奈倚门忧。"]},{"t":"太白酒楼","f":"五言律诗","c":["太白久不返，酒楼犹未倾。","当年聊一醉，千载仰高名。","隔岸围山色，凭栏到水声。","风流无贺监，过客若为情。"]},{"t":"王粹夫客淮上先归相寻不值诗以怀之","f":"五言律诗","c":["我来淮水上，君已解归舟。","逆旅无长策，天涯总薄游。","早辞征路苦，先见故园秋。","漂母祠前过，因之双泪流。"]},{"t":"夜宿焦山赠道林上人","f":"五言律诗","c":["鹫岭傍龙宫，慈帆但信风。","悬灯孤嶂里，洗衲乱流中。","山静云归锡，湖平月印空。","道林名不沗，禅理似支公。"]},{"t":"晚过惠山","f":"五言律诗","c":["舍筏寻兰若，斜阳古殿开。","竹烟深似雨，松瀑响如雷。","水逐钟声去，云从塔影来。","清泉随意取，装得满船回。"]},{"t":"王百谷招集南有堂","f":"五言律诗","c":["故人三载别，此日一尊同。","庵度旃檀雨，池凉蘋蓼风。","暮蝉归树急，残暑入林穷。","座客多湖海，乡心因暂空。"]},{"t":"题姚叔乂玄散斋","f":"五言律诗","c":["幽斋栖委巷，萧散寄高吟。","笔底青山债，尊前白发心。","俗缘閒渐减，玄理老弥深。","三径蓬蒿满，唯容二仲寻。"]},{"t":"同沈稚咸过寒山寺访旭公","f":"五言律诗","c":["曲岸暂维舟，精庐访比邱。","钟声闻半夜，杯影见中流。","榻倚干花晚，房开万竹秋。","相看成一笑，疑是虎溪游。"]},{"t":"赠刘会卿保御","f":"五言律诗","c":["但得筋骸健，何妨鬓发苍。","诗成开白社，书就秘青囊。","世事閒能遣，机心老易忘。","时时留客醉，丝竹满高堂。"]},{"t":"赠沈公绳","f":"五言律诗","c":["久已称三绝，真如顾虎头。","杜门閒自得，于世澹无求。","丘壑胸中相，潇湘笔底秋。","沈郎腰细尽，盘礴未能休。"]},{"t":"哭盐官斯学上人","f":"五言律诗","c":["微尘元世界，师已厌微尘。","满月初圆果，浮云易了身。","昙花天外散，金骨塔中新。","不作无生想，闻之应损神。"]},{"t":"常山道中","f":"五言律诗","c":["来时逢朔雪，归路又秋风。","客计惭羸马，乡心逐去鸿。","喜看闽地近，渐见越山穷。","想到家林日，篱花开几丛。"]},{"t":"经旧游怀康元龙","f":"五言律诗","c":["西陵分别后，踪迹各飘零。","又见枫林赤，依然酒幔青。","关河仍旧路，风雪忆邮亭。","独坐孤灯下，疏砧未可听。"]},{"t":"鹅湖晚行","f":"五言律诗","c":["一径入莓苔，前峰夕照催。","饥乌绕树去，乳犊出林来。","山色自然秀，野花无意开。","村村足幽趣，差得少迟回。"]},{"t":"车盘驿","f":"五言律诗","c":["征途秋草遍，客子倦知还。","岁晚缲车急，年荒水碓閒。","峰峦青络绎，溪涧绿回环。","落日苍茫外，何山是故山。"]},{"t":"归次建溪闻郑君大讣诗以哭之 其一","f":"五言律诗","c":["忽尔传君死，犹疑讣未真。","哀来魂欲断，痛定泪沾巾。","泉路何其近，皇天太不仁。","高阳脩旧社，应少白头人。"]},{"t":"归次建溪闻郑君大讣诗以哭之 其二","f":"楚辞体","c":["送我荷亭上，相看惜解携。","生离犹唧唧，死别重凄凄。","世不容豪侠，天疑爱滑稽。","魂兮招不返，歌罢数行啼。"]},{"t":"归次建溪闻郑君大讣诗以哭之 其三","f":"五言律诗","c":["正拟还家日，对君怀抱开。","如何千万语，总作一声哀。","泪不到泉壤，书难通夜台。","或君灵爽在，知我已归来。"]},{"t":"归次建溪闻郑君大讣诗以哭之 其四","f":"五言律诗","c":["交游君最长，矍铄有谁群。","对酒杯邀月，看山屐蹑云。","贫犹开白社，老不厌红裙。","何意经年别，归来便哭君。"]},{"t":"秋日载酒同陈汝翔黄伯宠惟起惟扬二弟访王玉生郊居","f":"五言律诗","c":["绿酒因君载，青山与客同。","画成真道子，隐去即庞公。","丘壑村村合，桑林巷巷通。","坐来香不断，窗外木犀风。"]},{"t":"冬夜袁无竞过酌","f":"五言律诗","c":["钟声排小阁，灯影坠孤尊。","竹净云阴薄，花疏霜气繁。","卑喧虽近市，幽僻亦深村。","坐久儿童睡，山风自掩门。"]},{"t":"陪屠田叔使君游仁王寺同康元龙袁无竞兴公弟分得回字","f":"五言律诗","c":["钟磬近香台，鸣驺半路回。","庄严菩萨界，善信宰官来。","合掌缘同结，攒眉禁暂开。","山僧能爱客，莲漏不频催。"]},{"t":"送黄若木还莆","f":"五言律诗","c":["执手向城隅，送君归鲤湖。","风涛危渡峡，雨雪倦登途。","遣日携书卷，消寒问酒垆。","不须嗟伏枥，千里待名驹。"]},{"t":"高贤祠成荅屠使君 其一","f":"五言律诗","c":["庙貌壮千秋，英灵托一丘。","藻蘋无俗客，香火总名流。","白骨化已久，清魂吟未休。","预知百岁后，同得此中游。"]},{"t":"高贤祠成荅屠使君 其二","f":"五言律诗","c":["八代斯文振，全闽雅道尊。","精灵同不灭，显晦未须论。","权自操吾党，名非藉子孙。","泱泱东海上，真可霸中原。"]},{"t":"高贤祠成荅屠使君 其三","f":"五言律诗","c":["新祠劳仰止，神理定非遥。","五世应难斩，千秋永不祧。","像从诗外想，魂向赋中招。","后死吾徒在，遗风未寂寥。"]},{"t":"高贤祠成荅屠使君 其四","f":"五言律诗","c":["俎豆隆殊典，山林更有光。","诗真传在世，没果祭于乡。","身后荣如此，生前困不妨。","当年冠盖者，谁敢望宫墙。"]},{"t":"渊溪十里桥与屠田叔泣别","f":"五言律诗","c":["从来轩冕泪，不滴芰荷衣。","独有今朝别，使君先泪挥。","地偏愁会隔，天阔恐书稀。","望望车尘远，人人哽咽归。"]},{"t":"惟秦冬夜偶至拥炉对酌率尔成咏","f":"五言律诗","c":["音从空谷听，兴似剡溪乘。","榾柮残炉火，松膋半壁灯。","俗情谈后减，诗草别来增。","浊酒堪消夜，浑忘朔气凝。"]},{"t":"有感 其一","f":"五言律诗","c":["传闻关白死，海气绝氛腥。","间谍防真伪，悲欢杂涕零。","王春回雨露，天怒息雷霆。","时事难高枕，端居莫谓宁。"]},{"t":"有感 其二","f":"五言律诗","c":["馁虎横行甚，村氓骨半枯。","猛应凭伥鬼，威或假妖狐。","白昼常当道，清时敢负嵎。","官兵虚搏击，鸡犬反惊呼。"]},{"t":"有感 其三","f":"五言律诗","c":["久雨防时歉，囊空米价腾。","子钱残岁急，官赋隔年徵。","薄劣明时弃，疏慵末俗憎。","处篱同斥鴳，未敢望鹍鹏。"]},{"t":"赠本净上人","f":"五言律诗","c":["信心归净土，行脚到闽天。","度众时开讲，降魔夜不眠。","闻钟能悟性，补衲恐妨禅。","何日参猊座，焚香听白莲。"]},{"t":"题林明府先辈挽诗卷后","f":"五言律诗","c":["乡录留名姓，遗图见影神。","鸣琴瀔水曲，归榇赣江滨。","哭墓门生老，传家嗣子贫。","卷中哀挽客，存者更何人。"]},{"t":"慰陈平夫","f":"五言律诗","c":["怜君多难日，知己亦销魂。","已叹如悬磬，何堪复鼓盆。","旧情思挽鹿，新恨听啼猿。","为问牛衣上，添将泪几痕。"]},{"t":"与黄道晦夜坐话旧","f":"五言律诗","c":["零落田园后，还嗟世事更。","眼昏妨夜读，身老废春耕。","稻麦亏丰岁，齑盐淡此生。","相看灯影里，无限旧时情。"]},{"t":"岁暮戏题诗稿后","f":"五言律诗","c":["本以牢骚著，多因幽愤成。","雌黄招众口，青紫误今生。","落落无穷意，遥遥不朽名。","万言难卒岁，掩卷独伤情。"]},{"t":"水明楼赠陈仕卿","f":"五言律诗","c":["日日来相访，爱君幽意长。","画题随客命，诗债逼人偿。","听雨坐蕉径，放云开竹房。","入林无小阮，终少七贤狂。"]},{"t":"赋得系臂纱送陆姬","f":"五言律诗","c":["红汗沾犹湿，缠绵玉钏知。","暗香生皓腕，微晕隐丰肌。","疑作同心结，看如续命丝。","守宫今褪尽，情重枕郎时。"]},{"t":"题普通寺","f":"五言律诗","c":["山城已在山，寺更翠微间。","磴路危因石，杉松密护关。","莺声无意巧，云影自然閒。","徐步经行久，桐花满地斑。"]},{"t":"赠黄思衡广文","f":"五言律诗","c":["意气贫难减，文章老更工。","身閒贪佛日，官冷称儒风。","夫子推杨震，经生重马融。","剑锋销未尽，耿耿尚如虹。"]},{"t":"怀惟秦客粤","f":"五言律诗","c":["计程当入粤，踪迹竟何如。","马度栟榈密，莺啼簟竹疏。","定回天外梦，谁寄岭南书。","寂寂蛮村路，知应念索居。"]},{"t":"吴城览古","f":"七言律诗","c":["白云犹绕旧王居，独对西风恨有馀。","百战山河归草莽，千年陵寝总丘墟。","月明茂苑游麋鹿，花暗荒城吊阖庐。","况是异乡多病客，岂堪唫眺暂踌躇。"]},{"t":"古意","f":"七言律诗","c":["一天秋色露华清，独倚妆台别恨生。","锦字缄愁过蓟水，寒衣将泪到辽城。","梦回万里金微路，肠断三更玉篴声。","起视明河人不见，朔云边月总关情。"]},{"t":"塞下曲","f":"七言律诗","c":["沙碛风高敌骑侵，将军新战贺兰阴。","塞霜晓角降王泪，汉月秋笳壮士心。","刀上洗瘢青血冷，营前望气白光沉。","旄头未落边烽急，肠断空闺戍妇砧。"]},{"t":"送人入蜀","f":"七言律诗","c":["忽闻天末雁声悲，况是尊前送客时。","白发尚怀江海梦，青山空负薜萝期。","马经剑阁晴虹断，帆过巴川夜月迟。","夔府城头应吊古，寒云漠漠草离离。"]},{"t":"西湖泛舟","f":"七言律诗","c":["夕阳箫鼓起中流，十里芙蓉两岸秋。","荇带乱萦青雀舫，菱歌低度白鸥洲。","吴山积翠斜侵郭，越女凝妆尽倚楼。","三竺钟声听渐远，半江微月送归舟。"]},{"t":"饮王氏南园","f":"七言律诗","c":["南园精舍远尘嚣，晏坐松阴暑气消。","鹫岭云光连古堞，马江帆影逐归潮。","乍闻金铎当空断，遥见珠幡隔寺飘。","日晚寒鸦栖欲尽，海风吹月上山椒。"]},{"t":"青楼曲","f":"七言律诗","c":["美人家住五陵东，沟水门前曲曲通。","帘影半邀金市月，箫声閒度玉楼风。","旧翻小扇桃花碧，新制单衫杏子红。","十二栏干千树柳，不知何处系青骢。"]},{"t":"送游方僧","f":"七言律诗","c":["春风初动雪初晴，锡杖今朝出化城。","万里云天孤鹤影，满林烟树乱莺声。","禅心客路随流水，古院荒山闭月明。","自是空门无定迹，河桥此别漫关情。"]},{"t":"秋夜送客","f":"七言律诗","c":["秋至关河木叶乾，送君西去路漫漫。","潮喧古渡猿啼隐，露下空江雁影寒。","数点渔灯归浦远，一声僧磬出林残。","片帆渺渺知何处，后夜相思独倚栏。"]},{"t":"金山寺别恩上人","f":"七言律诗","c":["忽闻钟韵出林微，话别空门思欲飞。","日暮西风吹客棹，夜深凉月梦僧衣。","芜城岁晚芦花尽，瓜步秋高木叶稀。","从此分携各南北，更于何处问禅机。"]},{"t":"炀帝行宫 其一","f":"七言律诗","c":["满目繁华一夕空，至今行客说离宫。","垂杨旧见朱旗绕，芳草曾经翠辇通。","商女歌残花落后，妖姬魂散月明中。","可怜淮水龙舟戏，听得江南曲未终。"]},{"t":"炀帝行宫 其二","f":"七言律诗","c":["废殿荒凉噪暮鸦，广陵潮满夕阳斜。","一从凤辇归黄土，无复龙舟驻翠华。","春尽冷烟生蔓草，夜深明月照璚花。","当时复道今何处，半属芜城百姓家。"]},{"t":"雪中登富春山","f":"七言律诗","c":["群山万壑白嶙峋，雪里移舟问富春。","诸将汉家依日月，故人天上动星辰。","千年宿草埋钟鼎，七里寒烟护钓纶。","最羡羊裘堪傲世，青袍愁染洛阳尘。"]},{"t":"姑苏怀古","f":"七言律诗","c":["秋风吹送木兰桡，无那愁心逐暮潮。","响屧廊中歌舞散，姑苏台上鹿麋骄。","东吴霸气今俱尽，西子香魂不可招。","半夜乌啼钟欲动，无情明月照枫桥。"]},{"t":"兰陵道中寄同社","f":"七言律诗","c":["木落孤城岁易阑，征途何日到长安。","匣中宝剑霜花冷，客里金尊竹叶残。","两浙名山方驻马，七闽诸子正登坛。","忽闻白苧歌声起，欲倩西风寄泽兰。"]},{"t":"经黄河寄怀陈平夫","f":"七言律诗","c":["隔岸惊闻伐木歌，橹声摇月下黄河。","六溪昼静枯桐冷，三径春深芳草多。","满路繁霜凋客鬓，半江寒雨梦渔蓑。","思君不奈风尘远，夜夜愁心逐逝波。"]},{"t":"易水道中答谢在杭","f":"七言律诗","c":["翩翩击筑共游燕，慷慨行歌易水边。","九曲河流看似带，三春杨柳折为鞭。","诗成马上无须草，酒买垆头不论钱。","此去长安应咫尺，与君同赋帝京篇。"]},{"t":"清明日饮陈子卿燕南客舍","f":"七言律诗","c":["燕市逢君倒接䍦，几回相乐又相悲。","天涯踪迹同萍梗，客路年华寄柳枝。","南国词坛高赤帜，西山爽气落瑶卮。","若非暂过梨花院，辜负春光总不知。"]},{"t":"下第呈孙子乐省元","f":"七言律诗","c":["黑貂裘敝出长安，客路春光半已残。","燕市柳从归处折，故园花在梦中看。","处囊壮士犹潜颖，落魄王孙未筑坛。","飘泊风尘还自笑，十年依旧一儒冠。"]},{"t":"平望舟中同在杭晚眺","f":"七言律诗","c":["片帆湖上正黄昏，万顷湖光浪不翻。","别后久无千里雁，月中同听一声猿。","半汀菱叶争迎棹，满目芦花不见村。","无数渔歌云外起，天涯孤客易销魂。"]},{"t":"王百谷半偈庵赠顺公","f":"七言律诗","c":["彼岸由来不易登，仲宣楼上遇名僧。","演成西竺三车法，传得南宗几佛灯。","纪腊每栽香国树，题诗常买剡溪藤。","漫言自昔耽禅说，身舍空门愧未能。"]},{"t":"娄江哭王太常敬美先生","f":"七言律诗","c":["箕尾骑来历几秋，招魂恸哭过西州。","云飞澹圃愁无色，水到娄江咽不流。","宝剑此时悬季子，明珠何地报隋侯。","丘山零落空华屋，徒抱人琴痛未休。"]},{"t":"哭王太常墓","f":"七言律诗","c":["一夜文星落太空，中原惊叹失人龙。","五湖方遂鸿冥志，千载真成马鬣封。","门下几人歌薤露，墓前今日挂芙蓉。","招魂宋玉吞声哭，欲叩天阍第九重。"]},{"t":"陈价夫归自崖州谈粤中山水因怀旧游","f":"七言律诗","c":["珠崖弹铗动经年，醉抱黎姬酒肆眠。","笑语尚存湖海气，衣裳犹带岛夷烟。","波罗老去甘如蜜，蒌叶开时小似钱。","十载游踪俱是梦，不堪重听旧山川。"]},{"t":"送刘司理考绩之京","f":"七言律诗","c":["北望京华去路赊，法星长照使君槎。","一官佐郡来分竹，三载王程正及瓜。","匹马夜嘶燕市月，新莺春啭上林花。","天朝正待平反疏，父老前途不用遮。"]},{"t":"赠蔡景明参知","f":"七言律诗","c":["托迹江湖二十霜，名山游遍不赍粮。","斗间能辨龙文气，粉署曾含鸡舌香。","夜月久虚玄草宅，客星还照紫薇郎。","山川信美皆吾土，何用登楼忆故乡。"]},{"t":"过邵梦弼广文山居","f":"七言律诗","c":["家傍城南薛老峰，衡茅长闭白云踪。","读书早已过袁豹，作赋元堪比士龙。","座上一盘餐苜蓿，匣中三尺挂芙蓉。","山间忽听苏门啸，知隔烟萝第几重。"]},{"t":"送赵仁甫司理左迁之京","f":"七言律诗","c":["十载功名叹积薪，风波万里一孤臣。","江潭此日歌渔父，宣室何年问鬼神。","自是蛾眉终见妒，岂知龙性故难驯。","迩来词客方多难，莫向长安逐酒人。"]},{"t":"哭邵梦弼广文 其一","f":"七言律诗","c":["云黯乌山旧草亭，抚床恸哭泪交零。","百年天地收灵气，半夜词坛陨将星。","挂壁哀弦今已断，隔邻长笛不堪听。","茂陵死后多遗稿，剩有残编著汗青。"]},{"t":"哭邵梦弼广文 其二","f":"七言律诗","c":["赋就招魂竟莫还，天阍虎豹正当关。","更无白日能回照，岂有金丹可驻颜。","死后脩文居地下，生前遗墨在人间。","青门皓首幽栖处，桂树萧条不忍攀。"]},{"t":"中秋饮西湖澄澜阁观妓","f":"七言律诗","c":["八月秋风冷芰荷，西山爽气晚来多。","千重树色浓于染，十里湖光澹似罗。","白社共酣桑落酒，红裙齐唱竹枝歌。","今宵若得君平卜，知泛星槎入绛河。"]},{"t":"挽吴门沈汝明处士","f":"七言律诗","c":["萧萧白发老山林，处士星文一夜沉。","邻舍几能悲短笛，中原谁不叹亡琴。","空林猿鹤春无主，满地松楸日易阴。","墓与要离孤冢近，梁鸿高节尚堪寻。"]},{"t":"齐将军席上闻歌","f":"七言律诗","c":["七载韶华叹逝波，天涯尊酒喜重过。","春风海上销兵气，夜月军中奏雅歌。","仙子吹笙年正少，将军入幕客偏多。","灞亭醉尉应相避，敢问今宵漏若何。"]},{"t":"送熊益中孝廉归丰城","f":"七言律诗","c":["征亭尊酒暂踌躇，一曲阳关恨有馀。","月里龙精归剑浦，云边马首出匡庐。","故园春尽莺声老，驿路天长雁影疏。","明到长安同献赋，知君才藻逼相如。"]},{"t":"赠黄瞻山先生","f":"七言律诗","c":["年少声华动五侯，老来长啸卧沧洲。","门无车辙堪罗雀，家有图书可汗牛。","流水一村韦曲社，桃花三月武陵舟。","知君猿鹤盟犹在，好看青山到白头。"]},{"t":"赠歌者","f":"七言律诗","c":["莺喉宛转舞蹁跹，唱彻凉州第一篇。","缑岭羽衣王子晋，汉宫丽质李延年。","袖当卧处还堪剪，锦掷筵间不用缠。","三过雍门称绝技，可能歌劝上留田。"]},{"t":"沙口夜泊答宗思兼见示","f":"七言律诗","c":["薄暮停桡水一湾，沽来村酒破愁颜。","戍楼残角吹霜落，别浦渔舟刺月还。","几点昏鸦归木杪，数家寒火出林间。","漫言潘岳犹年少，憔悴西风鬓易斑。"]},{"t":"重阳前一日寓宝严寺","f":"七言律诗","c":["为怜秋色满禅房，回首家山几断肠。","季子黑裘淹岁月，潘郎青鬓怯风霜。","天涯佳节愁中过，上界钟声梦里长。","飘泊异乡知己少，明朝谁泛菊花觞。"]},{"t":"江郡侯招饮西湖同曾人倩谢在杭分得游字","f":"七言律诗","c":["乞假邀驩露冕游，暂从湖上驻鸣驺。","千层粉堞连云起，一带沧波绕寺流。","大梦山前春意动，澄澜阁上雨声收。","江淹彩笔雄今古，敢对青尊共唱酬。"]},{"t":"送黄居约司理英州","f":"七言律诗","c":["少年新佩吕虔刀，拥传东行意气豪。","公署遥开泷水阔，法星还傍斗垣高。","曲江柳色迎征幰，庾岭梅花照锦袍。","同听鹿鸣君已贵，可无书札慰蓬蒿。"]},{"t":"己丑除夕迎春同陈振狂过钟山寺访曾人倩适瀚上人至同得僧字","f":"七言律诗","c":["岭南才子气凭陵，剡水孤舟兴可乘。","青树又添阶下腊，缁衣同对佛前灯。","漫誇市上春如锦，且醉尊中酒似渑。","总是空门无去住，好将真偈问名僧。"]},{"t":"庚寅元日曾人倩过访同谢在杭分韵","f":"七言律诗","c":["故人骑马到岩阿，同泛椒花醉薜萝。","别后青云俱未达，镜中华发近如何。","鸥盟隐去还堪结，马齿年来觉渐多。","新柳河桥初绽绿，明朝且莫赋骊歌。"]},{"t":"钟山寺送曾人倩归岭南","f":"七言律诗","c":["曾向东阿酒肆逢，重来相见未从容。","帆飞炎海三秋月，门掩青山半夜钟。","客路迎人惟柳色，贫交赠别只芙蓉。","遥知他日相思处，梦在罗浮四百峰。"]},{"t":"送江太守兵备三吴","f":"七言律诗","c":["登车揽辔正秋分，卧辙无能借寇君。","郭外一钱遮五马，匣中双剑静三军。","霜台俯瞰娄江水，行部遥飞震泽云。","自愧浅才甘寂莫，谁因羽猎荐雄文。"]},{"t":"送谢伯元之金陵","f":"七言律诗","c":["长江渺渺片帆开，一曲离歌落照催。","挟妓每过桃叶渡，寻僧重上雨花台。","芙蓉古岸犹堪采，禾黍遗宫尽可哀。","不必登高频吊古，六朝王气已成灰。"]},{"t":"温永叔郡丞以诗见赠赋答","f":"七言律诗","c":["南国风流温太真，翩翩才藻更谁伦。","几年作吏犹分竹，何处逢人叹积薪。","郡剧不妨三日醒，甑空宁厌一官贫。","使君赋有凌云气，白练亲题寄隐沦。"]},{"t":"闻警 其一","f":"七言律诗","c":["西贼寒盟秋犯边，黄尘漠漠暗高天。","一从互市通穷塞，廿载偷安罢控弦。","绝域羽书飞幕府，连营烽火照甘泉。","诸公早建安危策，四海苍生正倒悬。"]},{"t":"闻警 其二","f":"七言律诗","c":["和议当年计已疏，空将岁币致穹庐。","总缘中夏无防禦，遂使穷边得捣虚。","帷幄运筹贤相国，边陲经略老尚书。","吾皇威福齐天地，杕杜歌成乐有馀。"]},{"t":"闻警 其三","f":"七言律诗","c":["传闻边郡苦天骄，三辅人心忽动摇。","宁夏守臣纷告急，太平天子始临朝。","中原几处忧骑虎，北塞何人得射雕。","坐看边庭空漠北，汉家新拜霍嫖姚。"]},{"t":"闻警 其四","f":"七言律诗","c":["关山边骑响萧萧，司马观兵日度辽。","天上黑光久摩荡，宫中黄屋太焚烧。","空挥涕泪忧时变，难效涓埃答圣朝。","安得善言同宋璟，冥冥氛祲一时销。"]},{"t":"经涌泉废寺","f":"七言律诗","c":["约客扶筇到上方，白云空绕旧僧房。","经台岁久萝阴合，香积春深草色荒。","遗址尚传唐甲子，残碑犹志宋文章。","可怜几度沧桑变，惟有猿声啸夕阳。"]},{"t":"过大笠僧太虚故居","f":"七言律诗","c":["重携竹杖访禅栖，钟磬无声鸟乱啼。","只履乍逢归竺国，众香今已指曹溪。","幻身自昔终于灭，住世虚传得大齐。","却笑俗情空雨泪，悟来应识世人迷。"]},{"t":"赠赵茹霞羽士","f":"七言律诗","c":["海国真人茹碧霞，廿年云水寄生涯。","读残紫府三千箓，看尽玄都十万花。","天外瑶笙招白鹤，洞中霞佩隐青蛇。","知君名姓归仙籍，为乞星坛伏火砂。"]},{"t":"吸江亭送林隐之山人还永嘉","f":"七言律诗","c":["萧萧匹马万重山，遥指家林雁宕间。","竹叶难留孤客醉，桃花如笑故人颜。","不将旅食弹长铗，已动归心忆小蛮。","歌罢骊驹声渐远，吸江亭外即阳关。"]},{"t":"客中忆惟起惟扬弟","f":"七言律诗","c":["谁怜岁晚滞征途，无那离心满五湖。","花外烟霞双屐冷，竹中风雨一灯孤。","断猿叫月朝归峡，孤雁啼霜夜入芦。","忆汝松窗读周易，莫教三径易荒芜。"]},{"t":"再至京师","f":"七言律诗","c":["遥控秦关百二重，九天宫阙绚芙蓉。","醉中但击荆轲筑，梦里惊闻汉阙钟。","才子新词皆吐凤，美人高髻尽盘龙。","玉河杨柳丝丝绿，染得青袍色尚浓。"]},{"t":"中秋集周光禄花亭观妓","f":"七言律诗","c":["何来珠履满华堂，弦索声中漏未央。","狂客风流歌白帻，妖姬云集斗红妆。","月明尽撤千枝烛，花郁争分百和香。","莫谓醇醪容易醉，主人年少是周郎。"]},{"t":"送苍峡王巡检罢官归乡","f":"七言律诗","c":["越王台上送将归，远树空林带夕晖。","苍峡断猿双泪下，碧天寒雁一行飞。","秪愁白发流年暮，不问青山旧业微。","此别悠悠难再遇，思君惟有一沾衣。"]},{"t":"寄吴叔嘉","f":"七言律诗","c":["当年岁晚过江都，闻说相如渴未苏。","作客生涯云共薄，怀人愁绪月同孤。","秋风茂苑閒清昼，春雨荒城长绿芜。","遥想登楼定怀土，梦魂夜夜到勾吴。"]},{"t":"送刘宋卿还家兼讯顾长卿世卿","f":"七言律诗","c":["平芜漠漠白云閒，忍向尊前送客还。","赋别此时过候馆，怀人今夜闭空山。","一年春色啼莺里，千里归心去马间。","为问姑苏台上客，几人飞梦到闽关。"]},{"t":"送陈仲徽之齐省兄 其一","f":"七言律诗","c":["都亭对酒起愁声，芳草萋萋感别情。","一片飞帆扬子渡，五更归梦越王城。","客途社早初逢燕，官舍春深好听莺。","念我征鞍方暂息，不堪江上送君行。"]},{"t":"送陈仲徽之齐省兄 其二","f":"七言律诗","c":["堤畔流莺不可闻，此行应念鹡鸰群。","孤舟夜渡秦淮月，匹马朝冲泰岱云。","故国烟花随梦断，天涯春色隔江分。","欲知别后相思意，惟有登楼对夕曛。"]},{"t":"寄陈子卿","f":"七言律诗","c":["萋萋芳草满汀洲，为念王孙独倚楼。","易水悲风孤客泪，潞河寒雨一归舟。","征途入夜劳乡梦，野店逢春忆旧游。","献赋不须嗟未达，于今世路总悠悠。"]},{"t":"孙子长居湖上别业却寄","f":"七言律诗","c":["西湖水色碧连天，湖上幽栖地自偏。","远寺钟声明月夜，隔林樵唱夕阳边。","行当花径常逢鹿，坐向柽阴独听蝉。","闻说荒郊少人迹，与谁同泛钓鱼船。"]},{"t":"送玉生诸子游方广岩","f":"七言律诗","c":["一叶兰舟问翠微，满汀杨柳正依依。","谷当绝壁僧行惯，寺隐深溪客到稀。","半亩暮云禅榻冷，几番春雨水帘飞。","花源自是堪逃世，莫学渔郎去便归。"]},{"t":"送田将军武荐上司马 其一","f":"七言律诗","c":["侯门才子似君稀，鹊印貂裘赴帝畿。","济北烟花迎去马，潞河风柳绾征衣。","津亭春暖千莺啭，上苑秋高一鹗飞。","圣主临轩应召对，安边何策献彤帏。"]},{"t":"送田将军武荐上司马 其二","f":"七言律诗","c":["关城三月尚微寒，一曲离歌送所驩。","客舍花飞春漠漠，长安天远路漫漫。","舟移楚水晴烟断，马过燕山夕照残。","独爱终军最年少，请缨还拟繫楼兰。"]},{"t":"游宗谦山人见过","f":"七言律诗","c":["春残花落雨濛濛，十载襟期此日同。","一榻独悬青嶂里，数杯长醉白云中。","已闻啸似苏门远，还羡谈如稷下雄。","明发河桥应折柳，白头为客任西东。"]},{"t":"清明日感怀","f":"七言律诗","c":["此心如梦复如痴，荏苒春光欲暮时。","啼比杜鹃先有血，愁同杨柳更多丝。","林花开遍谁为主，社燕重来亦似悲。","寒食已过非禁火，闭门犹自绝晨炊。"]},{"t":"送妓入道 其一","f":"七言律诗","c":["厌居绮陌慕丹丘，断却尘缘学道流。","夜静有神游紫府，月明无梦到青楼。","六时古洞春风满，十二巫山暮雨休。","一曲云璈声缥缈，依稀犹带小凉州。"]},{"t":"送妓入道 其二","f":"七言律诗","c":["愁把芳年老狭邪，欲寻铅汞洗铅华。","西园公子求遗佩，南岳夫人赠紫霞。","翠袖正宜过碧海，朱颜偏可饵丹砂。","玉声已奏仙家乐，不向江心抱琵琶。"]},{"t":"题郭士龙隐居","f":"七言律诗","c":["壶公山色白云齐，一室萧然隐者栖。","短屐每寻芳草路，轻舟时泛木兰溪。","春深绿酒闻莺语，昼静玄经落燕泥。","欲觅武陵何处所，桃花干树使人迷。"]},{"t":"林方伯先生七十初度是日为吕纯阳诞辰","f":"七言律诗","c":["共传薇省即蓬壶，白发中朝老大夫。","申甫何年曾降岳，仙翁此日正悬弧。","一杯琼液承金掌，九转丹砂在玉炉。","莫是贞元前进士，托生尘世住玄都。"]},{"t":"送人还九江","f":"七言律诗","c":["送君西去路漫漫，二月东风拥去鞍。","彭蠡惊涛云外听，匡庐飞瀑月中看。","天涯草色今犹短，驿路杨花尚未残。","不用临岐倍惆怅，一尊还共醉长安。"]},{"t":"读礼感怀 其一","f":"七言律诗","c":["相见黄泉未有期，每思往事泪交颐。","蠹生残箧长留粉，蛛匿空房乱结丝。","花径尚看扶杖处，柽阴犹记纳凉时。","绵绵此恨应无尽，忍读风人陟岵诗。"]},{"t":"读礼感怀 其二","f":"七言律诗","c":["何事当年便绝裾，误人应是荐贤书。","九天无处阍堪叩，三釜如今愿已虚。","却恨别离同梦寐，还惊日月易居诸。","从今不起云霄念，长向花间御板舆。"]},{"t":"读礼感怀 其三","f":"七言律诗","c":["素车白马出燕关，风急云寒雪满山。","当日已拚成死孝，此身何敢望生还。","忍看堂上遗容在，无复花前舞袖斑。","丹旐翩翩人不见，抚床空有泪潺湲。"]},{"t":"读礼感怀 其四","f":"七言律诗","c":["哭向灵帏唤不醒，可怜从此隔幽冥。","双凫影绝人何处，五柳阴浓户自扃。","藉草祗今稀酒伴，种花谁复课园丁。","回思二十年前事，日日窗前教一经。"]},{"t":"送兴公弟之吴为先人乞铭 其一","f":"七言律诗","c":["衔哀送汝出江关，满路悲风损别颜。","此日素车驱白马，几时黄绢勒青山。","梦回草色离肠断，身着麻衣血泪斑。","怜我双眸枯欲尽，不堪分手更潺湲。"]},{"t":"送兴公弟之吴为先人乞铭 其二","f":"七言律诗","c":["叮咛数语泪千行，此去关山路渺茫。","三伏炎蒸过剑浦，一江风雨度钱塘。","魂随远屿孤鸿断，目极遥天匹练长。","当念倚门双白发，莫将行色滞他乡。"]},{"t":"送王玉生游吴","f":"七言律诗","c":["几树蝉声乱夕晖，送君无奈泪沾衣。","花间此日人伤别，竹里从今客到稀。","吴苑山川行处遍，横塘烟雨望中微。","登楼王粲多乡思，目断秋风一雁归。"]},{"t":"寄王百谷","f":"七言律诗","c":["三载吴门两见君，别来相忆倍殷勤。","梦回半偈庵前月，望断姑苏台上云。","赤牍此时凭雁足，黄庭何日换鹅群。","先人墓所丰碑在，应赖邯郸绝代文。"]},{"t":"送王大游吴兼讯舍弟","f":"七言律诗","c":["潇潇风雨满征途，一片轻帆过阖闾。","路指蛇门怀伍相，剑藏鱼腹吊专诸。","砧敲八月寒声早，叶下三江树影疏。","若到吴阊凭问讯，天涯游子近何如。"]},{"t":"送陈子卿归墨潭精舍","f":"七言律诗","c":["送君归咏卜居篇，精舍平临绝涧前。","翠壁倒悬潭似墨，苍林遥望树如烟。","月移竹色当虚牖，风落松花满钓船。","闻说汉庭方羽猎，未应寂寞老扬玄。"]},{"t":"雨夜登玉皇阁","f":"七言律诗","c":["鳌顶秋深起夜凉，飘飘云气黯虚堂。","丹烧九转成金母，阁耸千寻礼玉皇。","灯影乍沉孤嶂雨，磬声微度半林霜。","古坛坐久天花落，不觉馀香满石床。"]},{"t":"中秋同惟秦震卿集汝大草堂看月因怀惟起客吴","f":"七言律诗","c":["西风萧瑟叶初黄，入夜行歌过草堂。","金粟散时天似水，玉绳低处月如霜。","尊前竹色浮秋霭，槛外松阴度晚凉。","遥望南飞有乌鹊，应怜游子滞他乡。"]},{"t":"逢庆良上人","f":"七言律诗","c":["东林结社已多年，忽汎慈航到海边。","自是真空能出世，谁知绮语不妨禅。","洗瓢曲涧摇寒月，卓锡深山破暝烟。","几度相从谈胜果，无诸城外即诸天。"]},{"t":"送良上人还金陵静海寺","f":"七言律诗","c":["枫叶萧萧露气凝，不堪江畔送名僧。","浮杯忍作无期别，说法谁参最上乘。","满路凄风闻宝磬，一天残月梦金陵。","悬知锡杖重来处，传得南宗几佛灯。"]},{"t":"王百谷为先永宁表墓寄此答谢","f":"七言律诗","c":["西风吹雁出菰芦，尺素衔来字字珠。","倚马万言推绣虎，皋鱼双泪感啼乌。","通家敢谓同文举，名笔何缘借董狐。","片石空山垂不朽，千秋应得免樵苏。"]},{"t":"送王生之临邛省州守叔父献甫 其一","f":"七言律诗","c":["西北胡笳不断吹，送君南浦泪如丝。","荆门树影云中尽，巫峡猿声月下悲。","客路装轻怀匕首，驿楼灯现望峨眉。","天涯何处能相忆，孤馆残更梦觉时。"]},{"t":"送王生之临邛省州守叔父献甫 其二","f":"七言律诗","c":["驱车万里向殊方，极目邛崃路渺茫。","官舍烟云邻越巂，人家风土杂夷羌。","绮琴曲里挑新寡，鼙鼓声中忆故乡。","丙穴由来鱼不乏，八行书札莫相忘。"]},{"t":"读礼日谢在杭拜官湖州便道还家见访赋赠","f":"七言律诗","c":["当时同听鹿鸣歌，此日云霄与薜萝。","鸡骨支来天上泣，马蹄惊向巷中过。","经年聚散踪无定，一见悲欢泪更多。","天上星辰催执法，相思又隔五湖波。"]},{"t":"后感怀 其一","f":"七言律诗","c":["家难相寻最可怜，麻衣如雪泪如泉。","慈雏返哺嗟无日，熊胆和丸忆昔年。","总为易凋萱草色，却教重废蓼莪篇。","杯棬尚在人何处，不待持来已惨然。"]},{"t":"后感怀 其二","f":"七言律诗","c":["满目悲风起白杨，幽明相隔路茫茫。","穗帷尘暗灵何在，宝婺星沉夜不光。","忽尔无心呼阿母，犹然有梦礼医王。","板舆此日难重御，一到花间一断肠。"]},{"t":"后感怀 其三","f":"七言律诗","c":["才入庭帏便怆情，遗容犹在不闻声。","蜀魂未化啼尤切，精卫空填恨岂平。","怀似陆郎徒有橘，孝惭考叔竟无羹。","可怜神理年来尽，已向尘中厌久生。"]},{"t":"后感怀 其四","f":"七言律诗","c":["一夕音容背北堂，人间那得返魂香。","百年浑似枝头露，双鬓难留镜里霜。","爻象谩劳推季主，刀圭空复藉韩康。","此身不但如荼苦，血泪千行更万行。"]},{"t":"哭李惟实孝廉 其一","f":"古风","c":["寒云惨淡日黄昏，壮士长衔万古冤。","易水当年歌变徵，湘潭此日赋招魂。","妖狐夜半啼原野，山鬼秋深哭墓门。","明岁素车过五岭，为君?泪荐芳荪。"]},{"t":"哭李惟实孝廉 其二","f":"七言律诗","c":["少年侠客擅词华，埋玉空山事可嗟。","自是关门多虎豹，总缘岁序在龙蛇。","诗馀长吉囊中草，梦绝文通笔里花。","十载交情惟一哭，西风吹泪到天涯。"]},{"t":"哭李惟实孝廉 其三","f":"七言律诗","c":["曾同击筑醉燕都，意气翩翩似狗屠。","良友忽传成死别，故人犹未束生刍。","秦廷恸哭知多少，梁狱投书果有无。","我在苦中情更苦，伤君那禁泪模糊。"]},{"t":"哭李惟实孝廉 其四","f":"七言律诗","c":["重泉冥漠隔知音，从此交期梦里寻。","飒飒悲风天外急，离离芳草墓前深。","千秋独抱亡琴痛，万里空怀许剑心。","杯酒他年浇白骨，北邙松柏恐成林。"]},{"t":"寄刘季德","f":"七言律诗","c":["故人踪迹久相违，何事犹然一布衣。","九鲤烟霞归草屩，五羊山水寄金徽。","竹期王子重来看，花向刘郎别后飞。","千里停云情不浅，秋风莫遣雁鸿稀。"]},{"t":"寄许灵长","f":"七言律诗","c":["年来何处寄行踪，闻在吴山第一峰。","古洞烟霞生薜荔，寒窗风雨泣芙蓉。","万家灯影千村月，半夜歌声满寺钟。","几度思君劳梦寐，钱唐江上水重重。"]},{"t":"寄旷上人","f":"七言律诗","c":["瓢笠何年住化城，闭关跏坐梦魂清。","双双月下浮屠影，夜夜云间断磬声。","悟彻空花诸相灭，翻残贝叶一灯明。","几时结得东林社，共證菩提了此生。"]},{"t":"邓汝高进士转饷辽东便道过家见访喜赠","f":"七言律诗","c":["才华籍籍赋长杨，裘马翩翩出建章。","辽海军储凭转饷，汉廷郎署待含香。","笑谈不带云霄气，名姓新依日月光。","独有故人憔悴甚，岂堪相对问行藏。"]},{"t":"送在杭司理湖州 其一","f":"七言律诗","c":["少年拥传暂还家，捧檄新乘上汉槎。","地接洞庭多橘柚，郡称泽国半桑麻。","省刑网好开三面，判事才能出五花。","手折衰杨从此别，梦魂飞不到天涯。"]},{"t":"送在杭司理湖州 其二","f":"七言律诗","c":["长安跃马主恩新，词客今为执法臣。","苕水共看初带印，沧波由此罢垂纶。","宽同汉室于廷尉，情似樊川杜舍人。","何处公馀堪引眺，三江烟雨五湖春。"]},{"t":"送在杭司理湖州 其三","f":"七言律诗","c":["曾将才藻擅词坛，此日新弹贡禹冠。","早岁共称贤宅相，少年初拜汉郎官。","霅溪水响褰帷听，顾渚山高拄笏看。","自是法曹关象纬，霜威先已逼人寒。"]},{"t":"送在杭司理湖州 其四","f":"七言律诗","c":["争传词赋是玄晖，捧得除书昼锦归。","属吏共迎新绿绶，世家犹说旧乌衣。","征亭霜冷孤鸿断，驿路天长驷马飞。","君去已陪鹓鹭侣，不才空守钓鱼矶。"]},{"t":"寄答沈从先","f":"七言律诗","c":["海国秋高一雁轻，题书千里见交情。","鹿门君已逃踪迹，鹤市谁能识姓名。","玄草谩忧瓿上覆，彩花长向笔中生。","浅才何敢当皇甫，欲序三都愧未成。"]},{"t":"得胡御长诗却寄","f":"七言律诗","c":["踪迹年来混酒徒，独留名姓满江湖。","卜居已傍三天竺，处世犹悲五石瓠。","刻石好辞传幼妇，闭门高论著潜夫。","胸中莫是波斯国，寄得瑶函字字珠。"]},{"t":"哭周所谐 其一","f":"七言律诗","c":["开缄忽报故人亡，双泪如倾几断肠。","挂剑未能同季子，知音何处觅周郎。","到来已叹交驩浅，死去空怜别恨长。","多少遗编犹在箧，一回吟咏一凄凉。"]},{"t":"哭周所谐 其二","f":"七言律诗","c":["当年风雨出芝山，行李萧然夜度关。","自谓千秋同艺苑，何期此夕谢人间。","几时客作鸣驴吊，何日人能化鹤还。","一掬木兰溪上泪，溪声应共泪潺湲。"]},{"t":"哭周所谐 其三","f":"七言律诗","c":["百年交谊隔泉扃，遥对西风泪自零。","欲以遗文托行世，敢将良友负幽冥。","朱弦既断谁同调，邻篴重吹岂可听。","不道精灵沉已久，夜来犹望少微星。"]},{"t":"哭周所谐 其四","f":"七言律诗","c":["生来长咏四愁诗，死后凄凉更可悲。","二顷久无尘满甑，一家虽在命如丝。","人亡正及黄花节，客吊空违宿草期。","未抚灵床先哽咽，难将遗嘱问孤儿。"]},{"t":"戏柬谢使君","f":"七言律诗","c":["绿衣红袖两相宜，况值还家得意时。","夜夜琴心调凤曲，双双屐齿伴蛾眉。","月明古渡寻桃叶，露冷空江唱竹枝。","不俟五湖携粉黛，今朝先已载西施。"]},{"t":"赠佘宗汉明府 其一","f":"七言律诗","c":["青鬓郎官早息机，抛将墨绶变荷衣。","一裘已傍壶山隐，双舄宁从帝里飞。","饮似公荣常得醉，游同禽庆久忘归。","年来门巷清如水，惟有寒鸥伴钓矶。"]},{"t":"赠佘宗汉明府 其二","f":"七言律诗","c":["翩翩辞赋似西京，四壁萧然类马卿。","山水到时皆屐迹，江湖何处不诗名。","閒来柳向门前种，老去花犹笔里生。","岁晏赍粮过九鲤，与君长啸结鸥盟。"]},{"t":"送李廷晔令东莞兼柬邓香山 其一","f":"七言律诗","c":["初从北阙佩鸣珂，拥传遥从五岭过。","官馔自今多海错，童谣强半是黎歌。","广州旧甓寻陶侃，粤国荒台吊尉陀。","只恐簿书能俗客，一封那肯问渔蓑。"]},{"t":"送李廷晔令东莞兼柬邓香山 其二","f":"七言律诗","c":["新悬墨绶赴炎方，道过家林束别装。","海邑三秋椰子熟，公庭六月荔枝香。","台中谒帝飞双舄，郡里寻仙问五羊。","莫向天涯思故国，一时冠盖半同乡。"]},{"t":"送丁亨文进士司理召陵 其一","f":"七言律诗","c":["新将词赋献承明，万里分符佐楚荆。","道上竹深妃子庙，郡中花暗白公城。","山连五岭重重翠，水接三湘曲曲清。","此去王程君莫缓，几多人吏待持平。"]},{"t":"送丁亨文进士司理召陵 其二","f":"七言律诗","c":["洞庭湖上片帆轻，万顷微茫接太清。","楚甸峰峦天际杳，巫山云雨梦中生。","霜侵远渚鲟千尺，月照寒芦雁一声。","白露渐零衣渐冷，遥知宋玉不胜情。"]},{"t":"邓汝高雨中载酒见访分得园字","f":"七言律诗","c":["甘将踪迹老丘园，忽听轩车到荜门。","篱下一尊残菊色，林间双屐旧苔痕。","暝烟疏雨山山暗，落木寒泉处处喧。","今日主人翻作客，不须送客独留髡。"]},{"t":"侯君右来自永嘉喜赠","f":"七言律诗","c":["西园公子旧知名，负剑长歌海上行。","何日寝丘酬楚相，谁人虚席重侯生。","赋成白雪骄彤管，衣带朱霞恋赤城。","闻说临邛方贵客，莫因残岁急归程。"]},{"t":"赠黄道晦隐君 其一","f":"七言律诗","c":["鸡犬声中隐者居，桃花流水绕庭除。","芝苓服久容颜古，草莽交深世态疏。","千顷沧江移艇钓，一犁春雨带经锄。","有时唤渡过城市，不是脩琴即借书。"]},{"t":"赠黄道晦隐君 其二","f":"七言律诗","c":["白首幽栖只一区，耻将名姓世人呼。","读书借得村中社，岁胜看将壁上图。","地僻绝来高士驾，家贫先办县官租。","山厨不问炊烟少，犹向桑间饭饿夫。"]},{"t":"问黄道晦病","f":"七言律诗","c":["久讶扁舟不出溪，闻君抱病意悽悽。","空山日晚阳乌促，古砌天阴络纬啼。","夜冷谁人同襆被，地偏何处得刀圭。","一从消渴文园后，门外蓬蒿与榻齐。"]},{"t":"方广岩","f":"七言律诗","c":["欲觅精庐问化机，苍苍鸟道客游稀。","上方云起暮山冷，半岭日斜残雪飞。","古树猿惊樵子过，寒林厖吠野僧归。","路迷叠嶂不知处，但听磬声来翠微。"]},{"t":"宿华严阁","f":"七言律诗","c":["万仞岩中隐化城，倚栏遥望暮云平。","断桥残雪寒山影，绝磴凄风晚磬声。","坐对水帘尘虑远，眠当石榻梦魂清。","因兹悟得西来意，欲向空门了此生。"]},{"t":"岩中晓望","f":"七言律诗","c":["早起看山露气浓，玄岩古院有云封。","微风入室度清梵，斜月挂林闻曙钟。","猿带晓声过碧嶂，鹤留残梦出青松。","倚阑但听水帘响，失却翠微千万重。"]},{"t":"重游锦溪怀邓汝高进士","f":"七言律诗","c":["断桥流水自潺湲，与客重来忆所驩。","当日共看溪上竹，于今偏握省中兰。","云生万壑孤筇湿，雪满千山两屐寒。","住散不须增感慨，一尊林下且盘桓。"]},{"t":"壬辰除夕","f":"七言律诗","c":["人事悠悠岁月徂，堂前空对一灯孤。","哀来瘦骨全如鹤，听得啼声半是乌。","酹酒几回悲伏腊，称觞明日罢屠苏。","春风不散终天恨，断尽柔肠泪欲枯。"]},{"t":"癸巳元日","f":"七言律诗","c":["袅袅东风处处吹，萧条门巷自堪悲。","独斟柏叶愁如缕，閒对菱花鬓有丝。","三十虚名归马齿，半生薄命怨蛾眉。","寒梅不管人无赖，开遍南枝与北枝。"]},{"t":"迎春日","f":"七言律诗","c":["风流太守驾朱轮，五马骄嘶九陌尘。","椒实共拚今日醉，梅花先报一年春。","娇莺乍啭声犹涩，綵燕初裁色更新。","市井繁华箫鼓沸，停鞭齐看玉楼人。"]},{"t":"春日怀旧","f":"七言律诗","c":["千山万水梦魂遥，箫鼓声中忆阿娇。","半夜朱楼巫峡雨，几行红泪浙江潮。","青鸾锦字终难寄，司马琴心不再挑。","一别西湖成隔岁，春风春雨长兰苕。"]},{"t":"寄陆无从","f":"七言律诗","c":["江北江南一水分，尺书无计寄殷勤。","芜城草色愁中远，扬子涛声梦里闻。","二十四桥孤嶂月，五千里路万山云。","相思何处堪惆怅，几树璚花对夕曛。"]},{"t":"寄夏玄成","f":"七言律诗","c":["故人别后忽经年，闻道衡门尚草玄。","隋苑花明高士宅，广陵涛满孝廉船。","一双屐齿春云外，两地离心夕照边。","夜夜江南梦江北，芜城风雨柳塘烟。"]},{"t":"过郑惠州墓 其一","f":"七言律诗","c":["三尺孤坟倚翠微，行人到此泪沾衣。","罗浮四百魂何在，华表千年鹤未归。","尘世功名悲薤露，空山松柏冷斜晖。","每逢寒食倍惆怅，风落残花满路飞。"]},{"t":"过郑惠州墓 其二","f":"七言律诗","c":["丘墓凄凄锁断烟，墓前春草自芊芊。","空林猿鸟寒云外，古路牛羊夕照边。","骨闭重泉悲永夜，榇归南海自何年。","经过再拜荐蘋藻，宰木萧森啼杜鹃。"]},{"t":"送赵仁甫令梁山","f":"七言律诗","c":["桃花零乱柳如丝，正是河桥赋别时。","衣带江州司马泪，帆过湘水舜妃祠。","凫飞双舄看应远，猿叫三声听渐悲。","夔府孤城纵临眺，阳台云雨望中疑。"]},{"t":"送人游吴楚","f":"七言律诗","c":["津亭垂柳绿烟丝，万里关山匹马迟。","去国正当春尽后，登楼多在日斜时。","楚江草长悲鹦鹉，吴苑花深走鹿麋。","说别何须共惆怅，秋风摇落是归期。"]},{"t":"淘江舟中送张博士之官镇海","f":"七言律诗","c":["淘江此夜暂同舟，千里清漳君去游。","春雨满庭肥苜蓿，青山一路响钩辀。","云开蜃结空中市，昼静鳣飞海上楼。","自是官閒堪坐啸，刺桐花下日淹留。"]},{"t":"过常思岭憩福海庵次韵","f":"七言律诗","c":["白云深处梵王家，回望千层鸟道赊。","满室空香薰贝叶，一声残磬落松花。","听经野鹿群依草，出定山僧独施茶。","礼罢瞿昙留偈别，寒鸦影里夕阳斜。"]},{"t":"紫云洞","f":"七言律诗","c":["石灯虚阁影沉沉，万壑松风起夕阴。","断壁只馀苍藓合，洞门长锁紫云深。","一声铁篴破残梦，半夜石钟清道心。","跨鲤仙人何处去，琪花瑶草不堪寻。"]},{"t":"淘江访林德凤茂才","f":"七言律诗","c":["一榻茅茨倚翠微，暂将生计托渔矶。","门当濑水潮常早，路绕方山客到稀。","窗外竹声喧午枕，庭前花片点春衣。","与君相见即相别，月落江头未忍归。"]},{"t":"宿鼓山寺方丈 其一","f":"七言律诗","c":["维摩丈室绝尘氛，坐对珠龛演梵文。","松际窥人孤嶂月，山中留客半床云。","疏钟出寺过林隐，怪鸟啼春彻夜闻。","真性由来爱空寂，名香亲向殿前焚。"]},{"t":"宿鼓山寺方丈 其二","f":"七言律诗","c":["孤峰天畔削芙蓉，入夜遥看紫翠重。","一片禅心千涧水，五更尘梦数声钟。","云生净土龙归钵，露冷空坛鹤唳松。","借宿僧寮经几载，苍苔埋却旧游踪。"]},{"t":"重游喝水岩","f":"古风","c":["古洞盘旋紫翠间，洞门常借白云关。","虚瓢挂树老僧隐，昏磬出林飞鸟还。","路到穷时尤?嶪，泉经喝后不潺湲。","当年旧社成陈迹，春雨春花点地斑。"]},{"t":"半山小憩呈惟秦","f":"七言律诗","c":["千层鸟道一筇扶，三月东风响鹧鸪。","花发幽岩红踯躅，云生绝壁翠模糊。","七闽形胜山河壮，万顷沧溟岛屿孤。","徐福求仙空入海，谁知此地即仙都。"]},{"t":"落花 其一","f":"七言律诗","c":["春光九十似飞蓬，点径残英片片红。","逐水几看过涧壑，因风时得入帘栊。","杜鹃有恨啼新泪，蛱蝶无心恋旧丛。","独有香魂飞不散，明年仍发故枝中。"]},{"t":"落花 其二","f":"七言律诗","c":["佳人无计可留春，每见纷飞祗自颦。","总为韶华能起恨，亦缘衰谢易伤神。","轻狂已逐泥中絮，流落空沾马后尘。","莫惜花前频载酒，浮生能得几花辰。"]},{"t":"落花 其三","f":"七言律诗","c":["一番风雨一番怜，却笑东皇浪有权。","才见芳英明苑上，忽惊飞片落阶前。","倦游公子辞金谷，醉舞佳人卸翠钿。","惆怅春光容易度，不堪凭槛听啼鹃。"]},{"t":"落花 其四","f":"七言律诗","c":["乍见清池映晓妆，惊看池面贴残芳。","武陵溪上春风暗，杜曲园中夜雨狂。","绿叶成阴空自媚，红英落尽尚馀香。","含情最恨东君恶，不向人间理断肠。"]},{"t":"柳","f":"七言律诗","c":["千丝万缕斗妖娆，和雨和烟陌上飘。","夜夜篴声关塞路，年年杯酒灞陵桥。","隋堤台女输浓黛，楚国佳人斗细腰。","只恐章台春易老，几回攀折恨萧条。"]},{"t":"白桃花","f":"七言律诗","c":["春风吹遍武陵源，幻出瑶枝树树繁。","色似何郎初傅粉，娇同妃子乍承恩。","开当柳絮浑无迹，落向苔裀觉有痕。","独爱羽衣花下客，玉笙声断月黄昏。"]},{"t":"桃花片","f":"七言律诗","c":["一夜天孙剪绛绡，满林红雨乱萧萧。","武陵溪上香魂散，露井风前艳质销。","粉黛凋残留半靥，胭脂零落带馀娇。","崔郎肠断寻春处，人面花容两寂寥。"]},{"t":"花影 其一","f":"七言律诗","c":["斜阳影里月明中，一种葳蕤幻两丛。","零露滴时还荡漾，轻云遮处更朦胧。","风吹频觉娇无力，天暝方知色是空。","忽讶落英飞满径，几回持帚误呼童。"]},{"t":"花影 其二","f":"七言律诗","c":["芳英灼灼叶蓁蓁，倒影雕栏态更新。","忽遇灯光成幻境，倩将月色为传神。","分明镜里看珠翠，彷佛帷中见玉人。","世界阴晴元不定，可怜生灭总非真。"]},{"t":"水中花影","f":"七言律诗","c":["一枝浓艳俯沧浪，彷佛还疑镜里妆。","波面波心飞蛱蝶，树头树尾宿鸳鸯。","浮萍点缀偏生色，流沫潺湲岂有香。","借问娇姿谁得似，洛神方在水中央。"]},{"t":"夕阳","f":"七言律诗","c":["羲驭难留忽已西，东山犹带一痕低。","能催古寺疏钟起，渐听孤城画角齐。","影入芦汀群雁落，光衔茅屋乱鸡栖。","此时谁是销魂者，戍妇闺中最惨悽。"]},{"t":"白雁","f":"七言律诗","c":["蹁跹刷羽度衡阳，遥望还疑缟素妆。","起处芦花飘岸渚，低时残雪点潇湘。","带来远塞千山月，叫落深林半夜霜。","影入薄云看不见，湖光漠漠楚天长。"]},{"t":"白燕","f":"七言律诗","c":["呢喃长日画梁中，素质冰肌迥不同。","玉剪飞时遥可辨，宝钗化去竟成空。","梁园梦绕梨花月，隋苑声残柳絮风。","莫恋乌衣归旧国，藏身合在水晶宫。"]},{"t":"弓","f":"七言律诗","c":["谁挽乌号五石强，由来猿臂可穿杨。","蛇疑杯里终难释，鸟尽林中便已藏。","开处流星过绝塞，挂时残月在扶桑。","世间得失原无定，尼父当年笑楚王。"]},{"t":"萍","f":"七言律诗","c":["有叶无根不用栽，还疑水面长苍苔。","游鱼吹浪重重乱，彩鹢冲波两两开。","却得微风依岸泊，不容明月入池来。","忽然一夜添新雨，踪迹飘零信可哀。"]},{"t":"蝶","f":"七言律诗","c":["傅粉娇姿五色衣，由来生性爱芳菲。","夜深栩栩梦中化，日午双双花底飞。","偷得馀香过别院，带将春色入帘帏。","只愁荏苒韶光暮，飘泊知从何处归。"]},{"t":"元夕冰灯","f":"七言律诗","c":["灯烛荧荧照夜阑，分明影里见琅玕。","双双罗袜凌波湿，朵朵金莲出水寒。","新制恍疑来贝阙，高悬只合在瑶坛。","为言火树休相逼，只恐清辉一夕残。"]},{"t":"虞美人草","f":"七言律诗","c":["青草香魂是翠蛾，托根元属楚山河。","年年野烧咸阳火，夜夜啼螀玉帐歌。","恨血清霜凝处满，泪痕残雨滴时多。","汉宫亦有如花貌，谁向春风化碧莎。"]},{"t":"病美人","f":"七言律诗","c":["长伴流苏与合欢，腰肢瘦尽黛眉残。","渐看衣带愁中缓，却恨春光枕上阑。","梦去何心游楚峡，起来无力步邯郸。","一从玉指纤纤困，挂壁秦筝久不弹。"]},{"t":"老农","f":"七言律诗","c":["容貌衰癯两鬓华，难将生计事污邪。","手栽禾黍知多少，眼见田园属几家。","时课儿孙勤耨穫，閒从邻叟话桑麻。","昨朝扶杖过春社，还祝瓯窭欲满车。"]},{"t":"老医","f":"七言律诗","c":["曾将奇术冠青囊，八十年前遇长桑。","臂在不知经几折，眼花何用检诸方。","有剂可令千人活，无药能销两鬓霜。","橘老杏残筋力尽，定应死去作医王。"]},{"t":"题王太史家藏孙都护墨菊","f":"七言律诗","c":["西园公子费隃麋，貌得寒花色更奇。","玄品合栽陶令宅，幽姿宜傍右军池。","青烟落处浑无辨，白露凝时却易知。","篱下几人能识取，秪疑佳种出松滋。"]},{"t":"水帘","f":"七言律诗","c":["潺潺千点响淙淙，一片冰绡挂碧空。","日射恍疑金络索，月明如坐水晶宫。","神龙喷处珠盈贯，玉女来时佩驭风。","十二阑干遥骋望，万重山色总朦胧。"]},{"t":"寿林天懋母黄太夫人 其一","f":"七言律诗","c":["百斛璚浆满玉壶，寿筵犹进大官厨。","堂前宾客皆鹓侣，膝下郎君是凤雏。","重见封章传内使，又看书信寄麻姑。","傍人莫问千秋算，五岳长存海不枯。"]},{"t":"寿林天懋母黄太夫人 其二","f":"七言律诗","c":["仙衣初剪紫霞绡，镜里霜鬟尚未凋。","贤媛正宜参八座，殊恩今已锡三朝。","吹从玄鹤空中度，书寄青鸾海上遥。","多少翟公门下客，纷纷犹进白云谣。"]},{"t":"冶城怀古 其一","f":"七言律诗","c":["千里山河霁色开，清秋临眺独徘徊。","虹桥隐隐龙江绕，雁塔双双雉堞回。","落日寒潮螺女渡，冷烟衰草越王台。","当年霸业俱尘土，愁听荒原鸟雀哀。"]},{"t":"冶城怀古 其二","f":"七言律诗","c":["冶城日落乱啼鸦，城上乌乌起暮笳。","四野桑麻八闽郡，千村烟火万人家。","无诸古殿伤青草，南宋行都想翠华。","人事已非湖水在，年年风雨长蒹葭。"]},{"t":"垂虹桥别顾学宪先生","f":"七言律诗","c":["垂虹桥畔水悠悠，无数青山起暮愁。","桐叶战风惊远梦，芦花含月隐孤舟。","吴江露下丹枫冷，震泽云寒白雁秋。","此去风帆何处泊，相思明日隔沧洲。"]},{"t":"夜闻吴女诵经","f":"七言律诗","c":["佳人何意悟禅那，夜诵金经数百过。","窈窕相中疑大士，妖浮声里半弥陀。","还于女伴歌吟懒，自与尼师结拜多。","谩道西邻归彼岸，此生无计渡恒河。"]},{"t":"拟咸阳怀古","f":"七言律诗","c":["咸阳禾黍正离离，人代兴亡岂有期。","废殿秋风秦剑戟，荒山夜雨汉旌旗。","茂陵空洒千行泪，渭水长流万古悲。","何处登临最惆怅，乐游原上日斜时。"]},{"t":"爱妾换马 其一","f":"七言律诗","c":["如燕如龙户外嘶，行云行雨意悽悽。","青蛾永别黄金屋，赤兔新翻碧玉蹄。","虽有飞腾空冀北，更无歌舞出楼西。","他时紫陌相逢处，望见银鞍不住啼。"]},{"t":"爱妾换马 其二","f":"七言律诗","c":["双眉颦蹙四蹄翻，皂枥无声被不温。","憔悴难忘当日宠，悲鸣犹恋主人恩。","强随夜月登妆阁，愁逐秋风出塞垣。","金埒玉楼遥骋望，几多汗血几啼痕。"]},{"t":"夏日灵山堂避暑","f":"七言律诗","c":["灌木阴中共倚栏，飞来苍翠落檐端。","满林花雨诸天近，六月松风一座寒。","鸟入乱云翻影灭，蝉当斜日送声残。","相逢正有淹留兴，其奈疏钟报夜阑。"]},{"t":"越王台怀古","f":"七言律诗","c":["山河如故霸图休，台下空江水自流。","岁久莓苔生庙壁，日斜葭菼满汀洲。","旌旗影灭秋风冷，剑戟声沉暮雨愁。","莫道钓龙人已远，精灵还向夜深游。"]},{"t":"寄长溪史使君德明","f":"七言律诗","c":["少年作郡到长溪，五马时从柳外嘶。","官舍鸟啼春寂寂，公庭吏散草萋萋。","山城夜月闻弦诵，瘴海秋风绝鼓鼙。","日向习家池上醉，儿童争唱白铜鞮。"]},{"t":"送林熙工陈汝翔陈伯孺潮上人游武夷","f":"七言律诗","c":["津亭落木已纷纷，无那离情对夕曛。","极浦风烟随鸟尽，寒潭秋色与僧分。","兰舟独载千峰月，竹杖同扶九曲云。","此日江蓠正堪采，为余遥荐武夷君。"]},{"t":"秋日陈汝大载酒林氏水亭","f":"七言律诗","c":["满天秋色雁边遥，载酒芳园暑气消。","柳外鸣蝉寒度雨，竹间小浦暗通潮。","半林绿树迷危堞，一带苍山隔断桥。","此地相逢不沉醉，更于何处避尘嚣。"]},{"t":"送老卒还乡","f":"七言律诗","c":["少小从军出玉门，萧萧白发返丘园。","塞垣此别休回首，旧路重经更断魂。","残橐只馀孤剑在，故乡知有几家存。","古来征戍生还少，何必封侯是主恩。"]},{"t":"经古战场","f":"七言律诗","c":["萧条残垒不胜悲，此地曾经几乱离。","恨血尚馀春草里，游魂多出夕阳时。","潇潇寒雨闻刁斗，漠漠阴云见羽旗。","满路干戈愁转战，胡笳休向马头吹。"]},{"t":"赠颜廷愉将军 其一","f":"七言律诗","c":["姓名曾冠少年场，逆旅相逢意慨慷。","能以三都雄艺苑，还将一剑倚扶桑。","燕台击有荆轲筑，粤国游无陆贾装。","为爱琅邪门下士，如君词赋独升堂。"]},{"t":"赠颜廷愉将军 其二","f":"古风","c":["诗名久已动长安，此日仍登上将坛。","投笔耻为秦博士，横戈今作汉材官。","常?一命酬知己，不爱千金赠所驩。","莫道书生无远略，东封函谷有泥丸。"]},{"t":"秋日居法云寺喜瀚上人见访","f":"七言律诗","c":["门掩苍苔一径幽，白云应为远公留。","疏钟隐隐诸天暮，残叶萧萧满地秋。","竹院又逢今日话，芝山犹忆旧时游。","此中传偈多禅侣，何必浮杯到沃州。"]},{"t":"秋夜同颜廷愉黎廷彬二将军王元直秀才观微上人兴公舍弟集邓道鸣阃帅行署赋得紫薇夜漏同用花字","f":"七言律诗","c":["虚堂良会寂无哗，忽听谯楼鼓乱挝。","响入招提随断磬，声传睥睨杂悲笳。","共占此地星文聚，莫问中宵斗柄斜。","滴尽铜壶天似水，月光初转紫薇花。"]},{"t":"颜廷愉旅馆夜集闻歌","f":"七言律诗","c":["越王城里起西风，旅馆相看兴不穷。","词客交情联缟带，美人幽恨寄丝桐。","当筵夜静灯花绿，隔寺秋深落叶红。","此去岂愁逢醉尉，踏歌齐向月明中。"]},{"t":"陈廉访先生七十初度","f":"七言律诗","c":["投簪久矣老沧洲，共说神仙是隐侯。","衣剪烟霞轻豸绣，家营云水比菟裘。","数茎瑶草千年绿，九月黄花一径秋。","不用寻仙访真诀，姓名元已注丹丘。"]},{"t":"送陈道育游吴","f":"七言律诗","c":["西风萧瑟不胜愁，无奈同心赋远游。","一带青山吴苑暮，满林黄叶太湖秋。","离魂渺渺随鸿断，乡泪潺潺逐水流。","况是天涯摇落后，岂堪为客独登楼。"]},{"t":"得李伯实太学书知其移家金陵却寄","f":"七言律诗","c":["天涯久别正销魂，忽尔开缄见泪痕。","东粤梅花留去客，南朝芳草待王孙。","春风八口依京国，夜月千山梦故园。","往事伤心君莫问，台城烟柳易黄昏。"]},{"t":"同王元直读书法云寺赋赠","f":"七言律诗","c":["精庐高傍玉蝉峰，采葛歌成意更浓。","把臂共挥花下麈，连床同听佛前钟。","覆棋怜尔如王粲，倒屣何人是蔡邕。","白首交期谁得似，寺门遥指岁寒松。"]},{"t":"送林叔度游支提寺","f":"七言律诗","c":["何时踪迹别壶公，岁晚看山过霍童。","客路杖藜残雪里，人家鸡犬乱云中。","钟闻下界诸天近，寺隐深林一径通。","遥想空门多胜事，半龛明月几僧同。"]},{"t":"赠别康孟担","f":"七言律诗","c":["一丘栖隐近何仙，不异庞公在汉年。","名混布衣堪傲世，斋供绣佛可逃禅。","尊前有客同浮白，身后谁人识太玄。","此别相思劳梦寐，壶山云树鲤湖烟。"]},{"t":"送陈元凯明经北上兼觐省 其一","f":"七言律诗","c":["津亭落叶点衣斑，斗酒临岐动别颜。","江上流澌前岭雪，马头晴树隔淮山。","征途岁晚鸿声断，上苑春深草色閒。","此去趋庭驩不浅，可无飞梦到乡关。"]},{"t":"送陈元凯明经北上兼觐省 其二","f":"七言律诗","c":["江干分手动悲歌，迢递关山岁杪过。","独夜怀人魂梦远，中年知己别离多。","车驱微月寒登陇，马踏残冰晓渡河。","若遇长安旧相识，为言生计久蹉跎。"]},{"t":"送叶进卿太史还朝","f":"七言律诗","c":["星轺万里上长安，岁晚关河雪欲残。","剑佩晨趋金阙霁，丝纶夜草玉堂寒。","千条御柳鸣鞭过，五色宫云拄笏看。","幸有同心在霄汉，清时无用赋猗兰。"]},{"t":"陈汝大六十初度","f":"七言律诗","c":["年少曾窥宝笈文，老来高卧谢尘氛。","吟边野兴随青草，世外馀生付白云。","大药已传龙虎秘，閒身应混鹿麋群。","桑弧正及黄花节，一度花开一寿君。"]},{"t":"送人之边 其一","f":"七言律诗","c":["万里横戈赋远征，天涯去住不胜情。","隔河猎火秋调马，古戍狼烟夜列营。","沙碛春深无草绿，边城乱后少人行。","客中知有还乡梦，莫听孤笳月下声。"]},{"t":"送人之边 其二","f":"七言律诗","c":["漠漠黄尘匹马孤，马头今去向飞狐。","望乡台畔无青草，策勒城头有白乌。","满路寒霜朝倚剑，一天明月夜吹芦。","单于莫近阴山猎，南国书生正弃繻。"]},{"t":"无题和李义山 其一","f":"七言律诗","c":["香烬金猊烛散风，月沉西岭水流东。","云迷洛浦人何处，柳暗章台路不通。","远岫似凝眉上翠，守宫犹染臂间红。","凄凉往事休重省，十载游踪叹转蓬。"]},{"t":"无题和李义山 其二","f":"七言律诗","c":["为雨为云无定踪，半衾幽恨数声钟。","弦于离绪同时断，墨与啼痕一样浓。","无复芳心含豆蔻，空将薄命委芙蓉。","西邻只在高楼畔，似隔天台路几重。"]},{"t":"拟刘晨阮肇入天台效曹唐","f":"七言律诗","c":["历尽千山与万山，白云飞处见松关。","路从碧涧通仙窦，梦绝红尘出世间。","花落洞中春寂寂，日斜溪上水潺潺。","哀呼四壁多猿鸟，迷却来踪不可还。"]},{"t":"刘阮洞中遇仙子","f":"七言律诗","c":["路入天台境寂寥，空中吹送白云谣。","桃花片片流丹壑，瑶草青青映翠翘。","五色烟霞迷鹤梦，数声环佩隔虹桥。","人生莫道仙凡别，携手春风是此宵。"]},{"t":"仙子送刘阮出洞","f":"七言律诗","c":["鸡犬声中羽袖分，桃花折赠寄殷勤。","愁来玉液谁同饮，别后瑶笙忍独闻。","踪迹但随溪上水，仙凡只隔洞前云。","从今万劫仍千劫，惆怅无缘再遇君。"]},{"t":"仙子洞中忆刘郎","f":"七言律诗","c":["佳期谁信此生休，梦断巫山几度秋。","瑶草似怜人远去，桃花仍逐水东流。","红尘夜月空留枕，紫府春风独倚楼。","只恐重来迷处所，洞门深锁碧苔幽。"]},{"t":"刘阮再至天台不复见仙子","f":"七言律诗","c":["重到仙源路转深，旧游踪迹已销沉。","千年山水自朝暮，四壁烟霞成古今。","不见胡麻流别涧，独闻幽鸟噪空林。","早知一别无寻处，应悔当时出洞心。"]},{"t":"萼绿华将归九疑留别许真人","f":"七言律诗","c":["缥缈云軿驾彩霓，半天遥听玉麟嘶。","身归紫府难为别，目断红尘不住啼。","新启离筵铺凤髓，重封真诰印龙泥。","黄金条脱空留赠，九点青山望已迷。"]},{"t":"玉女杜兰香下嫁张硕","f":"七言律诗","c":["黄金钗股紫金钿，忽驾鸾车降碧烟。","百尺虹桥天上路，万条花烛世间缘。","云璈曲妙调龙琯，露液杯浓启凤筵。","却笑裴郎仙分浅，一双玉杵种多年。"]},{"t":"张硕重寄杜兰香","f":"七言律诗","c":["渺渺灵踪去不还，空劳珍重碧云鬟。","人间无路通瑶阙，梦里何因见玉颜。","兰露半销香冉冉，花风初度佩珊珊。","欲将一札传青鸟，知住蓬莱第几山。"]},{"t":"织女寄牛郎","f":"七言律诗","c":["临流几度待金飙，天帝无情恨鹊桥。","玉宇微茫空隔水，银河清浅不通潮。","心随凤驾思灵匹，泪逐龙梭上锦绡。","难得欢娱容易别，年年肠断可怜宵。"]},{"t":"甲午迎春","f":"七言律诗","c":["家家箫鼓响何频，海国惊看物候新。","自有东风吹綵胜，不愁微雨洒红尘。","土牛未送山中腊，宝马先行岁里春。","三十三龄容易过，蹉跎又是隔年人。"]},{"t":"岁暮感怀","f":"七言律诗","c":["年来踪迹叹蹉跎，独向衡门恋薜萝。","前路虚名青鬓少，先人遗业白云多。","匆匆短晷愁中尽，冉冉浮生梦里过。","时事凄凉应莫问，空山相对意如何。"]},{"t":"甲午元日","f":"七言律诗","c":["平明曙色乱春烟，独对东风意惘然。","蓂叶乍开尧砌上，椒花先献佛灯前。","忽闻爆竹迎新岁，愧饮屠苏后少年。","莫道清霜随腊尽，只愁飞入鬓毛边。"]},{"t":"赠邓道鸣都阃","f":"七言律诗","c":["千骑如云瘴海间，一天明月照刀环。","营门昼静笙歌沸，部曲秋高剑戟閒。","乐奏金铙新破敌，名标铜柱旧平蛮。","玉关他日功成后，犹见将军鬓未斑。"]},{"t":"送林贞发之汉阳兼寄陈仲敬明府","f":"七言律诗","c":["江干折柳正春初，闽楚相看万里馀。","满路愁云过七泽，一天明月吊三闾。","帆飞汉水莺声早，书到衡阳雁影疏。","为语神明河上宰，故人生计已樵渔。"]},{"t":"王相如文学千里来访诗以赠别","f":"七言律诗","c":["少年名姓满词场，千里相寻问草堂。","博物每披周石鼓，摛文能赋鲁灵光。","九龙夜吼门前水，疋马秋归岭外霜。","收得秘书盈万卷，王家事业本青箱。"]},{"t":"送欧阳霖仲归乡","f":"七言律诗","c":["梁狱书成泪未乾，天涯流落畏途难。","杼投已信曾参语，袍赠谁怜范叔寒。","逆旅相逢愁咄咄，故乡归去路漫漫。","布衣正好弹长铗，何必逢人变鹖冠。"]},{"t":"送周公子还金溪","f":"七言律诗","c":["彭蠡西归去棹长，东风江上送周郎。","数声忍顾歌骊曲，三月惟赍养鹤粮。","寄远柳应攀驿路，思亲花每梦河阳。","家山况与丰城近，别后遥看剑气光。"]},{"t":"送徐半刺之官淮阳","f":"七言律诗","c":["东风吹送片帆轻，江北江南万里程。","隋柳似迎行客过，淮流难比使君清。","尚怀太姥看山梦，新就盐官煮海名。","盘里水晶堪饷客，几时重见故人情。"]},{"t":"甲午端阳即事","f":"七言律诗","c":["满市贫民尽噪呼，谁家尊酒汎菖蒲。","汉廷久已饥方朔，楚泽何人吊左徒。","残喘厌看长命缕，空囊安用辟兵符。","愁来试上孤城望，几处炊烟几处无。"]},{"t":"将发芋江别惟起惟扬二弟","f":"七言律诗","c":["霜落乌啼半上潮，江头那忍解兰桡。","已悲去路关山远，况复归期岁月遥。","衰鬓依人愁冉冉，荒年为客橐萧萧。","他时两地同相忆，记得离筵是此宵。"]},{"t":"饮胡元瑞萝月轩","f":"七言律诗","c":["停棹来寻瀔水阳，半窗萝月坐飞觞。","阶前鹤迹留苔浅，秋后蝉声出树凉。","客路蒹葭寒细雨，他乡砧杵度微霜。","布帆东下江流急，满目西风别恨长。"]},{"t":"寄别幼孺次来韵","f":"七言律诗","c":["故国青山又远违，怀人空有梦魂飞。","猿当暮雨声偏惨，雁到秋风影尚稀。","一夜思乡华发变，中年为客壮心微。","竹林此日无多侣，莫向山中厌布衣。"]},{"t":"寄赠屠长卿仪部 其一","f":"七言律诗","c":["姓名曾注玉皇家，吸尽遥天五色霞。","一点真阳封土釜，六时神水转河车。","黄冠长日居蓬岛，紫气中宵隔若耶。","莫道相逢期太晚，于今佳谶有龙沙。"]},{"t":"寄赠屠长卿仪部 其二","f":"七言律诗","c":["一区长傍鉴湖边，坐对三花九品莲。","家散黄金惟塑佛，诗成白雪半游仙。","栖禅净室云堪卧，驭气遥空电可鞭。","他日从君无别语，祗应同證大因缘。"]},{"t":"题公朗宝函楼","f":"七言律诗","c":["危楼百尺梵王居，禅诵声高晚磬初。","一榻秋云松火冷，半窗残月竹阴疏。","鹫峰花雨诸天外，猊座金身六代馀。","多少尘劳都遣尽，独留诗癖未全除。"]},{"t":"寄怀瀚公","f":"七言律诗","c":["逆旅裁书问道安，故园明月几回看。","身閒对客题诗易，岁俭逢人乞米难。","风动空山孤锡响，霜深禅榻衲衣寒。","知师不作天涯梦，长夜忘眠坐戒坛。"]},{"t":"松陵舟中","f":"七言律诗","c":["西风吹袂失炎蒸，落日波光似镜澄。","囊里钱馀缘戒酒，途中舟缓为寻僧。","孤村近浦船为市，古寺临江塔有灯。","一带人烟何处所，榜歌遥指是松陵。"]},{"t":"吴阊吊高季迪太史","f":"七言律诗","c":["吴门灯火正黄昏，读罢遗编湿泪痕。","五字几人传故业，一杯何处吊吟魂。","秋风茂苑留荒草，暮雨寒山泣断猿。","欲向居人问封土，衣冠未必葬家园。"]},{"t":"旅次石头岸","f":"七言律诗","c":["石头城下水微茫，回首乡关驿路长。","瓜步烟波连断霭，秦淮云树隔斜阳。","秋高落木迷村舍，夜静寒潮到女墙。","客里愁心已如此，一闻南雁更凄凉。"]},{"t":"金陵怀古","f":"七言律诗","c":["白门京阙旧山川，朱雀乌衣夕照边。","百代荒陵崩夜雨，六朝遗殿锁秋烟。","胭脂岁久销宫井，苔藓春深绣御筵。","往事凄凉无限泪，伤心最是建文年。"]},{"t":"客中感秋呈王德载卢子明柳陈甫诸公","f":"七言律诗","c":["他乡为客长离忧，一夜新寒感敝裘。","对酒正当桑落后，思家偏向雁来秋。","白门月冷砧初断，淮水霜深叶自流。","不是天涯有知己，萍踪那得久淹留。"]},{"t":"送张孺愿还四明为儿娶妇","f":"七言律诗","c":["离情黯淡白门西，何处云山是会稽。","作客暂辞桃叶渡，思乡多梦若耶溪。","寒芦夜雨鸿初断，衰柳残阳马倦嘶。","待汝尚平婚嫁毕，五湖明月共招携。"]},{"t":"送胡彭举之衡阳","f":"七言律诗","c":["愁折衰杨过御堤，吴门遥望楚云低。","高峰见月秋回雁，野店逢霜晓听鸡。","九派江流湓浦外，一天帆影洞庭西。","知君作客年来惯，不畏猿声日夜啼。"]},{"t":"葛震父招游雨花台同张康侯姚佩卿诸子","f":"七言律诗","c":["高台千尺俯烟霞，却望当年旧帝家。","百雉都城仍踞虎，六朝宫树半栖鸦。","云边淮水连天远，林际钟山带郭斜。","独有空门不销歇，至今犹落讲坛花。"]},{"t":"送陆纂父山人还洞庭别业","f":"七言律诗","c":["他乡相见又离群，满目西风落叶闻。","二水空洲孤棹远，三吴秋色一江分。","白衣出郭金陵雨，绿酒看山震泽云。","从此游踪各南北，月明无处不思君。"]},{"t":"同吴翁晋姚叔乂诸子集陈公衡衙斋","f":"七言律诗","c":["南朝仙吏擅风流，四海论交半敝裘。","粉署鸟啼花外雨，白门鸦散柳边秋。","故宫云气销长乐，近郭湖光起莫愁。","马踏夜分归路晚，疏钟遥动景阳楼。"]},{"t":"赠李茂承太学","f":"七言律诗","c":["云间才子气翩翩，偶尔相逢入洛年。","半夜孤帆三泖月，一秋双屐六朝烟。","匣中紫气频看剑，笔底青山不卖钱。","同是天涯流落客，何妨长醉酒垆边。"]},{"t":"隔帘美人","f":"七言律诗","c":["环佩声闻见不真，多情绰约往来身。","只缘竹纬垂千缕，似对菱花隔一尘。","绣带暗飘纹外影，秋波潜送隙中春。","重重锦浪生罗袜，彷佛云间遇洛神。"]},{"t":"同梅季豹林叔度碧峰寺访如愚上人","f":"七言律诗","c":["行尽空林到沃洲，满林黄叶上方秋。","松遮古殿半山翠，竹隐空房三径幽。","宝盖影飘依佛座，昙花香散拂经楼。","年来绮语方除障，不敢题诗赠惠休。"]},{"t":"同闵寿卿王献子二山人集王德载都护溪阁同得萧字","f":"七言律诗","c":["尊酒凭虚破寂寥，秣陵云物晚萧萧。","窗开远岫常邀月，阁枕寒溪共听潮。","万里风烟天外尽，满林秋色雁边遥。","主人久傍墙东隐，不向西山更射雕。"]},{"t":"马姬馆赠梅子马","f":"七言律诗","c":["宝剑逢人脱赠轻，平生肝胆片言倾。","千秋白社工文客，半世青楼薄倖名。","枕上杨花今日泪，渡头桃叶旧时情。","囊中不管黄金尽，犹买娇歌夜夜声。"]},{"t":"寿雪浪禅师九月九日五十初度","f":"七言律诗","c":["祗林遥见白毫光，发祝多年尚未苍。","菩萨应期生下土，圣人此日出西方。","阶前记腊松长在，座上拈花菊正香。","一自九龙仍吐水，从今浴佛说重阳。"]},{"t":"金陵故宫","f":"七言律诗","c":["先朝遗殿闭尘埃，零落空劳过客哀。","五夜铜壶乾罢滴，六宫金锁涩难开。","翠华去后全无影，罗绮焚馀尚有灰。","弓剑尽埋烟雨冷，椒房一半上苍苔。"]},{"t":"重阳后顾世卿招游清凉寺翠微亭","f":"七言律诗","c":["虚亭高与翠微连，尚有黄花照法筵。","下界梵音中夜磬，半空帆影隔江船。","马行十里松阴月，人藉孤峰草色烟。","我本倦游多感慨，老僧休说六朝年。"]},{"t":"陈彦庄侍御招游清凉寺","f":"七言律诗","c":["同向空门结白莲，琳宫遥隐帝城边。","闭关僧是他方衲，题壁人多异代贤。","江北江南千里月，山前山后万家烟。","座间自有霜威肃，避暑何须说往年。"]},{"t":"送何伯达太学还鲤湖","f":"七言律诗","c":["岁晚扁舟发水濆，劳劳亭下叹离群。","一行雁影斜阳见，几处砧声半夜闻。","作客厌看吴苑月，思亲翻望秣陵云。","他时九漈劳魂梦，跨鲤仙人正是君。"]},{"t":"燕子矶","f":"七言律诗","c":["芦荻萧萧远水平，沉江铁锁尚留名。","半空鹳鹤飞来影，千载鼋鼍化去精。","石占中流危截浪，云侵残垒暝吞城。","山僧似惜游人别，犹送疏林磬一声。"]},{"t":"观浦口珠泉","f":"七言律诗","c":["一泓如练净无尘，幻出明珠颗颗新。","疑是鲛宫逢贾客，难于金谷换佳人。","夜光不说昆明水，照乘何须合浦滨。","生灭由来归泡沫，欲将灵迹问波神。"]},{"t":"访梅禹金秦淮客舍","f":"七言律诗","c":["舟过长干问客星，风流不用叹飘零。","一秋桃叶居淮水，十月梅花梦敬亭。","游遍南朝多宝寺，翻残西竺几函经。","赠君欲折藏鸦柳，满目隋堤何处青。"]},{"t":"谢司理招游道场山","f":"七言律诗","c":["碧树香台一径纡，满林幽鸟避前驱。","重重翠巘看苍弁，渺渺层波见太湖。","钟送馀声过下界，云留残影挂浮屠。","画船载月归来晚，十里烟光澹欲无。"]},{"t":"谒孙山人太初墓兼怀郑吏部继之","f":"七言律诗","c":["道场山下见荒阡，欲吊吟魂一怆然。","寂寂梨花寒食雨，萧萧蒿草夕阳烟。","空林夜静闻猿啸，断碣年深借鹿眠。","若把梅亭比苕水，千秋黄土总堪怜。"]},{"t":"闺情","f":"七言律诗","c":["深闺长日望刀环，锦被香销绣幕閒。","岂有梦魂通暮峡，更无眉黛画春山。","情牵夜月孤蛩泣，目断秋风一雁还。","不是狂夫恩意浅，由来薄命怨朱颜。"]},{"t":"同强善长包蒙吉计仲嘉徐子晋斯学上人集宝林寺镜公房时蒙吉来自东瓯仲嘉归自燕赵","f":"七言律诗","c":["吴市飘零感岁华，偶携瓢笠到僧家。","孤云静结人天果，朔气寒生佛座花。","作客畏闻燕地雪，逢君先问赤城霞。","山中欲别各留偈，送过虎溪将日斜。"]},{"t":"为王百谷悼亡","f":"七言律诗","c":["不顾房帷十载恩，窃将灵药月中奔。","楚台有枕难通梦，汉殿无香可返魂。","夜静鸳鸯虚锦帐，昼长鹦鹉唤璚轩。","小星三五沉何处，垂老青衫湿泪痕。"]},{"t":"虎邱寺","f":"七言律诗","c":["千顷寒云隐上方，半天明月照回廊。","玉凫化去山精灭，金虎销残宝气荒。","塔影虚空藏舍利，泉声日夜淬干将。","霸图零落浮图在，不拜吴王拜法王。"]},{"t":"赠彭城苏姬","f":"七言律诗","c":["苏小门前系紫骝，隔帘相见尚含羞。","青蛾暂结花间约，绿蚁能忘客里愁。","一片轻寒销枕簟，半窗明月上箜篌。","从今若过彭城路，不说张家燕子楼。"]},{"t":"初春德州道中有怀故园","f":"七言律诗","c":["落日平原朔气凝，征途迢递倦难胜。","风生沙捲残年雪，春至河销半渡冰。","古戍黄昏喧断角，远村寒夜见孤灯。","莺花自爱家林好，裘马何心向五陵。"]},{"t":"易水怀古","f":"七言律诗","c":["一笑秦庭事已空，萧萧寒气动悲风。","飞霜枉购千金匕，贯日犹悬百丈虹。","公子歌残衣变白，田光死去血流红。","蓟门零落咸阳火，易水年年只向东。"]},{"t":"同许灵长太学张去华山人陈幼孺曹能始二孝廉集邓汝高计部署中赋得长安新柳送张成叔太学还四明","f":"七言律诗","c":["东风二月蓟门过，新柳青青拂御河。","浅绿乍分眉上黛，柔条难任笛中歌。","几时叶满章台路，有日花飞太液波。","同是一枝堤畔种，无如此地别离多。"]},{"t":"下第后书怀 其一","f":"七言律诗","c":["自是扬云白未玄，不才那敢怨苍天。","回看故国八千里，误戴儒冠十七年。","贫倚诗书元失计，穷知文字信无权。","雄心销尽囊如水，流落依人面可怜。"]},{"t":"下第后书怀 其二","f":"七言律诗","c":["一领青衫万斛尘，沟隍十口计全贫。","关河偏阻空囊客，童仆潜归得意人。","云路岂能容野性，帝乡元不住閒身。","长安浪说春光好，未见丘园非是春。"]},{"t":"南还留别许灵长张叔韬冯咸甫邓泰素文梦珠柯起之诸子","f":"七言律诗","c":["日落燕关马去迟，一尊相对总相悲。","岂堪客路销魂处，正值皇都失意时。","此去恶分灯下影，重来愁益鬓边丝。","与君俱是飘零者，空说加餐赠别离。"]},{"t":"谒孔林","f":"七言律诗","c":["洙泗潆回两派分，泰山龙护素王坟。","传经已化三千士，执贽难逢七十君。","室筑空场生蔓草，树残荒陇起寒云。","一抔马鬣勤瞻拜，欲向春风荐鲁芹。"]},{"t":"燕子楼","f":"七言律诗","c":["旧日欢情委逝波，空楼灯影恨如何。","一天夜月閒箫管，十载春风罢绮罗。","松柏锁烟愁思苦，牡丹含雨泪痕多。","香销粉歇歌尘散，忍见双双燕子过。"]},{"t":"书怀","f":"七言律诗","c":["岁月蹉跎黯自惊，此身虽在鬓毛更。","江湖故旧无消息，童稚交游半死生。","喜信空门缘渐老，厌闻往事为多情。","客中最是愁人处，独夜残灯风雨声。"]},{"t":"闻人仲玑卜居西湖诗以寄之","f":"七言律诗","c":["卜筑南屏第几峰，烟霞长日伴游踪。","桥头柳色湖心月，郭外潮声寺里钟。","数载宦情同失马，千秋绝技羡雕龙。","兰桡竹杖频来往，十里荷花九里松。"]},{"t":"女冠还俗","f":"七言律诗","c":["愁戴黄冠老此身，芳心难禁黛眉颦。","且抛王母当年约，去了萧郎宿世因。","斗帐自今开甲乙，星坛谁复守庚申。","几回却笑巫山女，云雨空为梦里人。"]},{"t":"戏嘲郑四效长庆体","f":"七言律诗","c":["落落江湖无定迹，匆匆相见阖庐城。","离乡已是五六载，道旧曾无三两声。","杯水覆堂难再返，浮云出岫便无情。","故人浪说工词赋，只恐登楼赋未成。"]},{"t":"登延平玄妙观","f":"七言律诗","c":["玄都俯瞰碧溪濆，上帝高居接五云。","入院经声朝斗拜，绕坛香气降真焚。","龙精护法丰城剑，鸟篆书符玉洞文。","月满松关天籁寂，飘飖笙鹤半空闻。"]},{"t":"登芝山善见塔","f":"七言律诗","c":["百转清溪绕梵宫，千寻丹磴势盘空。","昙花乱散诸天雨，桥板斜飞一线虹。","塔影层层青嶂外，钟声隐隐白云中。","凭阑不敢轻呼吸，帝座溟濛近可通。"]},{"t":"谒马仙姬庙","f":"七言律诗","c":["元君仙籍出扶风，庙食千年建水东。","满院松杉巢鹳鹤，四时香火卜罴熊。","青天紫气生灵幄，白日红云护寝宫。","几度凭虚朝上帝，手抛霞帔幻成虹。"]},{"t":"初至武夷","f":"七言律诗","c":["道缘为重世缘轻，总属閒游岂计程。","九曲仙班邀鹤驭，半空天乐奏鸾笙。","经旬绝粒抛烟火，到处行歌变姓名。","多少函中遗蜕在，不知若个是前生。"]},{"t":"万年宫","f":"七言律诗","c":["万年宫殿魏王居，瑶草琪花满玉除。","坛下馀腥犹汉代，岩头遗蜕是秦初。","客从云水求丹诀，帝遣风雷护简书。","我亦曾孙今再世，梦中亲御紫鸾车。"]},{"t":"宿冲祐观","f":"七言律诗","c":["风灯零落夜钟残，数卷玄经掩不看。","药采刀圭还玉液，火留文武养金丹。","瑶池月满鸾笙杳，石榻云深蝶梦寒。","断尽世缘须及早，肯将白发戴黄冠。"]},{"t":"宿接笋峰道院","f":"七言律诗","c":["绝壁悬厓入杳冥，丹房长借白云扃。","地分六曲成三岛，台耸千层礼七星。","暮霭晴飞岩瀑翠，秋烟寒隐石灯青。","一声独鹤醒残梦，卧听黄庭半部经。"]},{"t":"宿云窝赠陈司马","f":"七言律诗","c":["清溪九曲即蓬壶，何用遥寻五岳图。","幽壑半开新净室，秘书还看旧阴符。","鹓鸾班里多年别，鸡犬云中几日驱。","重住云窝缘不偶，前身或恐是丹枢。"]},{"t":"天游观","f":"七言律诗","c":["高台独上翠千重，吹散岚烟有铁龙。","地种三花元汉畤，门扃五粒是秦封。","云边螺髻层层结，雨后蛾眉点点浓。","倚遍危阑遥极目，九环衣带束芙蓉。"]},{"t":"宿鼓子峰道院","f":"七言律诗","c":["芒鞋历遍翠微巅，脩竹阴中别有天。","洞隐黄冠皆净侣，岩封白骨尽飞仙。","石当隙处精庐搆，路到穷时栈道悬。","夜静焚香同礼拜，步虚声散一炉烟。"]},{"t":"游水帘洞时久不雨飞沫稍微赋得一首","f":"七言律诗","c":["素练冰绡一夜收，潺湲何处见龙湫。","鲛人海底馀残泪，玉女峰前上半钩。","自有玄珠藏赤水，不须琼液咽重楼。","一瓢欲挽银河泻，倒挂青天作瀑流。"]},{"t":"寻和叔道士不遇","f":"七言律诗","c":["暂去朝元出翠微，红尘何处染绡衣。","鸾传紫府书频至，鹤带青城箭未归。","六甲风雷坛下守，半空日月鼎中飞。","石函留得龙沙谶，莫道蓬壶会面稀。"]},{"t":"武夷溪口送惟起弟度关 其一","f":"七言律诗","c":["竹杖芒鞋历翠岑，蒯缑忽动远游心。","离魂已与千峰断，别恨空如九曲深。","秪有飘蓬怀白璧，全无大药化黄金。","山中散尽宾云曲，泪落西风半夜砧。"]},{"t":"武夷溪口送惟起弟度关 其二","f":"七言律诗","c":["青山游侣散纷纷，况复临岐远送君。","两地雁鸿难顾影，一时鸾鹤总离群。","人从杜若洲边去，路在桃花洞口分。","明发登高各惆怅，鹅湖斜日幔亭云。"]},{"t":"武夷送吴元瀚还莆","f":"七言律诗","c":["日日看山住翠微，虹桥宴罢各将归。","几时再买重游棹，三载方还旧钓矶。","囊橐只携丹诀去，梦魂犹带白云飞。","别君不用绨袍赠，玉女新裁五色衣。"]},{"t":"再送元瀚次来韵","f":"七言律诗","c":["一尊同向蓼花滩，露下丹枫落叶残。","身泛孤舟愁弟远，泪挥双袖别君难。","凄凉戍角秋霜晓，明灭渔灯夜雨寒。","此去入林寻旧隐，高斋新长几琅玕。"]},{"t":"陈惟秦为其先人营葬久居永南山寄讯","f":"七言律诗","c":["春事飘零倍忆君，满庭红雨落纷纷。","鳌峰已作三秋别，马鬣新成四尺坟。","花下几回虚朗月，竹中长日赋停云。","北邙正有松楸感，乌鸟声声不可闻。"]},{"t":"访薛炼师思齐","f":"七言律诗","c":["桃花千树绕江干，花里幽居日考槃。","曲径开时供鹿卧，方书抄就借人看。","一春草绿蓬门静，半夜云生药杵寒。","闻说延年有真诀，相逢先乞九还丹。"]},{"t":"寿李司理 其一","f":"七言律诗","c":["曾将词赋冠明廷，断狱年来动引经。","德比于公高汉室，名同小陆起华亭。","寿筵犹献长生缕，海国争看执法星。","何必西岩采三秀，郡斋瑶草自青青。"]},{"t":"寿李司理 其二","f":"七言律诗","c":["鹤吹飘飖下九天，共看良吏是神仙。","朝来拄笏心如水，夏至悬弧日似年。","函谷他时生紫气，长庚此夜应青莲。","遥知卧理还多暇，注得参同有几篇。"]},{"t":"送王懋宣先生之泰顺","f":"七言律诗","c":["垂杨影里乱啼莺，朝发都亭一骑轻。","黯淡蘼芜寻去路，微茫烟树见孤城。","他乡春色悲花落，旅馆愁心寄月明。","白发萧萧犹作客，临岐分手更关情。"]},{"t":"宿邓汝高竹林山庄","f":"七言律诗","c":["群峰回合树苍苍，一径云阴散夏凉。","荒坂牛羊归暮霭，比邻鹅鸭睡斜阳。","竹当疏槛常流翠，花落清溪不断香。","晏坐山中屏尘虑，今宵如宿辋川庄。"]},{"t":"春日居法云兰若 其一","f":"七言律诗","c":["移来书舍傍琳宫，隔断红尘路不通。","游屐半閒新雨后，法幢高挂乱云中。","夜深松偃疏帘月，春尽花飞晚磬风。","谩谓空门人迹少，相寻日日有支公。"]},{"t":"春日居法云兰若 其二","f":"七言律诗","c":["登临正及看花期，青草葳蕤步屧宜。","雨翳鲸音过院冷，风传莺语出林迟。","閒寻缁锡谈三昧，偶伴黄冠礼六时。","自是山中堪避俗，更无踪迹世人知。"]},{"t":"春日居法云兰若 其三","f":"七言律诗","c":["古路苍苍入鹫峰，烟霞隔断往来踪。","时将真诀灯前课，每与游僧竹下逢。","满架瑶函藏贝叶，远林山色绚芙蓉。","闭门晏坐尘缘息，又听云堂起暮钟。"]},{"t":"春日居法云兰若 其四","f":"七言律诗","c":["满径苍苔过客稀，疏钟才动暝烟飞。","轻敲竹院残僧返，乱落松花一鹤归。","夜静石灯分佛火，春寒山罽借禅衣。","上方万籁闻俱寂，但有经声出翠微。"]},{"t":"送王少文藁葬西郊","f":"七言律诗","c":["萧萧孤榇出郊关，执绋空馀涕泪潸。","满目松楸西郭路，半天风雨北邙山。","函中白骨孤云里，世上红尘一梦间。","除却千年华表鹤，更于何处望君还。"]},{"t":"秋夜汝高振狂伯孺过宿山斋时汝高将赴阙","f":"七言律诗","c":["西风摇落正秋天，相对空山意惘然。","竹里孤灯消永夜，镜中华发感流年。","寒蛩古砌啼凉月，小犬疏林吠暝烟。","只恐心期隔霄汉，岂能长向白云眠。"]},{"t":"拟积雨辋川庄","f":"七言律诗","c":["经旬梅雨自沉沉，灌木萧森起夕阴。","泉过断桥归别涧，钟传古寺出空林。","闭门习静山中乐，晏坐焚香物外心。","终日更无车马客，时从花坞听鸣禽。"]},{"t":"拟长沙过贾谊宅 其一","f":"七言律诗","c":["怜君谪宦楚江来，门外湘波日夜回。","废井年深生乱草，古墙春尽长荒苔。","猿声似诉孤臣恨，马首空劳过客哀。","此地无须叹寥落，长安甲第亦成灰。"]},{"t":"拟长沙过贾谊宅 其二","f":"七言律诗","c":["他乡迁客恨悠悠，此日长沙宅尚留。","寂莫空梁栖鸟雀，萧条古院闭松楸。","几年宦况同云薄，一去君恩共水流。","欲采江蓠伤往事，半天风雨洞庭秋。"]},{"t":"无题 其一","f":"七言律诗","c":["数声残漏满帘霜，青鸟衔笺事渺茫。","剖赠半规苍玉玦，分将百合紫罗囊。","空传垂手尊前舞，新结愁眉镜里妆。","一枕游仙终是梦，桃花春色误刘郎。"]},{"t":"无题 其二","f":"七言律诗","c":["无缘翻悔意相关，云雨巫阳一梦间。","独抚朱弦琴哽咽，背流红泪烛潺湲。","新分半玦终难合，旧赠明珠未忍还。","纵使章台零落后，长条犹自望君攀。"]},{"t":"无题 其三","f":"七言律诗","c":["锦衾罗帐泪潸然，淡月微霜夜可怜。","啮臂尚思当日约，同心空结片时缘。","瓶沉古井浑身碎，珠孕灵渊几个圆。","一别天台成隔世，桃花流水自年年。"]},{"t":"无题 其四","f":"七言律诗","c":["一寸湘筠泪满枝，百年幽恨是幽期。","朱弦忽断鸾难续，锦字私传鸟不知。","新唾花痕沾广袖，旧分香气散重帷。","此生欲了寻春约，须及清阴未绿时。"]},{"t":"无题 其五","f":"七言律诗","c":["剑化雌雄玉匣空，寒潮东逝信谁通。","金生莲步双缠白，钏约冰肌一线红。","事去欢娱并作怨，缘乖魂梦也难同。","芳菲零乱春光晚，满地胭脂半夜风。"]},{"t":"无题 其六","f":"七言律诗","c":["兰心迷蝶柳藏鸦，绮阁银灯照九华。","百尺蓝桥通步障，几重巫峡隔窗纱。","魂销翠带胸前草，肠断青铜影里花。","落尽深红春色晚，肯容刘阮更思家。"]},{"t":"无题 其七","f":"七言律诗","c":["镜中双鬓绾如鸦，广袖新看染石华。","晓起靓妆消翠靥，昼眠香汗浸红纱。","半沟腻水堪流叶，一尺雕栏不障花。","总为多情眉黛蹙，怪他人说是西家。"]},{"t":"无题 其八","f":"七言律诗","c":["愁见流苏百结同，绣帏寒夜一边空。","几痕斑泪孤生竹，十指朱丝半死桐。","在野鸳鸯虚桃被，出山鹦鹉怨樊笼。","臂纱不解缠绵意，长护嫣红旧守宫。"]},{"t":"无题 其九","f":"七言律诗","c":["归期无定数难占，凤蜡烧残夜未厌。","几点金徽桃后谱，半边铜镜嫁时奁。","红销榴带丝空结，朱褪樱唇酒不沾。","梦醒碧纱窗外月，梅花疏影满雕檐。"]},{"t":"无题 其十","f":"七言律诗","c":["玉殒珠沉思悄然，明中流泪暗相怜。","常图蛱蝶花楼下，记刺鸳鸯绣幕前。","祗有梦魂能结雨，曾无心胆似非烟。","朱颜皓齿归黄土，脉脉空寻再世缘。"]},{"t":"烈女吟","f":"七言律诗","c":["湘水难同此恨深，幽闺长咏柏舟吟。","半生夜雨常悲鹤，六礼春风未委禽。","瑟断朱弦因废轸，烛销红泪见灰心。","寝门一诀千年怨，魂梦无由识藁砧。"]},{"t":"秋日陈汝大邓汝高陈振狂陈子卿陈幼孺袁无竞兴公弟集绿玉斋时余与子卿幼孺下第归自长安汝高将使浙中兴公将游白下","f":"七言律诗","c":["竹林文酒暂盘桓，聚散无期后会难。","灯下几人分去住，尊前双泪带悲欢。","伤心此别魂俱断，落魄初归梦未安。","他日东行占太史，客星遥傍使星看。"]},{"t":"送林观察备兵金衢","f":"七言律诗","c":["使节翩翩浙水过，东山那许久蹉跎。","一门剑履闽中少，百将櫜鞬越绝多。","露布星驰官负弩，霜台月满士横戈。","九重正尔资筹算，无暇寻仙访烂柯。"]},{"t":"赠车子仁郡侯","f":"七言律诗","c":["含来鸡舌尚氤氲，新握麟符到海濆。","案了簿书心似水，门投词赋客如云。","市中骑竹迎童子，池上挥鞭醉使君。","敝刺即今羞自献，敢言名姓旧相闻。"]},{"t":"寄谭忠卿比部","f":"七言律诗","c":["清时才子赋怀沙，抗疏归来发未华。","粉署一官淹组绶，青衫双泪怨琵琶。","杼投慈母缘忧国，环赐明君定起家。","却爱衡门当庾岭，相思不用寄梅花。"]},{"t":"送陈永奉游金陵","f":"七言律诗","c":["千里行装半醁醽，渡江君去莫教醒。","马经小小佳人墓，舟过劳劳送客亭。","扬子风高潮自白，隋堤秋尽柳无青。","后庭遗曲桓伊笛，都向秦淮月下听。"]},{"t":"寿大司马吴公 其一","f":"七言律诗","c":["班缀鹓鸾爵上公，鼎烹龙虎貌还童。","铁冠曾执三湘宪，铜柱犹存五岭功。","曳处履声为赤舄，悬来弧影是彤弓。","渭滨未许长垂钓，闻说君王正梦熊。"]},{"t":"寿大司马吴公 其二","f":"七言律诗","c":["进贤冠换七星冠，箧里阴符不再看。","上帝久颁书玉检，先皇曾赐露金盘。","白蒙头上应还黑，赤在心中已是丹。","借得方平壶十二，更于今夕献瑶坛。"]},{"t":"送薛君大秀才游武林","f":"七言律诗","c":["司马南游正少年，可堪人去雁来前。","孤舟白拥芦藏月，两岸青残柳散烟。","帆外客星滩七里，湖中佛日竺三天。","射潮不用钱王弩，但有观涛赋几篇。"]},{"t":"送邓汝高户曹督饷之浙","f":"七言律诗","c":["粉署含香又几年，转输今识酂侯贤。","还家树不言温室，行部山应访冷泉。","玉麈夜挥天竺月，画船秋放太湖烟。","江南水旱忧非细，愿悉民艰疏御前。"]},{"t":"送孙四之金陵","f":"七言律诗","c":["一时词客叹飘蓬，无数离尊半日同。","买笑好留钱子母，防身须仗剑雌雄。","鹿麋夜走三吴苑，狐兔秋悲六代宫。","建业城边堪饮水，孙郎名自起江东。"]},{"t":"古田极乐寺晓起","f":"七言律诗","c":["听尽莲华刻漏长，山深岚翠满绳床。","鸟啼松嶂声声月，僧踏枫林步步霜。","座上落花天外雨，佛前沈水定中香。","此生总是空门客，到处皈依有法王。"]},{"t":"过郑樵林山人市隐堂","f":"七言律诗","c":["一丘高卧久忘机，双屐行歌遍翠微。","纶挂夕阳春钓罢，笠携残雪晚樵归。","松窗月冷烟霞梦，菊径云生薜荔衣。","不用凿坏深避世，山城车马往来稀。"]},{"t":"丙申元日得惟起弟越中书闻王玉生客苕消息因柬钱叔达","f":"七言律诗","c":["清尊何意醉流霞，览镜空惊鬓易华。","阶下蓂开新岁叶，陇头梅寄隔年花。","人逢老去常怀旧，客到春来定忆家。","此日交游多失路，岂君踪迹独天涯。"]},{"t":"送翁兆震太史册封周藩事竣还朝","f":"七言律诗","c":["暂缀鹓班马首东，桃花色借锦袍红。","鞭挥上苑三眠柳，圭捧深宫半叶桐。","飞盖兔园歌夜雪，鸣珂燕市动春风。","汉家金匮资良史，好奏诸儒白虎通。"]},{"t":"送张宗道之金陵兼怀诸旧游","f":"七言律诗","c":["茫茫烟水片帆轻，学得陶朱变姓名。","芳草楼台歌子夜，梨花村店过清明。","莫愁湖送当年桨，瓜步江流六代声。","欲作封题还自懒，知君今去石头城。"]},{"t":"屠田叔使君枉过兼惠藏书赋谢","f":"七言律诗","c":["艺苑相闻十载馀，应知名下定无虚。","不拘世路寻常礼，还赠人间未有书。","草泽敢当高士榻，蓬门终碍使君车。","自惭巴曲非同调，空枉干旄问索居。"]},{"t":"送陈汝翔客建溪书林","f":"七言律诗","c":["垂老江湖作校书，春风长日掩衡庐。","经收坏壁驱残蠹，字出名山辨鲁鱼。","著述未忘玄晏癖，往来多是邺侯居。","不须二酉藏遗草，九曲仙都当石渠。"]},{"t":"寄题郭张虚香雪斋","f":"七言律诗","c":["高斋遥散白氤氲，历乱梅花到处闻。","一笛残魂千树雪，半窗疏影满林云。","寒生姑射仙人梦，香借孤山处士坟。","何物江南堪寄远，年年春色倍思君。"]},{"t":"郑邦衡以书见贻兼惠玉章诗扇赋此荅赠","f":"七言律诗","c":["相怜不必旧相欢，忽枉裁书问考槃。","投赠一双皆楚璧，留题五字有齐纨。","琴尊几日同花竹，魂梦中宵到木兰。","年少声名君籍甚，浅才何敢作衙官。"]},{"t":"花朝社集送佘宗汉明府之南康访杨使君","f":"七言律诗","c":["满路流莺送客轺，匡庐山色望中遥。","朱门何处堪糊口，白发逢人反折腰。","月下歌声虚竹径，天涯离恨记花朝。","知君此去经彭泽，陶令高风未寂寥。"]},{"t":"送了空禅师归长干寺是日为观音大士初度","f":"七言律诗","c":["寻声疑自普陀来，又赠杨枝海上回。","缁衲折芦初地去，白衣成果普门开。","数千里路看飞锡，五十三参送善财。","他日怀师劳远梦，栖霞兰若雨花台。"]},{"t":"分得要离冢送陈伯孺之姑苏","f":"七言律诗","c":["漆灯明灭半无光，断碣凋残字几行。","黄土一抔封马鬣，紫苔三寸锈鱼肠。","月中似听英魂泣，地下难埋侠骨香。","况与伯鸾丘垄近，烦君并为荐椒浆。"]},{"t":"再送陈伯孺兼柬在杭 其一","f":"七言律诗","c":["尊前酒尽即他乡，岂为分携始断肠。","失路客身轻似叶，倚门亲鬓白于霜。","归装不望中人产，内顾先营百日粮。","未必绨袍能解赠，临行还嘱寄衣裳。"]},{"t":"再送陈伯孺兼柬在杭 其二","f":"七言律诗","c":["天涯休用叹穷愁，得称閒心是浪游。","湖上翠蛾三竺寺，月中青雀百花洲。","囊无重载身何累，交有深知刺易投。","贫贱依人君莫愧，布衣谁不谒诸侯。"]},{"t":"送陈振狂游玉华","f":"七言律诗","c":["酒酣璚液唱游仙，万树桃花引去船。","路绕潺湲千涧水，岩开混沌五更天。","云根白积峰头雪，松火青飞洞里烟。","采药倘逢秦代客，莫言人世是何年。"]},{"t":"怀吴元瀚","f":"七言律诗","c":["总是飘零未定身，不知吴楚与燕秦。","远天夜雨孤舟冷，古道秋风一剑贫。","到处南冠羞对客，谁家西第肯留宾。","薄游只恐无归计，迹落江湖又几春。"]},{"t":"赠薛君佐秀才","f":"七言律诗","c":["年少词华旧有声，高标应比玉壶清。","一春草向池中梦，五色花从笔里生。","座满烟霞挥麈尾，匣腾风雨泣龙精。","青云自是君家业，傲世休耽白社名。"]},{"t":"寒食日陈汝大园亭看海棠","f":"七言律诗","c":["寒食东风到舞筵，海棠开遍艳阳天。","银罂杏酪香同饱，画架榴裙血并鲜。","带雨花神娇欲泣，怯寒妃子醉无眠。","夜深莫更移灯看，今日山厨未有烟。"]},{"t":"春日同叔达汝大惟秦幼孺粹夫能始兴公集无竞南郊水亭","f":"七言律诗","c":["布谷声中醉倚栏，夕阳山色隔帘看。","青团柳叶春烟薄，白散梨花暮雨寒。","燕垒泥香芳径晚，鱼梁痕浅小池乾。","只因地僻稀来往，门外低枝欲碍冠。"]},{"t":"病中试鼓山寺僧所惠新茶","f":"七言律诗","c":["偃卧山窗日正长，老僧分赠茗盈筐。","烧残榾柮偏多味，沸出松涛更觉香。","火候已周开鼎器，病魔初伏有旗枪。","隔林况听莺声好，移向荼蘼架下尝。"]},{"t":"钟山寺访张孺愿留酌话旧","f":"七言律诗","c":["客中尊酒暂淹留，共对禅灯忆旧游。","此日听莺萧寺雨，当年骑马秣陵秋。","风尘未肯容衰鬓，岁月何堪老敝裘。","独有剑锋销不尽，君家神物是吴钩。"]},{"t":"邀黄仲高张孺愿钱叔达张公鲁陈汝大陈汝翔陈惟秦王玉生陈幼孺王粹夫颜廷愉曹能始兴公弟雨中集万岁寺即席送徐仲和归钱唐","f":"七言律诗","c":["共酌醍醐送客还，晚风吹雨暗禅关。","绿波春草长途别，白社莲花半日閒。","家望雷峰烟外塔，梦回天竺月中山。","净瓶分得杨枝赠，垂柳临岐不用攀。"]},{"t":"送黄仲高之漳州","f":"七言律诗","c":["送君南去瘴云边，遥望征途路一千。","五月枫亭扶荔雨，几村茅店刺桐烟。","土音未辨难闻曲，海错常供不费钱。","少妇当垆堪买醉，时时停策酒家眠。"]},{"t":"送曹二进士之金溪吊周明府","f":"七言律诗","c":["千里分襟怅别离，西州双泪数年悲。","途中磨镜同徐稚，匣里亡琴痛子期。","楚璞谩云增价早，隋珠犹悔报恩迟。","九原未必无遗恨，不见看花上苑时。"]},{"t":"赋得广陵涛送客之维扬","f":"七言律诗","c":["万马声喧不暂停，满天风浪昼冥冥。","遥连铁瓮千层白，微露金焦两点青。","吴楚山河分一水，齐梁烟月付中泠。","伤心莫作芜城赋，好辨江干瘗鹤铭。"]},{"t":"同屠田叔张孺愿钱叔达张公鲁及社中诸子集陈正夫水亭分得文字","f":"七言律诗","c":["习池花木翠氤氲，忽枉高轩过使君。","囊里诗签拈五字，尊前乐府演双文。","杯倾竹叶春频醉，烛烬兰膏夜已分。","地主独留髡送客，犹馀丝管梦中闻。"]},{"t":"不寐感怀","f":"七言律诗","c":["杜宇啼残漏正长，满林斜月到匡床。","浮生寤寐皆成梦，旧事悲欢总可伤。","知己未亡琴废轸，雄心犹在剑销芒。","枕前二十馀年泪，半在他乡半故乡。"]},{"t":"闻伯孺由吴兴入姑苏遥有此寄","f":"七言律诗","c":["一剑飘零渡五湖，半年踪迹遍三吴。","苕溪日暮愁心远，笠泽天长客梦孤。","旧隐云深寒薜荔，他乡春尽变蘼芜。","满船载得乌程酒，曾酹要离墓上无。"]},{"t":"再怀伯孺","f":"七言律诗","c":["登楼一望意凄凄，目极遥空白练低。","匹马烟花吴苑曲，孤舟风雨太湖西。","愁中芳草迷三径，别后垂杨暗六溪。","千里怀人多感慨，每看南雁忆封题。"]},{"t":"柬程子晖","f":"七言律诗","c":["求友空歌伐木声，逢君真见古人情。","迹因避世青山近，心为忧时白发生。","倚杖暮云花径远，捲帘春雨荔阴清。","除将问道寻师外，那得庞公肯入城。"]},{"t":"七夕邓汝高民部招集玉皇阁同佘宗汉谢脩之明府邓道鸣阃帅钱叔达王粹夫山人陈汝大康元龙袁无竞秀才陈幼孺孝廉兴公舍弟赋分得五歌","f":"七言律诗","c":["高阁开尊对薜萝，风吹零露下庭柯。","三秋白帝司权早，一夕红妆乞巧多。","夜杼暂停机上锦，凉衣初试箧中罗。","少微历历干天象，不独双星夜渡河。"]},{"t":"邓道鸣阃帅招集邻霄台送邓汝高计部还朝","f":"七言律诗","c":["三叠骊歌绕翠微，凉风初动叶初飞。","尊倾大将葡萄酒，泪湿穷交薜荔衣。","自信青山盟尚在，空怜白社客全稀。","清泠台上频回首，目断燕云一雁归。"]},{"t":"八月十四日夜招张孺愿钱叔达谢脩之陈汝大王玉生袁无竞集平远台观万岁神光二塔灯分得八庚","f":"七言律诗","c":["良夜高台露气清，遥空灵籁送秋声。","桂枝先自轮中满，莲炬还从镜里生。","隐隐七层标舍利，双双百宝放光明。","龙膏烛与蟾蜍影，同向人天照化城。"]},{"t":"送张孺愿还四明","f":"七言律诗","c":["津亭歌罢酒杯空，目极遥天送断鸿。","马上夕阳孤店柳，渡头残月半林枫。","瘴云漠漠辞闽北，乡树重重辨甬东。","此日莼鲈归计得，思家张翰怯秋风。"]},{"t":"送黄仲高还四明","f":"七言律诗","c":["江头尊酒别离难，满目疏林落叶丹。","家望剡川湖一曲，车驱闽岭路千盘。","关门晓色鸡声早，旷野秋声雁影寒。","今夜梦君何处所，半天残月蓼花滩。"]},{"t":"寄邓德咸明府","f":"七言律诗","c":["一代风流墨绶郎，几年为政似庚桑。","居官共号神明宰，判事多成急就章。","滩送九龙来廨宇，庭留双鹤守琴床。","春光莫羡河阳暖，六月还飞白简霜。"]},{"t":"送陈振狂之汀州","f":"七言律诗","c":["秋色将残树影稀，故人西去雁南飞。","满林枫叶栟榈寺，两岸芦花铁石矶。","霜冷戍楼喧暮柝，月明村舍捣寒衣。","九龙溪上滩声急，千里羁魂一夜归。"]},{"t":"与吴元瀚话旧","f":"七言律诗","c":["久客还家叹敝裘，对君犹自起离愁。","数茎白发尊前泪，九曲青山梦里游。","松径夕阳秋系马，竹房疏雨午啼鸠。","明朝又作匆匆别，目断西风独倚楼。"]},{"t":"张叔麟别驾招集钟山客舍席上听伎共限冷香二字","f":"七言律诗","c":["白苧歌残欲断肠，相逢谁是有心郎。","罗帏巫峡声声雨，玉杵蓝桥夜夜霜。","烛泪半灰金剪冷，花魂初散宝钗香。","红颜自昔多憔悴，岂学愁眉别样妆。"]},{"t":"送邓道鸣参戎东粤","f":"七言律诗","c":["楼船横海发闽关，新拥高牙五岭间。","月满柳营秋校猎，火飞藤峡夜征蛮。","双龙斩水妖精泣，万马嘶风部曲閒。","名在罗浮峰四百，功成何用勒燕山。"]},{"t":"赠林敷毅公子","f":"七言律诗","c":["年少悬书向国门，家声犹说紫薇垣。","登坛久已推牛耳，授简曾看擅兔园。","拥彗诸侯虚左席，操觚词客结中原。","功名不用垂钟鼎，白首江湖亦主恩。"]},{"t":"送张参戎镇秦川","f":"七言律诗","c":["铁衣曾典羽林兵，又握铜符海上行。","此日八蛮传露布，同时诸将拜霓旌。","臂开鹊血弓流影，腰泣龙魂剑有声。","见说辕门容揖客，可能前箸借书生。"]},{"t":"送长乐令郁文叔谢病还晋陵","f":"七言律诗","c":["弃官应遂白云心，行李空携单父琴。","病骨岂堪长负弩，黑头偏乞早投簪。","家当杨柳茶烟细，门比柴桑柳色阴。","除却簿书劳半载，一生清福总山林。"]},{"t":"赠张太医","f":"七言律诗","c":["年少曾将肘后探，高名今已似苏耽。","石烹夜月松烟细，药洗春泉橘井甘。","函里难经翻九九，洞中炉火转三三。","功成他日生毛羽，看驾云车白鹿参。"]},{"t":"题芳草王孙卷为罗生挽所知","f":"七言律诗","c":["联璧当年旧有声，千秋埋玉怨难平。","邯郸久作炊粱梦，都市犹传掷果名。","肠断山阳灯下笛，魂销缑岭月中笙。","萋萋满目王孙草，岁岁春风墓上生。"]},{"t":"丙申除夕","f":"七言律诗","c":["莫问残冬历一行，且将生计寄丝簧。","烧灯客丐宜春帖，对镜人凝綵胜妆。","衰鬓又添新岁感，童心犹记少年场。","拥炉坐听莲花漏，待进山厨柏叶觞。"]},{"t":"丁酉元日","f":"七言律诗","c":["岁月悠悠独自知，屠苏饮较众人迟。","一年苦乐俱陈迹，昨日呻吟即旧诗。","才尽敢云心似锦，颜衰犹幸鬓无丝。","春风不厌衡门冷，吹遍繁花雪万枝。"]},{"t":"送彭兴祖游燕","f":"七言律诗","c":["都亭新柳折为鞭，又别闽南北向燕。","马首一星边地火，莺声三月御河烟。","吴侬枕上红楼曲，赵女垆头绿酒钱。","此日离情君莫忘，落花风雨寺门前。"]},{"t":"分得胭脂井送陈淳夫太学之金陵","f":"七言律诗","c":["胭脂零落井痕荒，水面桃花照艳妆。","碧甃一泓沉宝珥，红泉千点滴银床。","金函半染铅华色，丝绠犹牵珠翠香。","莫问故宫生死地，辘轳容易转愁肠。"]},{"t":"送陈志玄还中都","f":"七言律诗","c":["一片离心双泪垂，人归偏在送春时。","鸡声残月邮亭火，马首疏烟酒店旗。","江北琼花孤馆梦，淮南丛桂故园思。","东风吹遍无情柳，满路青青拂面丝。"]},{"t":"送黄君甫还剑津","f":"七言律诗","c":["故园归去独扬舲，踯躅花残落远汀。","鹦武春衔杯里月，蛟龙宵睨剑头星。","滩回巨浪千层白，门对高峰九点青。","莫道盈盈分一水，相思魂断几长亭。"]},{"t":"分得宫花一万树送曹能始进士赴阙","f":"七言律诗","c":["芳菲丛里拜枫宸，铃索声中雨露新。","香雾有时分太极，秾华随处拂勾陈。","重重绿染宫袍色，片片红酣御辇尘。","不似曲江骑马日，杏林惟探一枝春。"]},{"t":"分得季子裘送钱叔达归吴兴","f":"七言律诗","c":["旅邸淹留历几春，黑貂无复到来新。","蒙茸莫问千金腋，褴褛翻疑百结鹑。","失路易沾函谷雨，还家犹染洛阳尘。","布衣落魄惭妻嫂，应悔当年浪入秦。"]},{"t":"题黄伯宠秀才欧冶山房","f":"七言律诗","c":["疏松影里草玄亭，屋后群峰列翠屏。","残雨小塘萍散绿，微风幽径竹摇青。","觞寻曲水流三月，剑拔寒潭洗七星。","寂寂衡门无客到，林莺啼午梦初醒。"]},{"t":"夏日邀屠田叔使君佘宗汉明府闵寿卿柳陈父王献子钱叔达吴元瀚诸山人颜廷愉都护兴公舍弟避暑平远堂分得一先韵","f":"七言律诗","c":["借得琳宫结净缘，数声钟磬出诸天。","龙江潮满千溪合，雉堞云开万井连。","瀑布乱飞丹嶂雨，山衣同历翠微烟。","莫言座上无丝竹，花外啼莺柳外蝉。"]},{"t":"寿车郡公","f":"七言律诗","c":["铜虎分来向海滨，玉皇香案记前身。","采将瑶草三山秀，种得甘棠一郡春。","天上紫鸾扶绛节，云中白鹿驾朱轮。","寿筵不用蟠桃荐，丹荔冰盘色正新。"]},{"t":"题周朝寀转运三代荣封册","f":"七言律诗","c":["出宰河阳旧有声，司农今复借双旌。","转输岁向三边急，斥卤烟从万灶生。","紫禁丝纶荣马鬣，熙朝冠盖擅羊城。","一门雨露皆君宠，不独云霄两弟兄。"]},{"t":"送林志尹谒选之京时予将入燕","f":"七言律诗","c":["数声南雁叫秋烟，路指交河北到天。","鸡送边城霜后角，马惊沙碛雪中鞭。","贫来远道亲雄剑，老去长安索俸钱。","我已藏名燕市久，相寻休向酒垆前。"]},{"t":"送闵寿卿从武夷还金山兼隐华阳洞","f":"七言律诗","c":["历遍清溪九曲深，麻衣随意住云林。","阴符一卷蛟龙护，秋笛数声猿鹤吟。","玉洞烟霞通地肺，金山台殿影波心。","空怀五岳平生志，未得从君学向禽。"]},{"t":"送陈宪伯入觐便道归省","f":"七言律诗","c":["万国诸侯会建章，使君千骑出东方。","绣衣正奏三年绩，綵服还称百岁觞。","辔揽朱轮宵拥月，疏封白简昼飞霜。","法星渐与闽天远，遥望精光帝座傍。"]},{"t":"送闵孝昭侍尊人还广陵","f":"七言律诗","c":["暂得相逢又解携，滩声高下桨声齐。","束装欲跨扬州鹤，问寝频听旅店鸡。","夜月故园淮浦北，秋云乡路海门西。","还期共醉芜城酒，系马隋宫旧柳堤。"]},{"t":"送温永叔郡丞守南宁","f":"古风","c":["符分铜虎寄专城，新驾朱轮岭表行。","八桂瘴云迎五马，二江岚月引双旌。","禁将巫蛊蛮丁化，燃出灵犀?母惊。","地近交州风土别，每逢春雨劝刀耕。"]},{"t":"送邓德咸刺史官沔阳","f":"七言律诗","c":["楚江猿啸岂堪听，野水连天过洞庭。","夜月褰帷逢汉女，秋风行部吊湘灵。","九疑峰色参差碧，三峡云光黯淡青。","君去不愁难寄远，萧萧兰芷满寒汀。"]},{"t":"题黄懋中大学士硕宽堂","f":"七言律诗","c":["多年簪笔侍螭头，焚却银鱼早乞休。","十亩云霞开径日，半楼烟雨捲帘秋。","小山桂树丛丛绿，曲涧桃花片片流。","不是能耽泉石趣，几人青鬓老菟裘。"]},{"t":"留别陈叔度","f":"七言律诗","c":["几日相逢意未阑，谁知相别不成欢。","尊前草色销魂易，笛里梅花寄远难。","鸡唱晓霜孤枕怯，马嘶残雪一鞭寒。","虽然千里同明月，两地伤心各自看。"]},{"t":"除夕前二日同康元龙集江参藩先生园亭","f":"七言律诗","c":["停骖岁晚向名园，满径寒花映酒尊。","雪色半侵青玉案，星光多傍紫薇垣。","几年愧下高人榻，一剑长衔国士恩。","不是残年催去客，敢辞十日饮平原。"]},{"t":"武林驿别康元龙","f":"七言律诗","c":["钱唐江上浪层层，此地分携感慨增。","客路残年悲短剑，驿亭寒夜忆孤灯。","归魂黑度千林雨，乡泪红凝半枕冰。","江北江南天万里，不堪回首望西陵。"]},{"t":"语溪舟中除夕用旧韵","f":"七言律诗","c":["满江灯火照帆樯，断送韶华在异乡。","红烛也流今夕泪，青铜犹忆去年妆。","孤身长路思千里，半世虚名梦几场。","欲解离愁谋一醉，行厨何处有椒觞。"]},{"t":"除夕西寺访朗公","f":"七言律诗","c":["停棹清溪值岁除，匆匆溪上访僧居。","残年只听莲花漏，半偈犹翻贝叶书。","爆竹声喧人语沸，石灯光照佛堂虚。","五噫悔作飘零客，愿得从师證六如。"]},{"t":"戊戌元日槜李舟中","f":"七言律诗","c":["千里关河更问津，东风吹动柳条新。","鸡声不挽难留岁，马齿偏催易老身。","楼上绮罗谁氏女，帆前箫鼓异乡人。","客心久已如荼苦，何用盘中荐五辛。"]},{"t":"曾人倩秘书招饮衙斋话旧分得昏字","f":"七言律诗","c":["悠悠往事不堪论，燕市悲歌欲断魂。","折柳岂忘逢驿路，颂椒还记醉祗园。","千金橐尽心犹壮，一剑锋销侠尚存。","酒后对君思起舞，浮云西北易黄昏。"]},{"t":"寄怀陈伯孺","f":"七言律诗","c":["六溪疏柳几条斜，不异柴桑处士家。","日午山窗书薤叶，春深江阁画梅花。","邻庄与弟同渔猎，古寺寻僧共结跏。","独有故人伤远别，年年衰鬓客京华。"]},{"t":"纪事 其一","f":"七言律诗","c":["汉家台殿敞蓬莱，玉柱盘龙接上台。","廿载皇仁深雨露，一时天意变风雷。","宫墙夜静啼乌急，苑树春归乳燕来。","翘首五云天万里，小臣双泪泣秦灰。"]},{"t":"纪事 其二","f":"七言律诗","c":["纷纷兵甲满中原，市井萧条有几村。","总为琼林伤地脉，非贪宝气凿云根。","中涓数献便宜策，丁壮难招恸哭魂。","辛苦西台姚柱史，画图空自叩天阍。"]},{"t":"纪事 其三","f":"七言律诗","c":["王师一夜报苍黄，大将星沉昼不光。","塞外忠魂酬玉剑，沙中枯骨带金疮。","黄昏燐火新亡卒，白日烽烟古战场。","莫向居庸城上望，霜天笳管总悲凉。"]},{"t":"纪事 其四","f":"七言律诗","c":["欃枪夜望射天弧，边计年来困挽输。","万里君门谁伏阙，四郊皇店尽徵租。","虎贲宿将多凋谢，乌合新兵屡噪呼。","时事艰危堪涕泪，太平能到白头无。"]},{"t":"得王元直金陵书却寄","f":"七言律诗","c":["芳草天涯怨不胜，怀人魂梦苦无凭。","何来一骑过淮水，传得双鱼自秣陵。","桃叶暖风春访伎，杏花微雨夜寻僧。","玉蝉精舍葳蕤锁，寂寞疏林半点灯。"]},{"t":"赠王思延都护","f":"七言律诗","c":["年少登坛拥隼旟，欲将长剑扫穹庐。","黄金世佩通侯印，彤管家藏太史书。","异域葡萄杯上绿，边城杨柳笛中疏。","运筹自合阴符秘，兵法无劳习穰苴。"]},{"t":"赠王君密民部","f":"七言律诗","c":["年少风流粉署郎，赋成争诵鲁灵光。","閒曹不废青箱业，先世犹传白简霜。","九折羊肠曾叱驭，一官鸡舌正含香。","潞河公暇门如水，花竹阴阴客满堂。"]},{"t":"潞河逢梅子马时子马自楚使燕","f":"七言律诗","c":["当年同听白门鸦，别后风烟几岁华。","万里飘零逢潞水，一官牢落傍长沙。","新愁绿岸帆前柳，旧事青楼梦里花。","草草离尊犹未醉，数声残角又天涯。"]},{"t":"天津道中怀王玉生","f":"七言律诗","c":["老向郊原受一廛，村中幽事总堪怜。","园栽桑柘同韦曲，坞筑辛夷学辋川。","花下笔床临粉本，松间茶鼎扇青烟。","自从南北风尘远，不到东山又几年。"]},{"t":"连窝舟中与张叔韬话旧","f":"七言律诗","c":["同泛归舟下潞河，空将身世感蹉跎。","十年京洛红尘满，三载朱崖白发多。","云暗戍楼喧断角，月残官渡起悲歌。","愁君此去王程急，两岸芦花奈别何。"]},{"t":"淮阴舟夜寄怀二云歌姬","f":"七言律诗","c":["淮浦东边月影斜，相思何处问琵琶。","别时折是章台柳，梦里歌为玉树花。","万里客魂销绿鬓，几回幽恨寄红牙。","遥知香骨怀人瘦，宽尽春风系臂纱。"]},{"t":"广陵七夕闻歌有怀","f":"七言律诗","c":["每看秋水忆临波，况值天孙夜渡河。","衣上馀香怀贾女，竹间残泪怨湘娥。","书从蓟北传来少，梦到江南别后多。","二十四桥桥畔月，不堪重听绕梁歌。"]},{"t":"真州逢谢在杭司理","f":"七言律诗","c":["萧萧书剑傍风尘，况对天涯骨肉亲。","半夜断猿知己泪，经年羸马异乡身。","飘零湖海愁归客，憔悴江潭问逐臣。","此日世途君自见，莫将青鬓叹沉沦。"]},{"t":"舟次枫桥寄陈汝大先生","f":"七言律诗","c":["萧萧羸马厌驰驱，愁听枫桥月落乌。","开遍芙蓉思故国，折来杨柳记西湖。","十年献赋青云薄，千里题诗白社孤。","我为飘零双鬓短，忆君霜雪满头颅。"]},{"t":"怀李仪卿","f":"七言律诗","c":["梅花绡帐晓寒生，怨似流苏百结成。","远岫犹怜眉黛浅，凌波还忆袜罗轻。","倦来司马偏多病，老去徐娘更有情。","十载旧欢真一梦，钓龙台上月空明。"]},{"t":"驿亭夜坐书怀寄内","f":"七言律诗","c":["十年书剑两无成，飘泊江湖愧姓名。","络纬声沉愁易集，芙蓉花老怨难平。","枕边暮雨离魂结，镜里秋霜客路生。","共隐青山期白首，古来曾有鹿门耕。"]},{"t":"赠沈稚咸","f":"七言律诗","c":["爱君蓬荜绿萝閒，住近枫桥第几湾。","短屐一春游茂苑，疏钟半夜听寒山。","门多词客寻诗至，寺有高僧乞画还。","数顷烟波满船月，歌声来往水云间。"]},{"t":"过沈从先江居","f":"七言律诗","c":["停棹来寻江上居，闭门知与世情疏。","买鱼入市儿沽酒，负米还家母倚闾。","委巷几留高士辙，寒窗长课小童书。","空怜四壁萧条甚，薄俗何人重子虚。"]},{"t":"垂虹夜泊怀陈幼孺","f":"七言律诗","c":["吴江残露冷丹枫，万里还家叹转蓬。","世路升沉同塞马，乡书寥落怨边鸿。","舟移晚渡三更月，桥跨秋波百丈虹。","犹忆当年分别处，征衣憔悴泣西风。"]},{"t":"姑苏怀郑翰卿","f":"七言律诗","c":["十年踪迹遍天涯，散尽黄金满狭斜。","庄舄岂能忘越国，莫愁原自属卢家。","孤莺白岳啼衰柳，匹马青楼过落花。","日暮思君心独远，片帆江上阻蒹葭。"]},{"t":"送张叔韬令罗浮","f":"七言律诗","c":["琼海曾乘博望槎，惠阳为政又携家。","琴床半落姑仙雪，印匣全封葛令砂。","输税山农冠箬叶，趁墟蛮女卖梅花。","官閒好作罗浮长，四百峰中早放衙。"]},{"t":"秋日访徐茂吴司理","f":"七言律诗","c":["青鬓投簪二十年，菟裘高筑虎林偏。","胸吞云梦全无楚，屋贮华阳小有天。","杨柳影侵游寺屐，竹枝歌送泛湖船。","钱唐江上潮如马，定赋观涛第几篇。"]},{"t":"西湖秋夜寄紫玉侍儿","f":"七言律诗","c":["他乡流落怨归期，天外秋风雁去迟。","枕上雨声灯下泪，湖心山色镜中眉。","难将双楫迎桃叶，愁听孤舟唱竹枝。","遥忆琐窗肠断处，残更哀角梦回时。"]},{"t":"钱唐感旧","f":"七言律诗","c":["吴山残黛晚烟低，满目桃花路又迷。","夜夜泪痕悲角枕，年年幽恨闭香闺。","分枝菡萏难连理，隔水鸳鸯暂并栖。","司马琴心今渐老，断肠明月小楼西。"]},{"t":"七里滩怀惟秦","f":"七言律诗","c":["桐江风冷露华漙，舟过严陵七里滩。","秋晚雁声枫外老，夜深渔火蓼边残。","月明古渡波千顷，云暗高峰路几盘。","遥忆故人沧海上，白头犹自守纶竿。"]},{"t":"过武夷访闵寿卿蘧庐一宿而别兼柬浑然道人江仲鱼秀才","f":"七言律诗","c":["蘧庐高结傍岩峦，翠壁千重路几湾。","霞色全飞丹灶火，溪声长绕白云关。","风尘已作经年别，烟水聊分一夜閒。","唱罢金鸡天欲晓，渔郎踪迹又人间。"]},{"t":"闻屠田叔转运擢守辰州寄赠","f":"七言律诗","c":["新驾朱轮驿路赊，甘棠初种郡庭花。","三苗纳款沅陵地，五马行春楚水涯。","酉室名山探绿字，辰溪深洞觅丹砂。","桃川正属提封内，试问秦人尚几家。"]},{"t":"送陈汝翔游惠州","f":"七言律诗","c":["马蹄随处认桄榔，千里孤身入瘴乡。","岭路春声啼翡翠，蛮村秋色变蕉黄。","朝云香骨累累土，夜月花神淡淡妆。","莫向异方思故国，夏初先得荔枝尝。"]},{"t":"为屠田叔悼亡姬 其一","f":"七言律诗","c":["渺渺凌波去绝踪，每看遗挂恨重重。","魂同睡蝶招难返，血比啼鹃拭更浓。","黄土有情封玉骨，青铜无计铸花容。","君行正近高唐路，肠断巫阳第几峰。"]},{"t":"为屠田叔悼亡姬 其二","f":"七言律诗","c":["一别妆楼闭寝门，梨花风雨泣黄昏。","蚌枯沧海珠无泪，鱼葬青山玉不温。","金谷尚传三斛价，罗帏空负十年恩。","春来忍看孤飞燕，恐是娇姬恋主魂。"]},{"t":"自题小像 其一","f":"七言律诗","c":["平生非侠亦非儒，半世游閒七尺躯。","却为疏狂因偃蹇，未忘柔曼转清癯。","违时傲骨贫犹长，对客诗肠老渐枯。","五字吟成心独苦，不知身后得传无。"]},{"t":"自题小像 其二","f":"七言律诗","c":["展卷徒为老大悲，形容将槁鬓将丝。","有时愤世空饶舌，何处谈诗不解颐。","足为无车行路健，心因多累记书迟。","自知瘦骨宜贫贱，莫怨人间只相皮。"]},{"t":"寄怀李惟顺赞府","f":"七言律诗","c":["岩邑萧条早闭关，翠屏高映讼庭间。","官同潘县栽花至，客到龙门御李还。","衙听孤莺声共放，吏兼双鹤影俱閒。","琴床一曲停流水，又对青娥画远山。"]},{"t":"林子真久客临汀闻余归自长安贻书慰藉感而赋荅","f":"七言律诗","c":["经年离思杳难裁，望断江南雪后梅。","锦字忽传孤雁至，明珠惊向九龙来。","雄心已耗刘蕡第，死骨谁收郭隗台。","总为穷愁才易尽，岂堪重问笔花开。"]},{"t":"送屠使君至芋江是夕留饮驿亭以梨园佐觞使君首倡依韵奉荅","f":"七言律诗","c":["追欢三载别今朝，对酒离魂黯欲消。","楚国行春迎露冕，邮亭卜夜驻星轺。","残鸡唱断风生柝，万马声寒月送潮。","暂歇梨园留刻烛，莫教红蜡一时烧。"]},{"t":"渊关再别屠使君次来韵 其一","f":"七言律诗","c":["使君才藻似枚皋，立得词坛赤帜高。","薄俸半因开社费，閒心多为著书劳。","年来淮桂歌招隐，此去湘兰赋反骚。","五马骖驔人独远，楚天遥望首空搔。"]},{"t":"渊关再别屠使君次来韵 其二","f":"七言律诗","c":["万里沅陵楚水隈，一麾今出越王台。","当筵客尽留诗别，卧辙人多掩泪回。","津汎神龙悲剑去，峰过回雁望书裁。","九疑渐近三山远，何处登临屐再陪。"]},{"t":"崇德令孙先生挽诗","f":"七言律诗","c":["语溪为政号神君，黑发俄脩地下文。","远道野僧歌薤露，寒宵山鬼哭松云。","斗间久失郎官宿，郭外新添令尹坟。","忽听悲风生垄树，犹疑长啸半空闻。"]},{"t":"云阳葛隐君双寿诗","f":"七言律诗","c":["句容元说葛洪家，配得仙姬萼绿华。","几度化龙陂上竹，寻常喂鹤鼎中砂。","笙吹缑岭声声月，衣剪茅山片片霞。","待到丹成同拔宅，遥空双驾紫鸾车。"]},{"t":"戊戌除夕 其一","f":"七言律诗","c":["独对残灯暗自惊，世途谁复念虚名。","索钱有虏诗难退，祀灶无灵术未精。","半壁图书先代业，四邻歌管少年情。","二毛岂必缘衰老，只恐穷愁白易生。"]},{"t":"戊戌除夕 其二","f":"七言律诗","c":["办得椒盘橐已虚，残年衣褐叹全无。","先人墨绶空廉吏，贱子青衫只腐儒。","自祭诗神斟柏叶，欲驱穷鬼挂桃符。","灯前不改贫家乐，堂上慈颜膝下雏。"]},{"t":"己亥元日 其一","f":"七言律诗","c":["开遍梅花腊尽归，声声爆竹启山扉。","去年愁苦将谁告，今岁平安向佛祈。","三径烟霞吾独老，六街风雨客来稀。","朱门通刺慵随例，自古閒身是布衣。"]},{"t":"己亥元日 其二","f":"七言律诗","c":["灯烛烧残见曙光，伤情多为惜年芳。","无田更切三时望，有闰翻添一月忙。","已分狂歌惟草泽，喜占春梦在池塘。","生憎稚子吹芦管，落尽梅花树树香。"]},{"t":"同幼孺惟起由琼河泛舟至义溪","f":"七言律诗","c":["寒风微雨共扬舲，无数渔歌竹外听。","浦口小洲悬半月，海门孤塔涌罗星。","洪涛敛势奔归峡，众水分流散入汀。","三十六湾溪路转，一湾山色一重青。"]},{"t":"送林道鲁就婚之楚妇翁王献父时为吉藩左相","f":"七言律诗","c":["二月春风咏摽梅，征衣还见锦初裁。","舟经剑浦乘龙去，路入衡阳捧雁来。","卺合贤王新赐醴，镜开神女旧妆台。","兔园正授枚生简，年少谁当作赋才。"]},{"t":"山居漫兴学晚唐","f":"七言律诗","c":["野服黄冠绝世情，小斋无客罢逢迎。","蜂窠衙静如山县，蚁穴泥深似土城。","雨久芭蕉心半捲，春迟杨柳眼初生。","只缘编得花屏好，每日沿阶几度行。"]},{"t":"送朝宗上人还金山","f":"七言律诗","c":["天涯行脚偶相逢，又向空门忆旧松。","千里月嘶春涧马，半江云起晓堂龙。","临流独浣归山衲，礼佛重鸣到寺钟。","闻说慈航堪度世，几时禅榻待周颙。"]},{"t":"送陈道育之官汉阳","f":"七言律诗","c":["万里传经入楚乡，新莺初啭柳丝长。","毡存子敬官非冷，舆御潘郎母可将。","山色千重看大别，江流九派过浔阳。","座间定有三鳣坠，地近嘉鱼对武昌。"]},{"t":"赠呼允龄将军","f":"七言律诗","c":["黄金横带气如虹，儒雅还看郤縠同。","鱼鸟阵开云变黑，鲸鲵血溅海生红。","肘悬幕府新雕印，手挂天山旧赐弓。","注就阴符刁斗急，夜深灯照柳营中。"]},{"t":"钱连江尊人双寿诗","f":"七言律诗","c":["宿应郎官接上台，岁星还傍婺星开。","丹烧勾漏霞干片，酒进麻姑露一杯。","琪草祗从阶下长，蟠桃都向县中栽。","承家自有关门尹，日日真人紫气来。"]},{"t":"送苏明府擢南计曹","f":"七言律诗","c":["鸡舌新含入旧都，几时闽海更还珠。","中牟理邑方驯雉，南部趋朝好听乌。","百里歌犹传蔽芾，一官清不愧莱芜。","度支若上筹边策，愿赐江南一半租。"]},{"t":"送张宗道之白下","f":"七言律诗","c":["春风频听白门鸦，匹马骄嘶踏杏花。","匣贮丰城埋后剑，帆开博望泛时槎。","梁间玳瑁寻卢女，井角胭脂吊丽华。","夜泊秦淮重买醉，隔江依旧月笼沙。"]},{"t":"金山持心上人以造塔募缘入闽喜而有赠","f":"七言律诗","c":["锡杖年来遍五湖，津梁随处度凡夫。","宝沉汉水思庞蕴，金布祗园问给孤。","七级月中光舍利，诸天云里涌浮图。","当时玉带今何所，犹自逢人说大苏。"]},{"t":"上杨叔向参知","f":"七言律诗","c":["清朝骚雅见遗音，爱士常怀倒屣心。","太史文章高倚马，右军书法得来禽。","家饶美竹堪为箭，爨有焦桐解辨琴。","行部时时过剑水，匣中风雨作龙吟。"]},{"t":"赠陆延平","f":"七言律诗","c":["高卧东山岁月深，南来五马又骎骎。","民淳市卖雷生剑，官久囊空陆贾金。","频见弓旌求草泽，常看车驾舍棠阴。","玉华有石还堪载，不愧君家旧郁林。"]},{"t":"延津逢许然明还武林诗以送之","f":"七言律诗","c":["相逢同是客中身，双剑延津合有神。","满树流莺啼去路，千山羸马送归人。","梨关月冷他乡梦，柳浪烟深故里春。","订得西湖湖上约，六桥何处问垂纶。"]},{"t":"送陈二表兄重游高州兼柬诸旧好","f":"七言律诗","c":["灯前愁赋渭城歌，瘴雨蛮烟万里歌。","市得好香沉水贵，劈来新荔火山多。","古祠重拜高凉洗，遗殿还寻粤尉陀。","往事悠悠三十载，旧游双鬓几人皤。"]},{"t":"送陈惟秦客恩州 其一","f":"七言律诗","c":["客枕愁听五岭猿，瘴江何处不消魂。","羊城月送春潮上，蚬水风催夜渡喧。","茉莉卖钱香满市，芭蕉成布绿连村。","明知此去蛮乡恶，无奈飘零别故园。"]},{"t":"送陈惟秦客恩州 其二","f":"七言律诗","c":["树树桐花夹路开，思乡还上粤王台。","裹盐峒客投墟去，沽酒蛮姬泛艇来。","市肆尽传鸡骨卜，垣墙多杂蛎房灰。","送君解说炎方俗，二十年前此地回。"]},{"t":"送邵武李太守擢宪滇南","f":"七言律诗","c":["昆明池水静无波，拥传新从僰道过。","开府定能宽汉法，采诗曾不废蛮歌。","趁墟滇客龙名市，纳款夷王象渡河。","他日勒功留片碣，点苍如黛石嵯峨。"]},{"t":"约陈伯孺仁王寺结夏效长庆","f":"七言律诗","c":["诗寄湾溪老友看，今年结夏择香坛。","约翻莲藏日三卷，愿饱花斋午一餐。","经月应酬抛竹素，暂时功课借蒲团。","更贪两物堪消暑，栲栳阴浓荔子丹。"]},{"t":"约薛晦叔仁王寺结夏诗以代柬","f":"七言律诗","c":["古寺幽偏少四邻，树阴苍翠石嶙峋。","暂抛火宅尘中累，同结香坛世外因。","下界难寻消暑地，平交谁是得閒身。","寄诗已约湾溪叟，清赏于君又一人。"]},{"t":"夏日园居和兴公韵 其一","f":"七言律诗","c":["荒园四面绿阴齐，菜甲纵横剩几畦。","络架瓜藤青不断，亚檐柽叶翠难低。","石堪清听敲灵壁，茶可消烦煮建溪。","坐对博山香渐灭，数声归鸟过窗西。"]},{"t":"夏日园居和兴公韵 其二","f":"七言律诗","c":["一条邛杖绕疏篱，正是閒行得句时。","缚帚竹寻将槁叶，插瓶花爱半开枝。","多情乳燕梁间垒，无意蜘蛛屋角丝。","树影临窗遮欲尽，昼长真与睡相宜。"]},{"t":"蔡景明参知重游晋安过访山居话旧时先永宁殁已九载尚辱垂吊感而赋此","f":"七言律诗","c":["垂老閒游出瘴乡，居停仍喜近山房。","昔年图画虫生卷，故主园林燕在梁。","眼底更谁为旧雨，鬓边无处不新霜。","感君犹有山河意，追念先人拜影堂。"]},{"t":"赵仁甫别驾解官归自夔府招同陈履吉陈平夫陈振狂集侣云堂","f":"七言律诗","c":["草堂新筑白云间，招得荷衣客往还。","北海芳尊倾鲁酒，西窗残烛话巴山。","林花乍落三开径，园柳初成五映关。","莲社正稀泉石侣，爱君青鬓肯投閒。"]},{"t":"送善上人募建水月庵","f":"七言律诗","c":["托钵他乡度有情，逢人稽首乞题名。","行行水际袈裟影，处处空中剪尺声。","募化不辞孤锡远，因缘休谓一钱轻。","凭师悟取西来意，水自澄清月自明。"]},{"t":"施仲宣司理招同邓汝高督学饮乌石山分得虚字","f":"七言律诗","c":["道山千尺本仙居，上有孤亭接太虚。","坐倚松篁频却盖，行过岩岫久停车。","洞疑大酉鸿濛外，石似天丁斧凿馀。","不是能忘轩冕贵，岂容踪迹混樵渔。"]},{"t":"过黄印坤广文故居","f":"七言律诗","c":["重过闾巷景萧然，蔓草疏花感昔年。","白社犹悬高士榻，青山新筑广文阡。","墨池久涸苔生砚，玄室长扃土翳毡。","唯有寒塘如半月，绿波依旧绕门前。"]},{"t":"赠林子实山人","f":"七言律诗","c":["破帽鹑衣过此生，放歌村落负薪行。","何人能识醉中趣，独我许留身后名。","老去未容狂态减，贫来弥觉俗缘轻。","茅茨委巷逢迎少，经岁不闻车马声。"]},{"t":"登玉皇阁","f":"五言古诗","c":["杰阁开灵境，瑶坛接太空。","层甍青嶂里，飞槛白云中。","海上蓬莱岛，人间太乙宫。","六鳌峰逶逦，五虎势巃嵷。","渐与尘寰隔，还于帝座通。","天都低日月，地轴隘华嵩。","远眺龙台古，回看雉堞雄。","阶生瑶草绿，炉伏大丹红。","妙诀传金母，高幡捧玉童。","骖鸾逢子晋，骑鹿揖韩终。","自识玄关妙，因知道教崇。","九仙遗迹在，何必访崆峒。"]},{"t":"初夏集王氏南园","f":"五言古诗","c":["南园开胜地，结伴共盘桓。","曲径依精舍，疏钟出戒坛。","山光低古堞，树色隐层峦。","弱柳垂青沼，名花映画栏。","浮屠高七级，悬磴折干盘。","帆影云中细，蝉声雨后残。","侵衣松露湿，夹座竹阴寒。","铃铎凭虚听，川原入望看。","明霞散林际，初月挂檐端。","啸咏情方洽，酣歌夜未阑。","此中足幽赏，长愿接清欢。"]},{"t":"游方广岩登绝顶二十四韵","f":"五言古诗","c":["方广华严地，神州一洞天。","寺藏青嶂里，路绕白云边。","气候晴兼雨，峰峦断复连。","树枝多臃肿，萝磴自盘旋。","猿啸听经石，龙生洗钵泉。","水帘终古泻，钟乳半空悬。","境出尘寰外，岩开混沌前。","金身馀五百，世界度三千。","净室邻飞瀑，沙弥种石田。","空门灰几劫，削壁字何年。","谷有羚羊险，山从鸟道缘。","地偏堪避世，境寂可安禅。","贝叶飘香界，昙花落法筵。","桑门同客馔，石榻伴僧眠。","已得澄心诀，浑忘俗累牵。","探奇情未已，跻险兴翩然。","披莽寻支径，扪萝到上巅。","畏途尤巀嶪，侧足更迍邅。","彳亍声俱喘，蹒跚膝在肩。","耸身摩斗柄，回睇盼云烟。","远水看如带，重冈小似拳。","祗疑天阙近，还听谷声传。","客有玄晖趣，僧如支遁贤。","从兹寻觉路，长此奉金仙。"]},{"t":"登石竹山","f":"五言古诗","c":["一径费攀跻，群峰觉尽低。","千层环碧嶂，百级挂丹梯。","岭峻天疑近，林深路转迷。","空中飞鸟绝，树杪乱猿啼。","跳浪山魈避，盘旋羽客栖。","解衣穿草莽，挥手抉虹霓。","岁久碑无字，丹成灶有泥。","书符寻篆箓，炼药乞刀圭。","吟眺情俱适，徘徊日渐西。","扶筇下山去，月色印前溪。"]},{"t":"登万岁塔","f":"五言古诗","c":["宝塔凌霄迥，登攀俯九垓。","山河天际绕，楼阁日边开。","幡影依檐落，铃声拂槛来。","马江波浩渺，雉堞势萦回。","隔岭留残照，遥空度晚雷。","炊烟生下土，禅诵出香台。","僧自山腰住，人从树杪回。","迷川今日渡，劫火往年灰。","上界疏钟动，孤城断角催。","几思题偈别，古壁半苍苔。"]},{"t":"游榴花洞","f":"古风","c":["逶逦群峰隐，纡回一径偏。","空山残照里，古路断云边。","入壑疑无地，穿林觉有天。","鹿眠松下坞，禽噪竹间泉。","芝草缘冈秀，榴花满洞然。","莓苔寒细雨，桑柘隔孤烟。","但见山川旧，谁知陵谷迁。","人皆迷汉姓，居是避秦年。","不记来时路，因?世上缘。","迟回未忍去，或恐过神仙。"]},{"t":"己丑除夕志喜","f":"五言古诗","c":["一岁尽今夕，悲欣异去年。","梅花送残腊，莲炬吐芳烟。","淑气回蓂荚，条风度管弦。","老亲欢膝下，稚子戏灯前。","柏酒山妻进，辛盘诸弟传。","天伦有真乐，喜极不能眠。"]},{"t":"箕踞轩赠郭圣仆","f":"五言古诗","c":["大隐不违亲，幽居少四邻。","跏趺依古佛，箕踞对时人。","习懒成迂癖，长斋了夙因。","形骸耽句瘦，囊橐积书贫。","薜荔裁奇服，耕桑作外臣。","柴门多紫气，木榻绝红尘。","谊以枌榆笃，交于草莽真。","愧予贪问字，忘却往来频。"]},{"t":"瓦棺寺看月同吴翁晋梅季豹郭圣仆志若真全二上人分得圆字","f":"五言古诗","c":["问偈过诸天，松间片月悬。","光分三世火，影灭半林烟。","云驶看疑运，霜明望更鲜。","玉绳低下土，金镜照迷川。","悟景应知幻，标枝可喻禅。","籁兼心共寂，轮与果俱圆。","散彩高幡外，生辉断磬边。","晓钟催渐落，长夜竟忘眠。"]},{"t":"苕溪逢谢长史姊丈携家适至赋此志喜且以为别","f":"五言古诗","c":["不谓飘零客，能逢骨肉亲。","乍同灯下语，犹讶梦中身。","意绪兼悲喜，关河各苦辛。","音初闻里闬，事但话乡邻。","细问儿童长，空怜弟妹贫。","艰危前路甚，消息故园真。","虽得欢携乐，其如别泪新。","明朝又分手，两地共伤神。"]},{"t":"四月晦日邀屠田叔钱叔达陈彦宗陈汝翔王玉生陈惟秦陈幼孺王粹夫陈正夫曹能始林子真兴公弟西湖观竞渡分得寒字","f":"五言古诗","c":["高阁俯澄澜，湖光入座看。","遥空箫管咽，夹水绮罗寒。","笑语连天沸，呼声动地欢。","扬旌过曲浦，挝鼓下惊湍。","翠袖飘文楫，红标飐画栏。","卧波苍甲偃，回棹玉鳞蟠。","共听菱歌度，浑忘蓂叶残。","土风争不禁，礼法醉犹宽。","藉草情偏洽，迷花兴未阑。","日斜游骑散，坠珥满江干。"]},{"t":"送李德威先生之樵川寻珠上人","f":"五言古诗","c":["何以度晨昏，萧然四壁存。","缁衣怜旧主，白发傍空门。","业净依菩萨，家贫任子孙。","馀生抛不顾，老泪滴无痕。","世事空花过，愁心落叶繁。","愿将香积供，千里劝加餐。"]},{"t":"怨歌行","f":"五言古诗","c":["恨极蛾眉蹙，情多雁素沉。","银灯孤照影，锦荐独伤心。","粉褪双颧玉，黄销半臂金。","解衣香气冷，揽镜泪痕深。","蛩韵鸣残杼，蛛丝网断琴。","罗帷明月鉴，珠被晓霜侵。","愿托巫山梦，为君长抱衾。"]},{"t":"送屠田叔之官沅陵五十韵","f":"五言古诗","c":["爵服诸侯列，声华一代先。","英灵钟岳秀，词藻动星躔。","入幕参军事，含香侍御筵。","符分京兆贵，礼典太常虔。","榷税淮阳郡，司鹾瘴海边。","炎天舟载雪，斥卤灶生烟。","大隐官如水，閒曹吏是仙。","交游盟草泽，啸咏狎林泉。","白屋身能下，缁衣好独偏。","抡才忘牝牡，为政薄鹰鹯。","岂以官情累，都将世味捐。","文章时倡和，杯斝定留连。","车骑谙闾巷，干旄耀市廛。","后生投刺满，多士过门阗。","不辍分题会，宁辞倒屣延。","素心尤恺悌，名理太渊玄。","董子帷常下，江郎笔更鲜。","形骸容放浪，礼数畏拘挛。","结社裁诗律，镌书割俸钱。","考工存旧记，情采著新编。","屈些增吴疏，毛诗补郑笺。","荔枝词脍炙，海错谱流传。","经施庄严寺，僧皈大乘禅。","寄诗怀五岳，留偈榜诸天。","乐府精宫羽，讴吟叶管弦。","两童供墨妙，十吏捧丹铅。","交谊町畦绝，谈锋壁垒坚。","画图摹往哲，俎豆祀高贤。","古道才能尔，今人讵有焉。","使君真岳岳，公子果翩翩。","闽部方推重，辰州急转迁。","悲风寒凛凛，远道思绵绵。","共款襟期隔，还劳梦寐牵。","双旌万里去，五马一城专。","问俗朱轮驾，行春锦绶悬。","家元饶竹箭，庭只挂蒲鞭。","眷顾恩三锡，勋阶禄二千。","辰砂蒐古洞，酉室检残篇。","沅水遥通沔，峒溪近接滇。","鹧鸪闻竹浦，鸡犬觅桃川。","刀剑民争卖，襜帷帝许褰。","逻灯严夜堞，耨火劝春田。","闽楚程难缩，关山阻可怜。","伤离当此日，投分已三年。","邈矣思良晤，凄其念后缘。","歌声宣郁郁，书札订惓惓。","往复虚青简，赓酬散白莲。","感知心独耿，惜别泪空涟。","眠食须珍重，功名合勉旃。","停骖频怅望，何地再周旋。"]},{"t":"仲冬十八日同王玉生陈伯孺幼孺兴公弟送屠田叔使君自芋江登舟至渊关时积雨初收川原竞爽促膝翻书扣舷觅句香绕笔床烟笼茶鼎情景清绝偶忆少陵野航恰受两三人之句因令玉生绘图共拆杜句为韵各赋一体以纪胜游余拈得三字","f":"五言古诗","c":["击汰芋江上，前峰日半含。","山容晴亘翠，水色净拖蓝。","帆饱行偏驶，舲虚坐正堪。","榜歌喧浦口，渔唱隐溪南。","鹳鹤追残照，牛羊下夕岚。","石棱冲浪瘦，枫叶醉霜酣。","沈水香烟细，烹泉茗汁甘。","云霞诸子共，丘壑众情耽。","名理交参伍，新诗改再三。","风波童稚狎，港路长年谙。","身入图中景，人为物外谈。","浣衣临曲渚，洗砚觅深潭。","清福閒能受，玄言静可探。","杜陵诗句好，此境果无惭。"]},{"t":"赠歌姬爱卿十二韵","f":"五言古诗","c":["绮席开华馆，倾城得爱姬。","苑花输靓脸，宫柳学柔肢。","薄鬓琼钗耀，单衫宝带垂。","娇喉歌自啭，长袖舞偏宜。","纤月横蛾翠，轻风馥口脂。","背灯偷卖眼，临镜故颦眉。","性慧藏阄巧，情多度曲迟。","明珰斜粉颈，银钿约冰肌。","旧恨啼难诉，新官对可悲。","暗调通缱绻，微拒掩猜疑。","意洽重逢日，魂销欲别时。","流苏空百结，未足表相思。"]},{"t":"赋得团扇承落花","f":"五言古诗","c":["飞花霞并烂，纨扇月同团。","素影留芳怨，馀香恋合欢。","娇疑障笑比，朱讶掩唇看。","有意迎风易，无声到地难。","胭脂纷点镜，锦绣剪堆盘。","魂向轻罗散，春从薄面残。","班姬方敛恨，闺思况将阑。"]},{"t":"赵仁甫先生以邛竹杖见惠赋此荅谢","f":"五言古诗","c":["种本传西域，曾闻贡汉宫。","一枝非嶰谷，万里出蚕丛。","曳去穿云际，携来到水穷。","节应虚绿土，头可挂青铜。","庄叟逍遥外，卢敖汗漫中。","未尝临俗客，偶尔借邻翁。","采药兼瓢往，挑经与锡同。","静缘幽径曲，诗兴野桥东。","共步添良友，扶颠当小童。","长房吾自愧，君已似壶公。"]},{"t":"子夜歌 其一","f":"五言绝句","c":["牵丝嫌干断，求藕恨泥深。","风吹菡萏折，那得见莲心。"]},{"t":"子夜歌 其二","f":"五言绝句","c":["篱外种都梁，篱内种黄檗。","虽是爱他香，篱心苦难说。"]},{"t":"子夜歌 其三","f":"五言绝句","c":["芙蓉面可怜，卷施心不死。","红豆落深坑，到底相思子。"]},{"t":"子夜歌 其四","f":"五言绝句","c":["锦帐覆雕床，银钩宛相向。","何时得见郎，钩起合欢帐。"]},{"t":"子夜歌 其五","f":"五言绝句","c":["乱却曲中心，只为音徽误。","郎来续旧弦，知移何雁柱。"]},{"t":"子夜歌 其六","f":"五言绝句","c":["采桑饲春茧，叶稀蚕不饱。","一茧着欢衣，与欢绵太少。"]},{"t":"春歌","f":"五言绝句","c":["罗衾与角枕，展转有谁怜。","妾身不如柳，一日尚三眠。"]},{"t":"夏歌","f":"五言绝句","c":["朱夏日何长，采莲向南浦。","妾心未剥莲，只在房中苦。"]},{"t":"秋歌","f":"五言绝句","c":["秋风吹江湄，采芳寄相忆。","妾貌如芙蓉，朝昏几变色。"]},{"t":"冬歌","f":"五言绝句","c":["寒威动房帷，悲风起罗荐。","妾恨井中冰，结时君不见。"]},{"t":"少年行","f":"五言绝句","c":["骏马千金买，银鞍锦障泥。","未谙边塞苦，日日玉楼嘶。"]},{"t":"秋怨","f":"五言绝句","c":["何处飞红叶，深宫不见秋。","可怜双眼泪，空对御沟流。"]},{"t":"魏宫怨","f":"五言绝句","c":["掩袂高台上，春风散绮罗。","西陵望不见，明月照漳河。"]},{"t":"昭君怨","f":"五言绝句","c":["掩泪抛长袖，从今歌舞稀。","肯将边地月，来照汉宫衣。"]},{"t":"玉阶怨","f":"五言绝句","c":["残露侵罗袂，深宫漏正长。","萤光随月影，点点过昭阳。"]},{"t":"别离曲","f":"五言绝句","c":["牵衣赠一言，君还能听否。","但看上林花，莫折章台柳。"]},{"t":"洞房曲","f":"五言绝句","c":["檀郎意憨痴，留灯照绰约。","郎嫌罗帐深，侬嫌罗帐薄。"]},{"t":"新嫁娘","f":"五言绝句","c":["薄帷鉴明月，宛转怜娇态。","郎来解罗裆，含羞掩裙带。"]},{"t":"古意 其一","f":"五言绝句","c":["低声犹掩袖，未许小鬟知。","料应无别语，只是说相思。"]},{"t":"古意 其二","f":"五言绝句","c":["海燕故双栖，池花自连理。","解却红罗襦，知君怜下体。"]},{"t":"古意 其三","f":"五言绝句","c":["巫阳生绣户，春色满雕床。","揉将花瓣碎，分得口脂香。"]},{"t":"怀高凉李大","f":"五言绝句","c":["别梦萦千里，愁心隔五湖。","乱山风雨里，相忆一灯孤。"]},{"t":"寄刘季德","f":"五言绝句","c":["落日催归马，离心寄酒尊。","一从分手后，风雨闭柴门。"]},{"t":"闻雁","f":"五言绝句","c":["忽起芦花渚，哀声入乱云。","空闺多戍妇，莫遣夜深闻。"]},{"t":"自遣","f":"五言绝句","c":["遁迹在空山，生涯寄场圃。","柴门到者稀，满地梨花雨。"]},{"t":"送张叔韬","f":"五言绝句","c":["关门风雨多，相送日云暮。","今宵山馆中，梦绕秦川路。"]},{"t":"逢雪宿华严阁","f":"五言绝句","c":["佛火悬青嶂，钟声下翠微。","萧萧风雪夜，犹有一僧归。"]},{"t":"山馆","f":"五言绝句","c":["地僻稀来往，空山日正长。","晚凉新睡觉，古木自斜阳。"]},{"t":"哭曾大","f":"五言绝句","c":["知音成死别，痛绝壁间琴。","不尽西州感，衡门芳草深。"]},{"t":"山中","f":"五言绝句","c":["散步入空林，斜阳满山麓。","四顾寂无人，蝉声出修竹。"]},{"t":"薄暮","f":"五言绝句","c":["匹马黄沙路，萧萧欲断魂。","天涯多少恨，况乃近黄昏。"]},{"t":"马上","f":"五言绝句","c":["去国八千里，堪嗟行路难。","马头天欲尽，犹不见长安。"]},{"t":"警急","f":"五言绝句","c":["闻说临洮府，今年没敌尘。","愿图恢复策，不必议和亲。"]},{"t":"逢侠者","f":"五言绝句","c":["了不知名姓，偶遇长安市。","片语忽相投，欢然结生死。"]},{"t":"江行杂咏 其一","f":"五言绝句","c":["小径隐丛薄，危桥跨断云。","前林多少树，霜叶落纷纷。"]},{"t":"江行杂咏 其二","f":"五言绝句","c":["江阔帆影迟，夜久砧声歇。","深嶂归暮云，寒波漾明月。"]},{"t":"江行杂咏 其三","f":"五言绝句","c":["暝色沉孤屿，残云冷钓艭。","一声长笛响，秋意满空江。"]},{"t":"江行杂咏 其四","f":"五言绝句","c":["返照有馀景，西风无限情。","暮蝉与孤雁，处处送秋声。"]},{"t":"对雨","f":"五言绝句","c":["寒窗一夜雨，山色几重青。","会得静中意，焚香看道经。"]},{"t":"客中除夕闻钟 其一","f":"五言绝句","c":["客路当除夕，凄凉倍忆家。","钟声何太急，断送旧年华。"]},{"t":"客中除夕闻钟 其二","f":"五言绝句","c":["为客他乡暮，钟声出晓云。","可怜今岁里，只此一回闻。"]},{"t":"送王玉生","f":"五言绝句","c":["作客生涯薄，依人去住难。","春光无限好，空向异乡看。"]},{"t":"江上再送汝高","f":"五言绝句","c":["相送江楼暮，风烟黯自愁。","君行是得意，不敢泪双流。"]},{"t":"客中寒食","f":"五言绝句","c":["去岁燕山道，今朝剑水滨。","如何两寒食，俱作异乡人。"]},{"t":"除夜芝山寺访瀚公","f":"五言绝句","c":["故院知何处，他山度岁华。","空门无去住，有佛即为家。"]},{"t":"寄王震甫","f":"五言绝句","c":["三年巴蜀客，万里故人心。","若比瞿塘水，思君应更深。"]},{"t":"怀郑性之","f":"五言绝句","c":["别去无消息，相思空断魂。","中原多侠客，谁是孟尝门。"]},{"t":"锦溪八景为林熙吉题 其一 团青岛","f":"五言绝句","c":["春风吹锦溪，秀色盘孤岛。","花落满苍苔，莫遣家童扫。"]},{"t":"锦溪八景为林熙吉题 其二 积翠台","f":"五言绝句","c":["振衣陟高台，岚光翠欲滴。","半夜春雨来，飞泉泻石壁。"]},{"t":"锦溪八景为林熙吉题 其三 五云冈","f":"五言绝句","c":["高冈有五石，石石皆生云。","晏坐松根下，前林正夕曛。"]},{"t":"锦溪八景为林熙吉题 其四 七星坞","f":"五言绝句","c":["怪石眠芳藓，危桥傍草亭。","寥寥人境外，花坞带春星。"]},{"t":"锦溪八景为林熙吉题 其五 迁莺林","f":"五言绝句","c":["晓步迁莺林，莺声何睍睆。","把酒坐垂杨，不觉归来晚。"]},{"t":"锦溪八景为林熙吉题 其六 宿猿洞","f":"五言绝句","c":["岘山奇境饶，古洞藏幽谷。","云深不可寻，但借玄猿宿。"]},{"t":"锦溪八景为林熙吉题 其七 萝径门","f":"五言绝句","c":["山中石作门，迫窄不可步。","回首望藤萝，迷却来时路。"]},{"t":"锦溪八景为林熙吉题 其八 松风壑","f":"五言绝句","c":["风生松壑中，涛声聒人耳。","中有绿发翁，长伴赤松子。"]},{"t":"过能仁寺","f":"五言绝句","c":["东郭西天近，禅宫古庙邻。","从今朝暮里，钟鼓一何频。"]},{"t":"题画 其一","f":"五言绝句","c":["日落溪水寒，林疏秋色老。","柴门闭白云，满树丹枫老。"]},{"t":"题画 其二","f":"五言绝句","c":["森森灌木阴，渺渺澄江静。","一棹独垂纶，中流钓山影。"]},{"t":"题画 其三","f":"五言绝句","c":["振衣危峰巅，扶桑日初起。","柳色破青烟，桃花带流水。"]},{"t":"江上漫成","f":"五言绝句","c":["游人恋故乡，每恨离家远。","如何石尤风，又叹舟行晚。"]},{"t":"西寺寻公朗上人因同宿小舟","f":"五言绝句","c":["寻僧入招提，斜阳下疏木。","只恐隔关门，同到舟中宿。"]},{"t":"记梦","f":"五言绝句","c":["梦与双亲别，牵衣两泪垂。","不知成永隔，犹道暂相离。"]},{"t":"送吴翁晋还吴兴","f":"五言绝句","c":["如何布衣至，依旧布衣归。","且向苕溪曲，三年守钓矶。"]},{"t":"失剑","f":"五言绝句","c":["恩雠俱未报，失去竞何心。","难将延陵剑，不及少原簪。"]},{"t":"得剑","f":"五言绝句","c":["神物合雄雌，归来事太奇。","精光犹未灭，会有报恩时。"]},{"t":"漂母祠","f":"五言绝句","c":["落落千金报，悠悠国士心。","从今惭漂母，不敢过淮阴。"]},{"t":"归渡扬子江","f":"五言绝句","c":["归来风波平，去日风波作。","世路非风波，来往风波恶。"]},{"t":"吴门逢郑四","f":"五言绝句","c":["几载天涯别，逢君空自悲。","知无桑梓念，不敢问归期。"]},{"t":"将至武夷","f":"五言绝句","c":["莫谓仙源近，舟回路几重。","他山苦相蔽，不见大王峰。"]},{"t":"咏残灯","f":"五言绝句","c":["空房心胆怯，灯影半将残。","揽衣频起剔，扬彩伴更阑。"]},{"t":"山行口占题建溪驿壁","f":"五言绝句","c":["客路当残岁，凄然正忆家。","山童不解事，停马折梅花。"]},{"t":"题邬子远扇面山水","f":"五言绝句","c":["长松荫远山，虚亭倚危石。","何来客杖藜，曳破秋云碧。"]},{"t":"题梅花画扇","f":"五言绝句","c":["春信江南早，凄然念故乡。","忽看纨扇影，转忆寿阳妆。"]},{"t":"吕梁洪","f":"五言绝句","c":["吕梁洪下水，已变作安流。","安流虽自好，只是滞归舟。"]},{"t":"题沈从先扇面画兰","f":"五言绝句","c":["国香零落久，幽谷忽成丛。","移向齐纨上，期君臭味同。"]},{"t":"题公朗扇上画梅","f":"五言绝句","c":["纨扇写寒梅，怀袖微香发。","山僧骨相清，对之双幽绝。"]},{"t":"回文诗","f":"五言绝句","c":["绿波回断港，青嶂荫孤村。","谷萝开乱莽，汀浪浸疏园。"]},{"t":"芋江驿楼口占送王元直重游金陵 其一","f":"五言绝句","c":["掩泪怀前事，送君无限悲。","经过多旧处，何处更相思。"]},{"t":"芋江驿楼口占送王元直重游金陵 其二","f":"五言绝句","c":["夜月乌衣巷，秋风燕子矶。","山川仍似昔，只是旧人非。"]},{"t":"舟中杂言 其一","f":"古风","c":["白云一片两片，翠微千重万重。","孤客尚馀短剑，青山何处疏钟。"]},{"t":"舟中杂言 其二","f":"古风","c":["处处桃花欲笑，枝枝柳叶含颦。","白璧卞和泣楚，黑貂季子归秦。"]},{"t":"舟中杂言 其三","f":"古风","c":["云外疏星点点，沙边小艇双双。","一曲孤琴有谱，数声长笛无腔。"]},{"t":"舟中杂言 其四","f":"古风","c":["云际鹧鸪格磔，花前蝴蝶蹁跹。","隔岸野桥跨水，空山古墓犁田。"]},{"t":"题伯孺画小景","f":"古风","c":["天际孤舟带雨，沙边竹杖穿云。","村落半藏宿莽，危亭独瞰江濆。"]},{"t":"戊子除夕饮顾道行先生谐赏园 其一","f":"古风","c":["游子惊闻爆竹，高堂谁荐椒花。","谐赏园中地主，姑苏城外天涯。"]},{"t":"戊子除夕饮顾道行先生谐赏园 其二","f":"古风","c":["白雁久无家信，青袍虚度年光。","自觉梦中是客，何言醉处为乡。"]},{"t":"题画寄闵寿卿 其一","f":"古风","c":["溪路一曲二曲，人烟三家两家。","野饭唯供涧藻，山衣自缉园麻。"]},{"t":"题画寄闵寿卿 其二","f":"古风","c":["草阁云生云灭，柴门风闭风开。","峰影溪中流去，瀑声天外飞来。"]},{"t":"山居四时词 其一","f":"古风","c":["楼外桃飘红雨，阶前苔绣青毡。","燕影差池似剪，莺声睍睆如弦。"]},{"t":"山居四时词 其二","f":"古风","c":["乱蝉争噪高柳，倦鸟独栖古篁。","新茗半瓯睡起，枯棋一局斜阳。"]},{"t":"山居四时词 其三","f":"古风","c":["天末金风荐爽，夜深玉露生寒。","黄菊含苞欲吐，芙蓉褪粉将残。"]}]};